    def test_tools_that_were_windows_are_works_of_the_main_window(self):
        """The user, 2026-10-16 (#311-#313): Events, Mercenaries, Rebels, Traits and Campaign rules are works of the
        main window, not windows of their own: each a gui_util.Page (the window manager's calls do nothing), made by
        its module's make_page (None without a mod), shown on the work bar."""
        try:
            import tkinter as tk
            from campaign_editor.gui import App
            root = tk.Tk()
        except Exception as e:
            self.skipTest("no window: %s" % e)
        from importlib import import_module
        from types import SimpleNamespace
        from campaign_editor import gui_util as GU
        try:
            names = {"rules": "RulesWindow", "events": "EventsWindow", "traits": "TraitsWindow",
                     "mercs": "MercPage", "rebels": "RebelsPage", "recolour": "RecolourPage"}
            self.assertEqual(set(App.PAGE_WORKS), set(names))
            for key, mod in App.PAGE_WORKS.items():
                m = import_module("campaign_editor." + mod)
                self.assertTrue(issubclass(getattr(m, names[key]), GU.Page), key)
                self.assertIsNone(m.make_page(SimpleNamespace(mod=None)))
                self.assertIn(key, App.WORK_TITLES)
                self.assertNotIn(key, [k for k, *_ in App.WINDOW_BUTTONS])
            page = GU.Page(root)
            for call in (page.title, page.transient, page.geometry, page.minsize, page.protocol, page.withdraw,
                         page.deiconify):
                call()
            self.assertEqual((page.dirty(), page.pending(), page.rebind(None)), (False, 0, 0))
            closed = []
            page.app = SimpleNamespace(page_closed=closed.append)
            page.destroy()
            self.assertEqual(closed, [page])
        finally:
            root.destroy()

    def test_imported_card_size_picked_like_make_a_card(self):
        """A Stainless Steel modder's wish (PICTURE RESOLUTION): Import... of a card / info picture offers the mod's
        own size, x2 to x4 or the file's own (was: resize yes / no), the pick kept for the next one."""
        try:
            from campaign_editor import gui_editors as GE
        except ImportError as e:
            self.skipTest("no tkinter: %s" % e)
        from campaign_editor import settings
        asked, pick = [], [2]
        old = GE.ask_choice
        GE.ask_choice = lambda parent, title, text, words, **kw: (asked.append((words, kw)), pick[0])[1]
        was = settings.get("card_scale")
        try:
            got = GE.RecordEditor._pick_size(None, "a.tga", (200, 260), (48, 64), False)
            self.assertEqual(got, (144, 192))                          # x3
            self.assertEqual(settings.get("card_scale"), 3)
            self.assertEqual(len(asked[0][0]), 5)
            self.assertEqual(GE.RecordEditor._pick_size(None, "b.tga", (144, 192), (48, 64), False), (144, 192))
            self.assertEqual(len(asked), 1)                            # already the size picked: not asked
            pick[0] = 4
            self.assertIsNone(GE.RecordEditor._pick_size(None, "c.tga", (10, 10), (48, 64), False))    # its own
            pick[0] = None
            self.assertIs(GE.RecordEditor._pick_size(None, "d.tga", (10, 10), (48, 64), False), False)
        finally:
            GE.ask_choice = old
            settings.put("card_scale", was if was is not None else 1)

    def test_watchtower_follows_its_repainted_land(self):
        """Report #181 (the web): a repaint giving a watchtower's tile to another region left its line under the old
        region's block - the game skips it ('does not match up to region name'). It moves into the new region's
        block (made when missing); painted into the sea, it is said."""
        from campaign_editor import forts as FO
        from campaign_editor.regionedit import SEA
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        write(os.path.join(camp, "descr_strat.txt"), STRAT +
              "\n; >>>> start of regions section <<<<\n\nregion A_R\nroad_level 0\nfarming_level 0\nfamine_threat 0\n"
              "watchtower \t5 5\nwatchtower \t1 6\n\nregion B_R\nroad_level 0\nfarming_level 0\nfamine_threat 0\n"
              "watchtower \t6 1\n")
        mod = ModData(self.root)
        plan = Plan(mod, "map", "map", {})
        FO.follow_repaint(plan, "test", {(5, 5): "B_R", (1, 6): SEA, (2, 2): "B_R"})
        f = plan.edit(mod.campaign_file("test", "descr_strat.txt"))
        text = "\n".join(f.texts())
        tail = text[text.index("start of regions section"):]
        self.assertNotIn("5 5", tail[:tail.index("region B_R")])
        self.assertIn("watchtower \t5 5", tail[tail.index("region B_R"):])
        self.assertIn("1 6", tail[:tail.index("region B_R")])                 # in the sea: left, said
        self.assertTrue(any("sea" in w for _, w in plan.warnings), plan.warnings)

    def test_last_town_given_away_its_general_steps_out(self):
        """Report #306: giving a faction's last town away with its general inside was refused ('has no other town to
        go to' - give it another town first, Apply, then again). He steps out onto a free tile beside the town, as
        the game leaves a faction with no town: its army in the field, said in a warning."""
        from campaign_editor.edit import map_changes
        mod = ModData(self.root)
