    def test_rename_faction_reaches_glued_names_and_the_games_files(self):
        """Report R-20261009-CDDAF0 (the test mod on Medieval II with M2EX): venice renamed venice_ce, then the game
        closed at start - 'Unknown attribute type(Combat_V_Faction_Venice)': the trait effect glues the faction's
        name to Combat_V_Faction_ and was not taken for its name. And in a thin mod a file only the game's data has
        must be renamed too - into the mod's own copy, the game's file untouched. Report #186: the campaign script
        named venice still ('venice' is not a known faction, thousands of times) - it follows now."""
        from campaign_editor import factionrename as FR
        game, _ = self._game()
        traits = os.path.join(game, "data", "export_descr_character_traits.txt")
        write(traits, "Trait Fearsalpha\n    Characters family\n\n    Level Afraid\n"
                      "        Effect Combat_V_Faction_Alpha -1 \n        Effect Combat_V_Faction_alphabet 1\n"
                      ";------------------------------------------\nTrigger t1\n    WhenToTest PreBattle\n"
                      "    Condition FactionType alpha\n")
        before = open(traits).read()
        camp = os.path.join(game, "data", "world", "maps", "campaign", "test")
        write(os.path.join(camp, "campaign_script.txt"), "script\n\tif I_LocalFaction alpha\n\t\tset_counter "
              "alpha_intro 1\n\tend_if\nend_script\n")
        write(os.path.join(game, "data", "scripts_alpha.nut"), "local f = \"alpha\";\n")
        data, _ = create_mod(os.path.join(game, "data"), "Beta")
        mod = ModData(data)
        plan = Plan(mod, "rename", "alpha_ce", {})
        FR.plan_rename(plan, "test", "alpha", "alpha_ce")
        # report #186: the campaign script follows (a word of its own; alpha_intro is another name); a Squirrel
        # script is only named
        self.assertTrue(any("scripts_alpha.nut" in w for _, w in plan.warnings), plan.warnings)
        plan.apply()
        with open(os.path.join(data, "world", "maps", "campaign", "test", "campaign_script.txt")) as fh:
            self.assertEqual(fh.read(), "script\n\tif I_LocalFaction alpha_ce\n\t\tset_counter alpha_intro 1\n"
                                        "\tend_if\nend_script\n")
        self.assertEqual(open(traits).read(), before)                       # the game's own file untouched
        mine = open(os.path.join(data, "export_descr_character_traits.txt")).read()
        self.assertIn("Effect Combat_V_Faction_Alpha_ce -1", mine)          # the case as written
        self.assertIn("Combat_V_Faction_alphabet 1", mine)                 # another name, left
        self.assertIn("Condition FactionType alpha_ce", mine)
        self.assertIn("Trait Fearsalpha", mine)                            # a trait's own name stays

    def test_recolour_finds_the_templates_cards_under_a_thin_mod(self):
        """Report R-20261009-4D53CB (the test mod on Rome with REX): a clone's cards stayed its template's red after
        Recolour - in a thin mod the template's cards lie in the game's data only, so none was found to compare with
        and the cards were taken for the clone's own colours. The game's own data counts too."""
        from campaign_editor import recolour as R
        game, _ = self._game()
        data, _ = create_mod(os.path.join(game, "data"), "Beta")
        build(ModData(data), "test", "alpha", "beta", {"start": {"regions": ["B_R"], "leader": {"name": "Boris"}}}).apply()
        cards = [it for it in R.targets(ModData(data), "test", "beta")
                 if not isinstance(it, str) and it["group"] == "unit cards" and it["rel"].endswith("#alpha_general.tga")]
        self.assertTrue(cards)
        self.assertIn("alpha", cards[0]["of"])
        self.assertTrue(cards[0]["others"][cards[0]["of"].index("alpha")][0].startswith(os.path.join(game, "data")))

    def test_from_another_mod_lists_only_mods_of_the_same_game(self):
        """Report #274: with a Medieval II mod loaded, Bring buildings listed Rome's mods (bi among them) and picking
        one only brought 'buildings go between mods of one game'. The 'from another mod' windows list only mods of
        the loaded game, the loaded one left out."""
        from types import SimpleNamespace
        from campaign_editor import packs
        with tempfile.TemporaryDirectory() as t:
            rome, m2 = os.path.join(t, "Rome Total War Gold"), os.path.join(t, "Medieval II Total War")
            for game, exe in ((rome, "REX.exe"), (m2, "M2EX.exe")):
                os.makedirs(os.path.join(game, "data"))
                write(os.path.join(game, exe), "")
            for d in (os.path.join(rome, "bi", "data"), os.path.join(m2, "mods", "a", "data"),
                      os.path.join(m2, "mods", "b", "data")):
                os.makedirs(d)
            mods = [("Rome: (the game)", os.path.join(rome, "data")), ("Rome: bi", os.path.join(rome, "bi", "data")),
                    ("M2: (the game)", os.path.join(m2, "data")), ("M2: a", os.path.join(m2, "mods", "a", "data")),
                    ("M2: b", os.path.join(m2, "mods", "b", "data"))]
            here = SimpleNamespace(data=os.path.join(m2, "mods", "a", "data"))
            self.assertEqual([lab for lab, _ in packs.same_game_mods(mods, here)], ["M2: (the game)", "M2: b"])
            here = SimpleNamespace(data=os.path.join(rome, "data"))
            self.assertEqual([lab for lab, _ in packs.same_game_mods(mods, here)], ["Rome: bi"])

    def test_report_mod_file_list_not_sent_again_unchanged(self):
        """Report #269: the mod's file list went with every report, like a log sent already - now it stays unticked
        when it went with an earlier report and the editor has not written the mod since (a new backup = changed)."""
        from campaign_editor import report, settings
        from campaign_editor.plan import BACKUP_DIR
        saved = dict(settings.get("reports_sent_files") or {})
        self.addCleanup(settings.put, "reports_sent_files", saved)
        mod = ModData(self.root)
        settings.put("reports_sent_files", {})
        self.assertIsNone(report.files_sent(mod))
        report.remember_files_sent(mod, "R-20261015-AAAAAA")
        self.assertEqual(report.files_sent(mod), "R-20261015-AAAAAA")
        bdir = os.path.join(self.root, BACKUP_DIR, "20991231_000000_x")          # the editor wrote the mod
        os.makedirs(bdir)
        later = time.time() + 120
        os.utime(bdir, (later, later))
        self.assertIsNone(report.files_sent(mod))
        self.assertIsNone(report.files_sent(None))

    def test_brought_recruit_line_drops_unknown_factionwide_resources(self):
        """Report #285: Gaul units brought from HLR into Barbarian Invasion stopped the game at start ('Script Error in
        export_descr_buildings.txt, line 50, column 100'): HLR writes 'hidden_resource alpine factionwide' and the
        word after the name hid the condition from the check - the resource BI does not have stayed in."""
        from campaign_editor.packs import fit_line
        known = {"hidden_resource": {"spain"}, "resource": None, "religion": None}
        line = ('recruit "barb infantry slave"  0  requires factions { celts, } and hidden_resource alpine factionwide'
                ' or hidden_resource briton factionwide')
        got, gone = fit_line(line, known)
        self.assertEqual(gone, ["hidden_resource alpine factionwide", "hidden_resource briton factionwide"])
        self.assertNotIn("alpine", got)
        self.assertIn("factions { celts, }", got)
        got, _ = fit_line('recruit "x"  0  requires factions { celts, } and hidden_resource alpine factionwide or '
                          'hidden_resource spain factionwide', known)
        self.assertTrue(got.endswith("factions { celts, } and hidden_resource spain factionwide"), got)  # never 'or'
        from campaign_editor.packs import cut_words
        words = cut_words(["hidden_resource alpine factionwide", "hidden_resource briton factionwide",
                           "not resource camels"], "units", "recruit lines")
        self.assertIn("hidden resources alpine, briton (", words)
        self.assertIn("resources camels (", words)
        self.assertIn("the game does not stop at start", words)
        got, gone = fit_line('recruit "x"  0  requires factions { celts, }  and hidden_resource spain factionwide',
                             known)
        self.assertEqual(gone, [])                                      # a resource this mod has stays, whole

    def test_recolour_brush_dab_never_has_its_right_edge_before_its_left(self):
        """Report #281: painting by hand in Recolour stopped with 'x1 must be greater than or equal to x0' - the
        points are the shown picture's divided by its scale (fractions) and a size-1 dab's right edge came out a
        hair left of its left edge."""
        from campaign_editor import recolour as R
        for k in (7, 3, 2.5, 1.3):
            for i in range(400):
                for size in (0, 1, 2, 5):
                    x0, y0, x1, y1 = R.dab(i / k, (i * 3) / k, size)
                    self.assertGreaterEqual(x1, x0)
                    self.assertGreaterEqual(y1, y0)
        self.assertEqual(R.dab(10, 10, 4), (8.0, 8.0, 11.0, 11.0))

    def test_recolour_kept_for_a_faction_not_created_yet_finds_its_copies(self):
        """Report #224: Recolour while making a faction said 'create it first'. The window shows the template's
        pictures; at the write (after the faction part) the ticked ones are found among the new faction's own copies
        by their names (template -> new) - or the very file it shares with the template."""
        from campaign_editor import recolour as R
        game, _ = self._game()
        data, _ = create_mod(os.path.join(game, "data"), "Beta")
        before = [it for it in R.targets(ModData(data), "test", "alpha") if not isinstance(it, str)]
        want = set().union(*(R.renamed_rels(it["rel"], "alpha", "beta") for it in before))
        self.assertIn("data/ui/units/beta/#alpha_general.tga", want)         # the card keeps its name, own folder
        build(ModData(data), "test", "alpha", "beta", {"start": {"regions": ["B_R"], "leader": {"name": "Boris"}}}).apply()
        after = [it for it in R.targets(ModData(data), "test", "beta") if not isinstance(it, str)]
        self.assertTrue(after)
        self.assertEqual(len([it for it in after if R.plain_rel(it["rel"]) in want]), len(after))

    def test_thin_mod_gets_its_whole_map_folder_on_a_map_change(self):
        """A thin mod's first map change (a town deleted with its region) brings the game's other map layers into the
        mod - but map.rwm, which the game builds again from the mod's map, and never the campaign's untouched texts
        (the user, 2026-10-20: copies of the game's files shadow a modder's own); the game's files are never written;
        Restore takes the mod back to nothing."""
        from campaign_editor import regiondelete as RD
        game, _ = self._game()
        camp_game = os.path.join(game, "data", "world", "maps", "campaign", "test")
        write(os.path.join(camp_game, "map.rwm"), "old map cache")
        write(os.path.join(camp_game, "descr_events.txt"), "; no events\n")
        game_before = tree_hash(os.path.join(game, "data"))
        data, _ = create_mod(os.path.join(game, "data"), "Beta")
        mod = ModData(data)
        plan = Plan(mod, "delete", "B_R", {})
        RD.delete(plan, "test", "B_R", "A_R")
        plan.apply()
        camp = os.path.join(data, "world", "maps", "campaign", "test")
        have = sorted(os.listdir(camp))
        for name in ("map_regions.tga", "descr_regions.txt", "descr_strat.txt"):
            self.assertIn(name, have)
        self.assertNotIn("map.rwm", have)                               # built again by the game from the mod's map
        for name in ("descr_events.txt", "descr_win_conditions.txt"):  # never changed: still read from the game
            self.assertNotIn(name, have)
        self.assertEqual(tree_hash(os.path.join(game, "data")), game_before)     # the game's own files untouched
        self.assertNotIn("B_R", ModData(data).regions("test"))
        for b in backups(ModData(data)):
            restore(ModData(data), b)
        self.assertEqual([n for _, _, fs in os.walk(data) for n in fs], [])

    def test_thin_mod_redrawn_faction_map_brings_no_campaign_files(self):
        """A redrawn faction-select map (map_<faction>.tga) is a picture of the campaign, not a map layer: the thin mod
        gets that one picture, never the campaign's descr_strat, events or other files (they would shadow the modder's
        own - the user, 2026-10-20)."""
        game, _ = self._game()
        camp_game = os.path.join(game, "data", "world", "maps", "campaign", "test")
        write(os.path.join(camp_game, "map_alpha.tga"), "picture")
        write(os.path.join(camp_game, "descr_events.txt"), "; no events\n")
        data, _ = create_mod(os.path.join(game, "data"), "Beta")
        mod = ModData(data)
        plan = Plan(mod, "art", "alpha", {})
        plan.binary(os.path.join(camp_game, "map_alpha.tga"), b"new picture")
        plan.apply()
        camp = os.path.join(data, "world", "maps", "campaign", "test")
        self.assertEqual(sorted(os.listdir(camp)), ["map_alpha.tga"])

    def test_thin_mod_game_bytes_and_read_only_files_never_copied(self):
        """A thin mod gets no copy of a game's file the write leaves as it is (the user, 2026-10-20): a picture written
        with the game's very bytes is no change, and a game's descr_strat only read is never 'put right' by the
        keep-ups (here: a later faction holding a town would be made alive) - so nothing at all lands in the mod."""
        game, _ = self._game()
        strat_game = os.path.join(game, "data", "world", "maps", "campaign", "test", "descr_strat.txt")
        with open(strat_game, encoding="utf-8") as f:
            text = f.read()
        write(strat_game, text.replace("faction\talpha, balanced smith\n", "faction\talpha, balanced smith\n"
                                       "dead_until_resurrected\n", 1))
        pic = os.path.join(game, "data", "world", "maps", "campaign", "test", "map_alpha.tga")
        write(pic, "picture")
        data, _ = create_mod(os.path.join(game, "data"), "Beta")
        mod = ModData(data)
        plan = Plan(mod, "x", "alpha", {})
        plan.edit(strat_game)                                           # read for the change, left as it is
        with open(pic, "rb") as f:
            plan.binary(pic, f.read())                                  # the game's own bytes
        self.assertEqual(plan.changed_files(), [])
        plan.apply()
        self.assertEqual([n for _, _, fs in os.walk(data) for n in fs], [])

