    def test_select_map_drawn_from_the_campaign_map(self):
        """The user, 2026-10-14: the faction-select map made from the campaign map itself - relief and rivers, no
        signs - with the faction's land filled with its colour at 50 % (2026-10-15: a full fill 'looked ugly', 75 % still a full fill), no
        borders inside it; a campaign without select pictures to learn from gets one too (384 wide, the map's
        shape)."""
        try:
            import PIL  # noqa: F401
        except ImportError:
            self.skipTest("no Pillow")
        from campaign_editor import factionart as FA
        mod = ModData(self.root)
        regions = list(mod.regions("test"))
        im = FA.map_drawing(mod, "test", regions[:1], (200, 10, 10))
        img = mod.region_map("test")
        self.assertEqual(im.size, (384, round(384 * img.height / img.width)))
        x, y = mod.city_tiles("test")[regions[0]]
        px = im.getpixel((int((x + 0.5) * im.width / img.width), int((img.height - 1 - y + 0.5) * im.height /
                                                                         img.height)))
        bare = FA.map_drawing(mod, "test", [], (200, 10, 10)).getpixel(
            (int((x + 0.5) * im.width / img.width), int((img.height - 1 - y + 0.5) * im.height / img.height)))
        want = tuple(round(0.5 * b + 0.5 * c) for b, c in zip(bare, (200, 10, 10)))
        self.assertTrue(all(abs(a - b) <= 3 for a, b in zip(px, want)), (px, want))   # 50 %: the land shows through
        x2, y2 = mod.city_tiles("test")[regions[1]]
        other = im.getpixel((int((x2 + 0.5) * im.width / img.width), int((img.height - 1 - y2 + 0.5) * im.height /
                                                                            img.height)))
        self.assertNotEqual(other, (200, 10, 10))                     # another faction's land: the map as it is

    def test_locked_factions_opened_on_load(self):
        """The user, 2026-10-15: on loading a game whose campaign keeps factions locked (unlockable / nonplayable),
        offer to open them - into the playable list, with a backup; the Senate, the Pope, the rebels and factions
        with no town at the start (dead on turn one) stay as they are."""
        from campaign_editor import gamefix
        from campaign_editor.strat import Strat
        from campaign_editor.textio import TextFile
        strat = os.path.join(self.root, "data", "world", "maps", "campaign", "test", "descr_strat.txt")
        text = open(strat).read()
        text = text.replace("playable\n\talpha\nend\nunlockable\nend\nnonplayable\n\tslave\nend",
                            "playable\n\tbeta\nend\nunlockable\n\talpha\nend\nnonplayable\n\tgamma\n\tslave\n"
                            "\tromans_senate\nend", 1)
        write(strat, text)
        before = tree_hash(self.root)
        mod = ModData(self.root)
        self.assertEqual(gamefix.locked_factions(mod, "test"), ["alpha"])      # gamma has no town, slave stays
        found = [p for p in gamefix.problems(mod, on_load=True) if p["id"].startswith("locked_factions")]
        self.assertEqual(len(found), 1)
        self.assertIn("alpha", found[0]["why"])
        bdir = gamefix.fix_plan(mod, found).apply()
        s = Strat(TextFile.load(strat))
        self.assertEqual([n for _, n in s.playable["items"]], ["beta", "alpha"])
        self.assertEqual([n for _, n in s.unlockable["items"]], [])
        self.assertEqual([n for _, n in s.nonplayable["items"]], ["gamma", "slave", "romans_senate"])
        self.assertEqual(gamefix.locked_factions(ModData(self.root), "test"), [])    # not asked again
        restore(ModData(self.root), bdir)
        after = {k: v for k, v in tree_hash(self.root).items() if "_backups" not in k}
        self.assertEqual(after, before)

    def test_select_map_outline_smooth_without_a_picture_from_above(self):
        """Report #271 (Barbarian Invasion): with no picture from above the select map was drawn on the editor's own
        map picture - a pixel or two a tile - and the faction's outline came out in tile steps. It is rounded on a
        picture 6 pixels a tile now, as with the picture from above."""
        try:
            from PIL import ImageChops
        except ImportError:
            self.skipTest("no Pillow")
        from unittest import mock
        import contextlib
        from campaign_editor import factionart as FA
        from campaign_editor.minimod import write_tga
        try:                                       # without NumPy there is no picture from above at all
            from campaign_editor import minimap
            no_view = mock.patch.object(minimap, "top_view", side_effect=ValueError("no heights"))
        except ImportError:
            no_view = contextlib.nullcontext()
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        R, B, K = (255, 0, 0), (0, 0, 255), (0, 0, 0)
        px = [[R if x + y < 9 else B for x in range(12)] for y in range(8)]      # a slanting border
        px[1][1], px[5][9] = K, K
        write_tga(os.path.join(camp, "map_regions.tga"), 12, 8, px)
        mod = ModData(self.root)
        with no_view:
            im = FA.map_drawing(mod, "test", ["A_R"], (200, 10, 10), size=(384, 384))
            bare = FA.map_drawing(mod, "test", [], (200, 10, 10), size=(384, 384))
        diff = ImageChops.difference(im, bare).convert("L").point(lambda v: 255 if v > 30 else 0)
        img = mod.region_map("test")
        tile = 384 / img.width
        # where the faction's area starts on each row: not only on the tiles' edges (stair steps) but between them
        starts = set()
        for y in range(384):
            row = [diff.getpixel((x, y)) for x in range(384)]
            if 255 in row and 0 in row[row.index(255):]:
                starts.add(len(row) - 1 - row[::-1].index(255))          # where the area ends on the row
        off_grid = [x for x in starts if min(x % tile, tile - x % tile) > 1.5]
        self.assertTrue(off_grid, sorted(starts))

    def test_select_map_drawn_inside_the_games_frame(self):
        """The user, 2026-10-15: Medieval II's faction-select pictures have a rope frame round the map - the drawing
        replaces the map only and fits inside the frame; the frame stays the game's own. A picture with no frame
        (Rome) is the map from edge to edge."""
        try:
            from PIL import Image, ImageDraw
        except ImportError:
            self.skipTest("no Pillow")
        from unittest import mock
        from campaign_editor import factionart as FA
        bg = Image.new("RGB", (384, 275), (150, 140, 120))
        d = ImageDraw.Draw(bg)
        for k in range(11):                                  # rope: light and dark stripes, dark lines at 1-2 and 9-10
            shade = (58, 58, 58) if k in (1, 2, 9, 10) else ((200, 190, 170) if k % 2 else (120, 110, 90))
            d.rectangle((k, k, 383 - k, 274 - k), outline=shade)
        self.assertEqual(FA.select_inner(bg), (11, 11, 373, 264))
        self.assertEqual(FA.select_inner(Image.new("RGB", (384, 237), (90, 120, 160))), (0, 0, 384, 237))
        mod = ModData(self.root)
        img = mod.region_map("test")
        with mock.patch.object(FA, "select_background", return_value=(bg, "map_x.tga")), \
                mock.patch.object(FA, "select_frame", return_value=(500 / img.width, 400 / img.height, -60, -40)):
            im = FA.map_drawing(mod, "test", list(mod.regions("test"))[:1], (200, 10, 10))
        self.assertEqual(im.size, bg.size)
        for xy in ((0, 0), (5, 137), (383, 274), (190, 270), (378, 100)):
            self.assertEqual(im.getpixel(xy), bg.getpixel(xy), xy)          # the frame untouched
        self.assertNotEqual(im.getpixel((190, 137)), bg.getpixel((190, 137)))   # the map inside drawn anew

