    def test_levels_a_faction_never_reaches_are_found(self):
        """A faction's towns grow only as far as the highest governor's building it may build (vanilla Rome's
        barbarians: a city); a level needing a bigger settlement (the large temples, large / huge city) is out of
        its reach - the Buildings tab leaves it out and says so."""
        from campaign_editor.buildings import Building, Level, out_of_reach, top_settlement
        core = Building("core_building")
        for name, fs, smin in (("house", "roman, barbarian,", "village"), ("villa", "roman, barbarian,", "town"),
                               ("palace", "roman, barbarian,", "large_town"), ("proconsul", "roman,", "city"),
                               ("imperial", "roman,", "large_city")):
            lv = Level(name, "factions { %s }" % fs)
            lv.settlement_min = smin
            core.levels.append(lv)
        self.assertEqual(top_settlement([core], "gauls", "barbarian"), "city")
        self.assertEqual(top_settlement([core], "julii", "roman"), "huge_city")
        temple = Level("pantheon", "")
        temple.settlement_min = "large_city"
        self.assertTrue(out_of_reach(temple, "city"))
        self.assertFalse(out_of_reach(temple, "huge_city"))
        self.assertFalse(out_of_reach(temple, None))

    def test_emblem_makes_medieval_banner_sheet_from_the_white_template(self):
        """Emblem everywhere, Medieval II (the plan's step 3, his 'да'): the faction's battle banner sheet (every banner
        shape of its units, banners/textures/faction_banner_<f>) is made with the emblem - the white template of the
        mod's sheets dyed in the colours with the symbol on each shape (banners_m2.Kit); a sheet other factions share
        is offered too (it becomes the faction's own copy); the rebels' sheet never."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("Pillow is not installed")
        from campaign_editor import emblem as E
        path = os.path.join(self.root, "faction_banner_milan.tga")
        Image.new("RGBA", (8, 4), (9, 9, 9, 255)).save(path)
        sheet = {"label": "battle banner faction_banner_milan.texture", "rel": "banners/textures/faction_banner_milan"
                 ".texture", "path": path, "locked": True, "size": (8, 4),
                 "extra": {"kind": "banner", "ref": "banners/textures/faction_banner_milan.texture"}}
        rebels = dict(sheet, label="battle banner faction_banner_rebels.texture", rel="banners/textures/"
                      "faction_banner_rebels.texture", path=path.replace("milan", "rebels"))
        Image.new("RGBA", (8, 4)).save(rebels["path"])
        self.assertEqual([p["rel"] for p in E.emblem_pictures([sheet, rebels])], [sheet["rel"]])
        asked = []

        class Kit:
            def make(self, s, symbol):
                asked.append((s, symbol))
                return Image.new("RGBA", (8, 4), tuple(s["colours"][0]) + (255,))
        sym = Image.new("RGBA", (4, 4), (255, 255, 255, 255))
        got = E.build(sym, [sheet], sym, {"kit": Kit(), "colours": [(10, 20, 30), (1, 1, 1)], "pattern": "plain"})
        self.assertEqual(got[sheet["rel"]].getpixel((0, 0)), (10, 20, 30, 255))
        self.assertEqual(asked[0][0], {"colours": [(10, 20, 30), (1, 1, 1)], "pattern": "plain"})
        self.assertIs(asked[0][1], sym)                                # the symbol on every shape
        self.assertEqual(E.build(sym, [sheet], sym, None), {})           # no white template: left as it is

    def test_emblem_reaches_town_flags_3d_symbol_and_captain_cards(self):
        """One symbol on every flag of the faction (Rome), each from a WHITE TEMPLATE (the user, 2026-10-15: 'do not
        repaint - white templates like the routing flags'): the town flag = the blank banner dyed, the 3D symbol =
        its white square flag dyed, the captain's card = the old card with its cloth made the white cloth, then dyed
        - the pole kept. The rebels' and the routing flags are never touched."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("no Pillow")
        from campaign_editor import emblem as E
        blank = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
        blank.paste(Image.new("RGBA", (12, 40), (235, 235, 235, 255)), (2, 2))    # the pennant
        blank.paste(Image.new("RGBA", (30, 30), (235, 235, 235, 255)), (30, 2))   # the square flag
        self.assertEqual(E.square_flag(blank), (30, 2, 60, 32))
        old_std = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
        old_std.paste(Image.new("RGBA", (30, 30), (180, 20, 20, 255)), (30, 2))
        card = Image.new("RGBA", (20, 30), (90, 90, 90, 255))
        card.paste(Image.new("RGBA", (12, 14), (175, 25, 22, 255)), (6, 3))       # the red cloth on a grey pole
        tpl, mask, box = E.white_template(card, E.cloth_colour(old_std), E.white_square(blank))
        self.assertEqual(tpl.getpixel((10, 8))[:3], (235, 235, 235))            # the template: white cloth
        st = {"colours": [(20, 40, 200)], "pattern": "plain"}
        for label, old, want in (("flag on its towns in battle", Image.new("RGBA", (32, 32)), (32, 32)),
                                 ("faction symbol (3D) texture", Image.new("RGBA", (16, 16)), (16, 16)),
                                 ("captain's card", card, (20, 30))):
            got = E.flag_pictures({"label": label}, old, blank, st, None, old_std)
            self.assertEqual(got.size, want)
        got = E.flag_pictures({"label": "captain's card"}, card, blank, st, None, old_std)
        self.assertEqual(got.getpixel((10, 8))[:3], (20, 40, 200))              # dyed from the white template
        self.assertEqual(got.getpixel((1, 25))[:3], (90, 90, 90))               # the rest as it was
        rebel = {"label": "flag on its towns in battle", "rel": "models_building/textures/##standard_slave.tga"}
        self.assertTrue(E._rebels_flag(rebel))

