    def test_button_state_pictures_set_added_and_taken_out(self):
        """Interface: the pictures of a UI object's states (normal, mouse over, pressed, ticked) - one changed, one
        added as a copy of the last, one taken out (the file back byte for byte); the only picture stays; every piece
        drawn with the object is named."""
        from campaign_editor.lnt import Lnt, LntError
        raw = self.LNT.encode("latin-1")
        lnt = Lnt(raw)
        self.assertEqual(lnt.users("logo_obj"), [("main_menu", "main_logo")])
        logo = lnt.piece("main_menu", "main_logo")
        lnt.set_state("logo_obj", "highlighted", "textures\\FE_texture1.tga", "logo")
        self.assertEqual(lnt.objects()["logo_obj"]["regions"]["highlighted"], ("textures\\FE_texture1.tga", "logo"))
        self.assertEqual(lnt.art(logo, "highlighted")[1], (0, 36, 489, 204))
        out = lnt.dump().decode("latin-1")
        self.assertIn("  </UI region>\r\n  <UI region>highlighted\r\n    <page>", out)
        lnt.remove_state("logo_obj", "highlighted")
        self.assertEqual(lnt.dump(), raw)
        lnt.set_state("logo_obj", "art", "textures\\FE_texture1.tga", "other")
        self.assertIn("    <region>other</region>\r\n", lnt.dump().decode("latin-1"))
        with self.assertRaises(LntError):
            lnt.remove_state("logo_obj", "art")                     # its only picture
        with self.assertRaises(LntError):
            lnt.set_state("no_such", "art", "p", "r")

    def test_own_picture_for_a_piece_keeps_what_it_does(self):
        """The user, 2026-10-17: a piece's picture replaced by one's own - 'pull a knot and the web follows': it keeps
        what it does (identifier, the page it opens, its words) and gets its OWN copy of its UI object, so no other
        piece changes; a new texture with a region per state (the engine finds regions by name, without case); a
        library picture (a region of the game's sheets) the same way; shared = its object itself changed; Back to
        the game's picture takes the own blocks out again - the file byte for byte; a missing region (the game stops)
        and a page too big for the engine's sheet are said."""
        from campaign_editor.lnt import Lnt, LntError, own_picture_file, sheet_size
        raw = self.LNT.encode("latin-1")
        lnt = Lnt(raw)
        logo = lnt.piece("main_menu", "main_logo")
        stem = lnt.own_stem("main_menu", logo["index"])
        self.assertEqual(stem, "logo_obj_own")
        regs = {stem + "_art": (0, 0, 99, 49)}
        obj, gone = lnt.own_picture("main_menu", logo["index"], {"art": ("ce_ui\\logo_obj_own.tga", stem + "_art")},
                                    texture=("ce_ui\\logo_obj_own.tga", regs))
        self.assertEqual((obj, gone), ("logo_obj_own", None))
        now = lnt.piece("main_menu", "main_logo")
        self.assertEqual((now["identifier"], now["x"], now["width"]), ("UIP_EMPTY_ART", 266, 489))
        self.assertEqual(lnt.art(now), ("ce_ui\\logo_obj_own.tga", (0, 0, 99, 49), "ce_ui"))
        self.assertIn("logo_obj", lnt.objects())                       # the game's object stays for the others
        out = lnt.dump().decode("latin-1")
        self.assertIn("</texture>\r\n<texture>ce_ui\\logo_obj_own.tga\r\n  <path>ce_ui</path>\r\n  <region>"
                      "logo_obj_own_art\r\n    <left>0</left>\r\n", out)
        self.assertEqual(lnt.missing_regions(), [])
        self.assertIn("LOGO_OBJ_OWN_ART", lnt.names_taken())
        # replaced again keeping the own picture for a state: the old object goes, its picture stays (still named)
        again = lnt.dump()
        obj, gone = lnt.own_picture("main_menu", logo["index"], {"art": ("ce_ui\\logo_obj_own.tga", stem + "_art")})
        self.assertEqual((obj, gone), ("logo_obj_own2", None))
        self.assertEqual(lnt.missing_regions(), [])
        self.assertNotIn("logo_obj_own", lnt.objects())
        lnt = Lnt(again)
        # a library picture instead: the old own picture goes, its file said to be no longer used
        obj, gone = lnt.own_picture("main_menu", logo["index"], {"art": ("textures\\FE_texture1.tga", "logo")})
        self.assertEqual((obj, gone), ("logo_obj_own2", "ce_ui\\logo_obj_own.tga"))
        self.assertEqual(lnt.back_to_game("main_menu", logo["index"]), None)
        self.assertEqual(lnt.dump(), raw)
        with self.assertRaises(LntError):
            lnt.back_to_game("main_menu", logo["index"])               # the game's own: nothing to go back to
        # shared: the game's object itself changed, no copy
        obj, _ = lnt.own_picture("main_menu", logo["index"], {"art": ("textures\\FE_texture1.tga", "gone_one")},
                                 shared=True)
        self.assertEqual(obj, "logo_obj")
        self.assertEqual(lnt.missing_regions(), [("logo_obj", "art", "gone_one")])
        self.assertEqual(sheet_size("x/mtw2.lnt"), (4096, 2048))
        self.assertEqual(sheet_size("x/Rome.lnt"), (2048, 2048))
        self.assertEqual(Lnt(raw).page_area("main_menu"), 496 * 176)  # 490 x 169 rounded up to 8 pixels
        try:
            from PIL import Image
        except ImportError:
            return
        data = own_picture_file([Image.new("RGB", (10, 10), (255, 0, 0)), Image.new("RGB", (5, 5))], (20, 8))
        self.assertEqual(Image.open(__import__("io").BytesIO(data)).size, (20, 16))

    def test_building_lines_explained(self):
        """Report #316: the Building editor's lines had no '?' (the units' had): each line of a chain says what it
        does and what each value is - recruit / recruit_pool / agent split into their numbers, the condition named,
        a level's own line, the fixed words ('bonus'); an unknown line gets none."""
        from campaign_editor import edbfields as BF
        got = BF.explain("recruit_pool", '"Peasants" 1 0.5 4 0 requires factions { england, }')
        for part in ("1. unit = Peasants", "3. units added a turn = 0.5", "4. most units the pool holds = 4",
                     "then: requires factions { england, }"):
            self.assertIn(part, got)
        self.assertIn("2. experience it starts with = 0", BF.explain("recruit", '"roman hastati" 0'))
        self.assertIn("1. bonus - this word itself", BF.explain("happiness_bonus", "bonus 2"))
        self.assertIn("2. amount = 2", BF.explain("happiness_bonus", "bonus 2"))
        self.assertIn("1. size = town", BF.explain("settlement_min", "town"))
        self.assertIn("a level of the chain", BF.explain("wooden_wall", "requires factions { barbarian, }"))
        self.assertIsNone(BF.explain("no_such_line", "1"))

    def test_unit_entries_keep_experience_and_the_right_click(self):
        """A garrison / an army carries each unit's exp / armour / weapon (they were written back as 0 0 0 at every
        change); the right click (the user, 2026-10-16: a context menu, not buttons) sets them, adds more like it,
        takes all like it out, replaces one keeping its numbers, adds several or with experience from the roster."""
        from campaign_editor import strat as S
        line = "unit\t\tTown Militia\t\t\t\texp 3 armour 1 weapon_lvl 0"
        e = S.unit_entry(line)
        self.assertEqual(e, "Town Militia|3|1|0")
        self.assertEqual(S.unit_entry("unit Town Militia exp 0 armour 0 weapon_lvl 0"), "Town Militia")
        self.assertEqual((S.entry_type(e), S.entry_stats(e)), ("Town Militia", (3, 1, 0)))
        self.assertEqual(S.unit_line(e), line)
        self.assertEqual(S.unit_line("Archers"), "unit\t\tArchers\t\t\t\texp 0 armour 0 weapon_lvl 0")
        self.assertEqual(S.with_stats(e, exp=12, weapon=2), "Town Militia|9|1|2")   # the game's ranges
        self.assertEqual(S.with_stats(e, exp=0, armour=0), "Town Militia")
        self.assertEqual(S.entry_label(e), "Town Militia (exp 3, armour 1)")
        try:
            import tkinter as tk
            root = tk.Tk()
        except Exception as err:
            self.skipTest("no window: %s" % err)
        from types import SimpleNamespace
        from campaign_editor.gui_garrison import GarrisonEditor
        try:
            got = []
            ed = GarrisonEditor(root)
            u = lambda t: SimpleNamespace(type=t, category="infantry", upkeep=100, price=300, mercenary=False,
                                          general=False, ownership=["all"], summary=lambda: t)
            units = [u("Town Militia"), u("Archers")]
            ed.load(None, None, "Rome", units, [e, "Archers"], got.append)
            ed.set_stats(1, exp=4)
            self.assertEqual(ed.garrison, [e, "Archers|4|0|0"])
            ed.more(0, 2)
            self.assertEqual(ed.garrison, [e, e, e, "Archers|4|0|0"])
            ed.set_stats(0, every=True, weapon=2)
            self.assertEqual(ed.garrison[:3], ["Town Militia|3|1|2"] * 3)
            ed.replace(3)
            ed.add(units[0])                                    # the card clicked takes its place, its numbers kept
            self.assertEqual(ed.garrison[3], "Town Militia|4|0|0")
            ed.take_all("Town Militia")
            self.assertEqual(ed.garrison, [])
            ed.add(units[1], n=5, exp=2)
            self.assertEqual(ed.garrison, ["Archers|2|0|0"] * 5)
            ed.add(units[1], n=99)                              # never past the 20 an army holds
            self.assertEqual(len(ed.garrison), 20)
            self.assertEqual(got[-1], ed.garrison)
        finally:
            root.destroy()

    def test_faction_slots_added_on_their_grid(self):
        """More factions to pick (open.md 'MENU SLOTS FOR MANY FACTIONS'): a faction-select page's CFP_symbol48_N slots
        made up to a number - copies of the last under the next numbers, the grid continued (the same columns, rows
        on from the last); Check mod files says when there are fewer slots than playable factions."""
        from campaign_editor import lnt as L
        page = ("    <UI piece>CFP_symbol48_%d\r\n      <identifier>UIP_MENU_BUTTON</identifier>\r\n"
                "      <Parameters>\r\n        <x>%d</x>\r\n        <y>%d</y>\r\n        <width>48</width>\r\n"
                "        <height>48</height>\r\n      </Parameters>\r\n    </UI piece>\r\n")
        body = "".join(page % (i + 1, 780 + (i % 3) * 53, 158 + (i // 3) * 54) for i in range(4))
        raw = ("<layout>\r\n  <layout_width>1024</layout_width>\r\n  <layout_height>768</layout_height>\r\n"
               "  <lpage>ImpCam_choose_faction\r\n" + body + "  </lpage>\r\n</layout>\r\n")
        lnt = L.Lnt(raw.encode("latin-1"))
        self.assertEqual(L.slots_short(lnt, 6), [("ImpCam_choose_faction", 4)])
        self.assertEqual(L.add_slots(lnt, "ImpCam_choose_faction", "CFP_symbol48_", 7), 3)
        got = [(x["name"], x["x"], x["y"]) for x in L.slot_rows(lnt)[("ImpCam_choose_faction", "CFP_symbol48_")]]
        self.assertEqual(got[3:], [("CFP_symbol48_4", 780, 212), ("CFP_symbol48_5", 833, 212),
                                   ("CFP_symbol48_6", 886, 212), ("CFP_symbol48_7", 780, 266)])
        self.assertEqual(L.slots_short(lnt, 6), [])
        self.assertEqual(L.Lnt(lnt.dump()).dump(), lnt.dump())
        # every write that changes descr_strat gives each playable faction its slot by itself (the user, 2026-10-18:
        # 'the editor adds a slot for each new faction, right?'), backed up with the write like any file
        from campaign_editor.plan import Plan
        mod = ModData(self.root)
        menu = os.path.join(mod.data, "menu")
        os.makedirs(menu, exist_ok=True)
        one = page % (1, 780, 158)
        write(os.path.join(menu, "Rome.lnt"), raw.replace(body, one))
        camp = mod.campaign_file("test", "descr_strat.txt")
        plan = Plan(mod, "x", "x", {})
        f = plan.edit(camp)
        i = next(k for k, line in enumerate(f.texts()) if line.strip() == "alpha")
        f.insert(i + 1, ["\tslave"])                                 # two playable now, one slot
        plan.apply()
        got = L.Lnt.load(os.path.join(menu, "Rome.lnt"))
        self.assertEqual(len(L.slot_rows(got)[("ImpCam_choose_faction", "CFP_symbol48_")]), 2)

    def test_missing_texture_inside_a_campaign_map_model(self):
        """Check mod files: a texture named INSIDE a campaign-map model (.cas) that is not there stops the game ('Failed
        to find texture', read in both exes' code). Only the models whose texture the game takes from the model are
        looked at: resources, settlements, faction symbols, descr_model_strat types with no texture line; found as
        .tga, .tga.dds or .dds beside the model, a bare name in its textures folder, the mod's own or the game's."""
        from campaign_editor import castex
        from campaign_editor.check import check_mod
        mod = ModData(self.root)

        def cas(rel, *textures):
            body = b"\x00".join(b"\x10\x00\x00\x00" + t.encode("latin-1") for t in textures) + b"\x00"
            write_bytes = os.path.join(mod.data, *rel.split("/"))
            os.makedirs(os.path.dirname(write_bytes), exist_ok=True)
            with open(write_bytes, "wb") as fh:
                fh.write(b"\x00" * 40 + body + b"\x00" * 8)
        cas("models_strat/resource_gold.cas", "textures\\gold.tga")
        cas("models_strat/resource_wool.cas", "wool.TGA")                      # a bare name
        cas("models_strat/navy.cas", "textures\\galley.tga")                 # its type has texture lines
        self.assertEqual(castex.texture_names(open(os.path.join(mod.data, "models_strat", "resource_gold.cas"),
                                                   "rb").read()), ["textures\\gold.tga"])
        with open(os.path.join(mod.data, "descr_sm_resources.txt"), "a", encoding="latin-1") as fh:
            fh.write("\ntype gold\nitem data/models_strat/resource_gold.CAS\n"
                     "type wool\nitem ../mymod/data/models_strat/resource_wool.cas\n")
        with open(os.path.join(mod.data, "descr_model_strat.txt"), "a", encoding="latin-1") as fh:
            fh.write("\ntype my_admiral\ntexture romans_julii, data/models_strat/textures/navy.tga\n"
                     "model_flexi data/models_strat/navy.cas, max\n")
        got = castex.problems(mod)
        self.assertEqual(len(got), 2, got)
        self.assertIn("models_strat/resource_gold.CAS (a resource's model) names the texture 'textures\\gold.tga'",
                      got[0])
        self.assertIn("'wool.TGA'", got[1])
        self.assertIn("names the texture 'textures\\gold.tga'", check_mod(mod, "test"))
        write(os.path.join(mod.data, "models_strat", "textures", "gold.tga.dds"), "x")
        write(os.path.join(mod.data, "models_strat", "textures", "wool.tga"), "x")
        self.assertEqual(castex.problems(mod), [])
        self.assertIn("MODEL TEXTURES:", check_mod(mod, "test"))

    def test_events_without_their_words(self):
        """Check mod files: an event (descr_events.txt, or historic_event in the campaign script) whose {NAME_TITLE} /
        {NAME_BODY} are not in historic_events.txt - a note, not a fault: the game logs 'Couldn't find title /
        description string' and shows the scroll empty (our tester's runs, both games); an emergent faction's words
        are elsewhere and not asked for. Every vanilla event has both."""
        from campaign_editor import events as EV
        from campaign_editor.check import check_mod
        mod = ModData(self.root)
        camp = os.path.dirname(mod.in_campaign("test", "descr_strat.txt"))
        write(os.path.join(camp, "descr_events.txt"), "event historic my_event\ndate 3 summer\n\n"
                                                       "event emergent_faction slavs\ndate 5\n")
        write(os.path.join(camp, "campaign_script.txt"), "script\n    historic_event other_event\nend_script\n")
        text = os.path.join(mod.data, "text")
        os.makedirs(text, exist_ok=True)
        with open(os.path.join(text, "historic_events.txt"), "w", encoding="utf-16") as fh:
            fh.write("\u00ac comment\n{MY_EVENT_TITLE}A title\n")
        got = EV.text_gaps(mod, "test")
