    def test_3d_map_heights_as_the_heights_brush_reads_them(self):
        """#339: a square of other heights round every heights-brush stroke in 3D - the map was built from the
        picture's grey steps, the brush sent the game's own map_heights.hgt values for the points round it. Both now
        read the same: the .hgt's value where it agrees with the picture, the picture's elsewhere, land never 0."""
        try:
            import numpy as np
            from campaign_editor import terrain3d as T3
        except ImportError:
            self.skipTest("no NumPy")
        from types import SimpleNamespace
        from campaign_editor import terrain as T
        top, low = 2550.0, -255.0                                 # 10 m a grey step, 1 m a blue step
        top_down = np.array([[(10, 10, 10), (20, 20, 20), (0, 0, 0)],
                             [(0, 0, 200), (30, 30, 30), (40, 40, 40)]], np.uint8)
        bottom_up = top_down[::-1]
        hgt = (3, 2, [-56.0, 312.0, 370.0,                        # bottom row: agrees, agrees, 3 steps off
                      104.0, 207.0, -3.0])                        # top row: agrees, agrees, sea under land
        got = T3.game_metres(top_down, top, low, hgt)
        self.assertEqual(got.tolist(), [[104.0, 207.0, 1.0], [-56.0, 312.0, 400.0]])
        pic = SimpleNamespace(width=3, height=2, get=lambda px, py: tuple(int(v) for v in bottom_up[py][px]))
        sc = T.ShapeCoast(pic, None, None, None, None, None, None, top, low, hgt)
        for py in range(2):
            for px in range(3):
                self.assertAlmostEqual(sc.metres(px, py), float(got[1 - py][px]), places=4)

    def test_3d_frame_clock_says_where_the_time_goes(self):
        """Step 1 before drawing straight into the window: a frame's time by parts - drawn by the card, copied back,
        put in the window - the mean of the last 10 frames, in plain words with what each number means."""
        try:
            from campaign_editor.glmap import FrameClock
        except ImportError:
            self.skipTest("no NumPy")
        clock = FrameClock()
        self.assertEqual(clock.text(), "")
        for _ in range(12):
            clock.add(0.010, 0.005, 0.025, (1200, 700))
        self.assertEqual(len(clock.frames), 10)
        self.assertEqual(clock.text(), "a frame (1200 x 700): the graphics card draws it in 10 ms, copying it back "
                                       "takes 5 ms, putting it in the window 25 ms = 40 ms (25 frames a second)")

    def test_3d_map_shown_by_the_card_itself(self):
        """Step 2: the map's frame is copied into the window by the card (nothing read back), the brush's ring drawn
        over it on the card as wide lines (the card draws lines one pixel wide only); Windows only, else as before."""
        try:
            from campaign_editor import glmap, glwindow as GW
        except ImportError:
            self.skipTest("no NumPy")
        import numpy as np
        rows = GW.thick_line([(0, 0), (10, 0)], 4, (1, 1, 1, 1))
        self.assertEqual(len(rows), 6)
        self.assertEqual(sorted({r[1] for r in rows}), [-2.0, 2.0])         # 4 pixels wide, round the line
        self.assertEqual(sorted({r[0] for r in rows}), [-2.0, 12.0])        # a little past each end
        self.assertEqual(GW.thick_line([(3, 3), (3, 3)], 2, (1, 1, 1, 1)), [])
        if sys.platform != "win32":
            self.assertFalse(GW.WindowGL(None).attach(0))                   # elsewhere: drawn as before
        if not glmap.available()[0]:
            self.skipTest("no OpenGL 3.3 here")
        ctx = glmap.context()
        frame, screen = ctx.simple_framebuffer((20, 10)), ctx.simple_framebuffer((20, 10))
        frame.use()
        ctx.clear(0.0, 0.0, 1.0, 1.0)
        GW.show(ctx, frame, screen, 20, 10, [([(0, 5), (20, 5)], 2, (1.0, 0.0, 0.0, 1.0))], GW.Overlay(ctx))
        arr = np.frombuffer(screen.read(components=3), np.uint8).reshape(10, 20, 3)[::-1]
        self.assertEqual(tuple(arr[1, 10]), (0, 0, 255))                    # the map's frame, copied
        self.assertEqual(tuple(arr[5, 10]), (255, 0, 0))                    # the line over it
        frame.release()
        screen.release()

    def test_menu_page_drawn_after_the_3d_map(self):
        """#340: an Interface page went black after the 3D map - the map leaves the depth test on in the one shared
        OpenGL context, so every piece after the page's backdrop (all at one depth) was thrown away. The page's
        drawing sets the card's switches itself."""
        from campaign_editor import glmenu as G
        if not G.available():
            self.skipTest("no NumPy or no OpenGL 3.3 here")
        from campaign_editor import glmap
        ctx = glmap.context()
        ctx.enable(ctx.DEPTH_TEST | ctx.CULL_FACE)               # as View in 3D leaves it
        try:
            arr = G.draw(20, 10, (0, 0, 0), [(None, G.quad(0, 0, 20, 10, rgba=(0.1, 0.1, 0.1, 1.0))),
                                             (None, G.quad(5, 2, 15, 8, rgba=(1.0, 0.0, 0.0, 1.0)))])
        finally:
            ctx.disable(ctx.DEPTH_TEST | ctx.CULL_FACE)
        self.assertEqual(tuple(arr[5, 10]), (255, 0, 0))

    def test_menu_layout_read_and_written_byte_exact(self):
        """The interface editor's ground (the user, 2026-10-15: 'a full interface editor', from Wholesome Queen's
        studio): a .lnt file read into pages, pieces, pictures; written back byte-exact; a move, a copy, a rename and
        a removal change only their own lines."""
        from campaign_editor.lnt import Lnt, LntError
        raw = self.LNT.encode("latin-1")
        lnt = Lnt(raw)
        self.assertEqual(lnt.dump(), raw)
        self.assertEqual(lnt.pages(), ["main_menu", "new_game"])
        self.assertEqual(lnt.size(), (1024, 768))
        single = lnt.piece("main_menu", "main_single")
        self.assertEqual((single["x"], single["y"], single["width"], single["height"]), (255, 256, 513, 38))
        self.assertEqual((single["menu_id"], single["text"], single["font"], single["align"]),
                         ("new_game", "UI_SINGLE", "arial_split_CAF", "centre"))
        self.assertEqual(lnt.opened_by(), {"new_game": [("main_menu", "main_single")]})
        self.assertEqual(lnt.art(lnt.piece("main_menu", "main_logo")),
                         ("textures\\FE_texture1.tga", (0, 36, 489, 204), "textures"))
        self.assertIsNone(lnt.art(single))                           # empty_push_button: the engine draws it
        from types import SimpleNamespace
        from campaign_editor.lnt import texture_file
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d)
        for rel in ("menu/textures/FE_texture1.tga", "menu/textures/M2_Border.tga.dds"):
            write(os.path.join(d, *rel.split("/")), "x")
        mod = SimpleNamespace(roots=lambda: [d], data=d)
        self.assertTrue(texture_file(mod, None, "textures\\FE_texture1.tga").endswith("FE_texture1.tga"))
        # Medieval II names the picture alone, its folder in the texture's <path>; unpacked as .tga.dds
        self.assertTrue(texture_file(mod, None, "M2_Border.tga", "textures").endswith("M2_Border.tga.dds"))
        self.assertIsNone(texture_file(mod, None, "none.tga", "textures"))
        tree = lnt.root
        lnt.move("main_menu", "main_single", x=300, y=200)
        # a drag: the lines meant change, the file is not read again (it was, twice a mouse move - it lagged)
        self.assertIs(lnt.root, tree)
        self.assertEqual(Lnt(lnt.dump()).piece("main_menu", "main_single")["x"], 300)
        self.assertIs(lnt.textures(), lnt.textures())                 # read once a parse
        lnt.move("main_menu", "main_logo", height=168)                # a missing height goes after width
        self.assertIsNot(lnt.root, tree)                              # a line put in: read again
        out = lnt.dump().decode("latin-1")
        self.assertIn("        <x>300</x>\r\n        <y>200</y>\r\n", out)
        self.assertIn("        <width>489</width>\r\n        <height>168</height>\r\n      </Parameters>", out)
        self.assertEqual(len(out.splitlines()), len(self.LNT.splitlines()) + 1)
        lnt.copy_piece("main_menu", "main_single", "main_single_2", dy=64)
        two = lnt.piece("main_menu", "main_single_2")
        self.assertEqual((two["x"], two["y"], two["text"]), (300, 264, "UI_SINGLE"))
        self.assertEqual(lnt.piece("main_menu", "main_single")["y"], 200)
        lnt.copy_piece("main_menu", "main_logo", "logo_there", to_page="new_game")
        self.assertEqual([x["name"] for x in lnt.pieces("new_game")], ["logo_there"])
        lnt.rename_piece("new_game", "logo_there", "logo_here")
        lnt.set_text("main_menu", "main_single_2", "UI_OTHER")
        self.assertEqual(lnt.piece("main_menu", "main_single_2")["text"], "UI_OTHER")
        with self.assertRaises(LntError):
            lnt.copy_piece("main_menu", "main_single", "main_single_2")      # the name is taken
        for page, name in (("new_game", "logo_here"), ("main_menu", "main_single_2")):
            lnt.remove_piece(page, name)
        lnt.move("main_menu", "main_single", x=255, y=256)
        self.assertEqual(lnt.dump().decode("latin-1").replace("        <height>168</height>\r\n", "", 1), self.LNT)
        # a slip the game reads past (report #349: an <identifier> never closed before </UI piece>): no stop - the
        # tag left open is one line, a stray close passed over, both in problems; the bytes stay as they are
        slip = Lnt("<layout>\r\n  <lpage>a\r\n</layout>\r\n")
        self.assertEqual(slip.problems, ["line 2: <lpage> is never closed - read as one line"])
        piece = ("<layout>\r\n  <lpage>p\r\n    <UI piece>b\r\n      <identifier>button\r\n"
                 "      <object_id>obj</object_id>\r\n    </UI piece>\r\n  </lpage>\r\n  </stray>\r\n</layout>\r\n")
        slip = Lnt(piece)
        self.assertEqual(slip.dump().decode("latin-1"), piece)
        p = slip.root.find("layout").find("lpage").find("UI piece")
        self.assertEqual((p.get("identifier"), p.get("object_id")), ("button", "obj"))
        self.assertEqual(len(slip.problems), 2)
        # a modder's comments, one line and several (#305: '</lpage> closes nothing open (open: <!-- HEADING ...')
        noted = ("<layout>\r\n  <!-- HEADING WITH TITLE \"FACTIONS\" I THINK -->\r\n  <lpage>a\r\n  <!-- two\r\n"
                 "  <lpage>b -->\r\n  </lpage>\r\n</layout>\r\n")
        self.assertEqual([p.value for p in Lnt(noted).layout().all("lpage")], ["a"])
        self.assertEqual(Lnt(noted).dump().decode("latin-1"), noted)
        # two pieces of one name on a page (Medieval II's main menu): each reached by its place, the right one moves
        twin = Lnt(raw)
        at = twin.copy_piece("main_menu", 0, "main_logo_2")
        twin.rename_piece("main_menu", at, "main_logo")
        self.assertEqual([x["name"] for x in twin.pieces("main_menu")], ["main_logo", "main_logo", "main_single"])
        twin.move("main_menu", at, x=5)
        self.assertEqual([x["x"] for x in twin.pieces("main_menu")], [266, 5, 255])
        for game, rel in (("Rome Total War Gold", "data/menu/Rome.lnt"), ("Medieval II Total War", "data/menu/mtw2.lnt")):
            for top in ("/home/user/rtw-game-data", "/home/user/m2tw-game-data"):    # the games' own, when here
                p = os.path.join(top, game, rel)
                if os.path.isfile(p):
                    with open(p, "rb") as fh:
                        data = fh.read()
                    self.assertEqual(Lnt(data).dump(), data)

    def test_raze_tooltip_says_what_it_brings(self):
        """The game's own three capture buttons say their gold at once; Sack Settlement (Rome) and Raze Settlement
        (Medieval II) say theirs too: the tooltip holds {gold} / {buildings} / {people}, filled for the town just
        taken by the same rule the raze pays by (raze_estimate)."""
        from campaign_editor import addons as A
        for key in ("sack_settlement", "raze_settlement"):
            text = A.by_key(key).template()
            got = A.read_settings(A.by_key(key), text)
            self.assertIn("{gold}", got["RAZE_BUTTON_TIP"])
            self.assertIn("ui.tooltip(0, raze_tip_text())", text)
            est = text[text.index("function raze_estimate"):text.index("function raze_tip_text")]
            self.assertIn("RAZE_GOLD_PER_BUILDING", est)
            self.assertIn("RAZE_KEEP_CHAINS", est)
            import re
            code = re.sub(r'"(?:[^"\\\n]|\\.)*"', '""', re.sub(r"//[^\n]*", "", text))     # strings and comments out
            self.assertEqual(code.count("{"), code.count("}"))

    def test_game_fonts_read_and_picked_for_the_menus(self):
        """The Interface window writes the menus' words in the game's own letters: a .cuf font (CUF0: header, a char
        table, 4-byte glyph records, offsets, 8-bit alpha) read and drawn; the font a piece names found as the game
        does - descr_font_db.txt's TrueType under an engine, else the layout's own .cuf, else the nearest size."""
        import struct as st
        from types import SimpleNamespace
        from campaign_editor import cuf, lnt as L
        table = [0xFFFF] * 65536
        table[ord("A")], table[ord(" ")] = 0, 1
        recs = st.pack("<bBBB", 2, 3, 2, 2) + st.pack("<bBBB", 0, 2, 0, 0)
        bitmap = bytes((255, 0, 0, 255))
        data = (b"CUF0" + st.pack("<11h", 2, 10, 0, 0, 0, 0, 0, 0, 0, 2, 2) + st.pack("<HI", 2, len(bitmap)) +
                st.pack("<65536H", *table) + recs + st.pack("<2I", 0, 0x7FFFFFFF) + bitmap)
        font = cuf.read(data)
        self.assertEqual(font.glyph("A").rows, [bytes((255, 0)), bytes((0, 255))])
        w, h, alpha = cuf.render(font, "A A")
        self.assertEqual((w, h), (8, 2))                          # 3 + 2 + 3 advance
        self.assertEqual(alpha[:2], bytes((255, 0)))
        with self.assertRaises(ValueError):
            cuf.read(b"NOPE" + data[4:])
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d)
        for n in ("fonts/font_10.cuf", "fonts/font_18.cuf", "fonts/times.ttf"):
            write(os.path.join(d, *n.split("/")), "x")
        write(os.path.join(d, "descr_font_db.txt"), "font\ttnr_sml\ttimes.ttf\t14\tkerned\n")
        mod = SimpleNamespace(roots=lambda: [d], data=d)
        doc = SimpleNamespace(fonts=lambda: {"tnr": {"file": "fonts\\font_18.cuf", "height": "18"},
                                             "arial_split_CAF": {"file": "Fonts\\arial.CAF", "height": "10"}})
        import campaign_editor.limits as LM
        real = LM.engine_of
        try:
            LM.engine_of = lambda m: "REX.exe"
            self.assertEqual(L.font_source(mod, doc, "tnr_sml"), ("ttf", os.path.join(d, "fonts", "times.ttf"), 14))
            LM.engine_of = lambda m: None                          # the original exe: its .cuf fonts
            self.assertEqual(L.font_source(mod, doc, "tnr_sml")[0], "cuf")
            self.assertTrue(L.font_source(mod, doc, "tnr")[1].endswith("font_18.cuf"))
            self.assertTrue(L.font_source(mod, doc, "arial_split_CAF")[1].endswith("font_10.cuf"))
        finally:
            LM.engine_of = real

    def test_menu_pieces_drawn_the_games_way(self):
        """Pieces with no picture of their own are drawn as RomeTW.exe draws them, from its parts in data/menu: the kind
        from the identifier / object, a tick box = one cell of buttons_composite2 as a square of the piece's width,
        frames a 9-slice from 8 px outside the piece, a slider arrows + track + knob."""
        from campaign_editor import menudraw as MD
        self.assertEqual(MD.kind("UIP_VIDEO_HDR", "empty_toggle_button", False), "tick")
        self.assertEqual(MD.kind("UIP_VIDEO_RES_DROPDOWN", "empty_art", False), "dropdown")
        self.assertEqual(MD.kind("UIP_AUDIO_MASTER_VOL_SLIDER", "empty_art", False), "slider")
        self.assertEqual(MD.kind("UIP_STATIC_TEXT", "empty_art", False), "static")
        self.assertEqual(MD.kind("UIP_MENU_BUTTON", "empty_push_button", False), "button")
        self.assertEqual(MD.kind("UIP_MENU_BUTTON", "logo", True), "art")
        self.assertEqual(MD.text_colour("static"), ((255, 223, 127), True))
        self.assertEqual(MD.text_colour("button"), ((255, 221, 119), False))
        try:
            from PIL import Image
        except ImportError:
            return
        grid = Image.new("RGBA", (128, 128))
        for n in range(16):                                     # each cell its own colour
            grid.paste((n * 10, 0, 0, 255), (32 * (n % 4), 32 * (n // 4), 32 * (n % 4 + 1), 32 * (n // 4 + 1)))
        parts = lambda name: grid                               # noqa: E731
        t = MD.tick(parts, 20)
        self.assertEqual((t.size, t.getpixel((10, 10))[0]), ((20, 20), 0))
        self.assertEqual(MD.tick(parts, 20, ticked=True).getpixel((10, 10))[0], 10)
        f, off = MD.framed(parts, 100, 40)
        self.assertEqual((f.size, off), ((116, 56), 8))
        self.assertEqual([f.getpixel(p)[0] for p in ((2, 2), (50, 2), (50, 28), (113, 53))], [0, 10, 50, 150])
        sl = MD.slider(parts, 120, 20, value=0)
        self.assertEqual((sl.getpixel((5, 5))[0], sl.getpixel((115, 5))[0], sl.getpixel((25, 5))[0]), (120, 130, 70))
        self.assertIsNone(MD.tick(lambda name: None, 20))

