            self.assertIn(own, plan.binaries)
            self.assertEqual(Image.open(__import__("io").BytesIO(plan.binaries[own])).size, (40, 10))
            with mock.patch.object(OWN, "library_dir", lambda: lib):
                got = []
                lw = OWN.Library(w, on_pick=got.append)
