    def test_interface_window_moves_copies_and_undoes(self):
        """Interface... (the user, 2026-10-15: 'a full interface editor'): the mod's menu layout drawn page by page; a
        piece picked, nudged, copied under the next number, the change undone and redone; a double click on a button
        opens its page; no buttons of its own (#296): the main window's Undo / Redo step it, its make_plan is what
        Preview changes / Apply changes write; nothing written before that."""
        try:
            import tkinter as tk
            root = tk.Tk()
        except Exception as e:                        # no tkinter / no display (CI without one)
            self.skipTest("no window: %s" % e)
        from types import SimpleNamespace
        from campaign_editor import gui_interface as GI
        menu = os.path.join(self.root, "data", "menu")
        os.makedirs(menu, exist_ok=True)
        with open(os.path.join(menu, "Rome.lnt"), "wb") as fh:
            fh.write(self.LNT.encode("latin-1"))
        before = tree_hash(self.root)
        try:
            root.mod = ModData(self.root)
            root.show_text = lambda *a: None
            w = GI.InterfacePanel(root, root)                            # a work of the main window, no window
            w.pack(fill="both", expand=True)
            self.assertNotIsInstance(w, tk.Toplevel)
            root.update()
            self.assertEqual(w.page, "main_menu")
            w.picked = w.doc.piece("main_menu", "main_single")["index"]
            w.nudge(1, 0, SimpleNamespace(state=0x1))                   # Shift: 10 pixels
            self.assertEqual(w.current()["x"], 265)
            w.copy_piece()
            self.assertEqual(w.current()["name"], "main_single_2")
            self.assertEqual(w.current()["y"], 266)
            w.do_undo()
            self.assertIsNone(w.doc.piece("main_menu", "main_single_2"))
            w.do_redo()
            self.assertIsNotNone(w.doc.piece("main_menu", "main_single_2"))
            w.set_value("text", "UI_OTHER")
            d = w.ask_place()                                         # the right click's Place and size...
            d.destroy()
            self.assertEqual(w.current()["text"], "UI_OTHER")
            single = w.doc.piece("main_menu", "main_single")["index"]
            quit_like = dict(w.doc.piece("main_menu", single), identifier="UIP_QUIT_DIALOG")
            self.assertTrue(w._is_button(quit_like))                    # Quit: no 'BUTTON' in its identifier
            self.assertFalse(w._is_button(w.doc.piece("main_menu", "main_logo")))
            root.geometry("900x700")
            root.update()
            s0, ox0, oy0 = w._scale()
            e = SimpleNamespace(x=300, y=200)
            point = ((300 - ox0) / s0, (200 - oy0) / s0)
            w._wheel(e, 1)                                              # the wheel zooms round the mouse
            s1, ox1, oy1 = w._scale()
            self.assertGreater(s1, s0)
            self.assertAlmostEqual((300 - ox1) / s1, point[0], places=6)
            w._pan_start(SimpleNamespace(x=10, y=10))
            w._pan_move(SimpleNamespace(x=40, y=30))                    # the held wheel moves the screen
            self.assertEqual(w._scale()[1:], (ox1 + 30, oy1 + 20))
            w.fit()
            self.assertEqual(w._scale(), (s0, ox0, oy0))
            root.update()
            w._set_hover(single)                                       # the mouse over a button: 'mouse over'
            self.assertEqual(w._state(w.doc.piece("main_menu", single)), "highlighted")
            w._set_hover(None)
            w.v_state.set("pressed")
            self.assertEqual(w._state(w.doc.piece("main_menu", single)), "selected")
            w.v_state.set("normal")
            w.picked = w.doc.piece("main_menu", "main_logo")["index"]

            def press(d, text):
                todo = [d]
                while todo:
                    c = todo.pop(0)
                    if c.winfo_class() == "TButton" and c.cget("text") == text:
                        return c.invoke()
                    todo += c.winfo_children()
                self.fail("no button %s" % text)
            d = w.ask_states()                                        # right click: Pictures of its states...
            press(d, "Add this state")                                 # the first state it lacks: normal (enabled)
            press(d, "OK")
            self.assertEqual(w.doc.objects()["logo_obj"]["regions"]["enabled"], ("textures\\FE_texture1.tga", "logo"))
            d = w.ask_states()
            press(d, "Take out")                                       # the first row: art
            press(d, "OK")
            self.assertEqual(list(w.doc.objects()["logo_obj"]["regions"]), ["enabled"])
            w.do_undo()
            self.assertEqual(sorted(w.doc.objects()["logo_obj"]["regions"]), ["art", "enabled"])
            w.picked = w.doc.piece("main_menu", "main_single")["index"]
            w.open_target()
            self.assertEqual(w.page, "new_game")
            self.assertTrue(w.dirty())
            self.assertGreater(w.pending(), 0)
            self.assertEqual(tree_hash(self.root), before)             # nothing written yet
            buttons, todo = [], [w]
            while todo:
                c = todo.pop(0)
                if c.winfo_class() == "TButton":
                    buttons.append(c.cget("text"))
                todo += c.winfo_children()
            for own in ("Undo", "Redo", "Preview", "Keep for Apply"):     # the main window's, never twice
                self.assertNotIn(own, buttons)
            root.status = tk.StringVar(master=root)
            n = len(w.undo)
            w.undo_step()                                              # the main window's Undo on this work
            self.assertEqual(len(w.undo), n - 1)
            w.redo_step()
            self.assertEqual(len(w.undo), n)
            plan = w.make_plan()                                       # what Preview / Apply changes write
            self.assertEqual(len(plan.changed_files()), 1)
            w.load()                                                   # shown again on the same mod: work stays
            self.assertIsNotNone(w.doc.piece("main_menu", "main_single_2"))
            self.assertEqual(w.rebind(ModData(self.root)), 0)          # the same mod again, its file unchanged: kept
            self.assertTrue(w.dirty())
            with open(os.path.join(menu, "Rome.lnt"), "ab") as fh:     # the file written meanwhile: said, read again
                fh.write(b"\r\n")
            self.assertEqual(w.rebind(ModData(self.root)), 1)
            self.assertFalse(w.dirty())
            w.destroy()
        finally:
            root.destroy()

    def test_palette_tga_read_and_written_back_true_colour(self):
        """A map made by a community map generator stores map_regions / features / ground as COLOUR-MAPPED TGAs
        (type 1; 9 = run-length) - the editor could not open them. They read like true-colour ones, and a picture
        written back (patched) is a plain type 2 TGA with the same pixels."""
        import struct as st
        from campaign_editor.tga import patched, read_tga, read_tga_bytes
        pal = [(0, 0, 0), (41, 140, 233), (255, 255, 255)]           # r, g, b
        idx = [1, 1, 0, 2, 1, 1]                                      # 3 x 2, bottom-up
        cmap = b"".join(bytes((b, g, r)) for r, g, b in pal)
        head = st.pack("<BBBHHBHHHHBB", 0, 1, 1, 0, 3, 24, 0, 0, 3, 2, 8, 0)
        p = os.path.join(self.root, "pal.tga")
        with open(p, "wb") as fh:
            fh.write(head + cmap + bytes(idx))
        img = read_tga(p)
        self.assertEqual([img.get(x, y) for y in range(2) for x in range(3)], [pal[i] for i in idx])
        rle = st.pack("<BBBHHBHHHHBB", 0, 1, 9, 0, 3, 24, 0, 0, 3, 2, 8, 0) + cmap + \
            bytes((0x81, 1, 0x00, 0, 0x00, 2, 0x81, 1))               # 2 x 1, 0, 2, 2 x 1
        self.assertEqual(read_tga_bytes(rle).get(0, 1), pal[2])
        out = patched(p, {(0, 0): (9, 9, 9)})
        self.assertEqual((out[1], out[2], out[16]), (0, 2, 24))        # true colour, no colour map
        back = read_tga_bytes(out)
        self.assertEqual(back.get(0, 0), (9, 9, 9))
        self.assertEqual(back.get(2, 1), pal[1])

