    def test_bigger_map_rivers_stop_at_the_new_coast(self):
        """A river whose last tiles the smoother coast puts in the sea runs to the coast and ends on the land touching
        the water - never a pixel on the water (the user's rule; a tester's DaC x3: land kept under such rivers stood
        off every mouth as a sandbar)."""
        from campaign_editor import upscale
        from campaign_editor.tga import read_tga
        river, black = (0, 0, 255), (0, 0, 0)
        px = [[black] * 4 for _ in range(4)]
        for x in range(4):
            px[1][x] = river                                  # a river along y 1, west to east
        path = os.path.join(self.root, "feat.tga")
        write_tga(path, 4, 4, px)
        land = upscale.Mask(12, 12)
        for X in range(12):
            for Y in range(12):
                land[(X, Y)] = X < 8                          # the new coast cuts the last tile and a bit
        data, drawn = upscale.features_scaled(path, land)
        with open(path, "wb") as fh:
            fh.write(data)
        f = read_tga(path)
        on = {(x, y) for x in range(12) for y in range(12) if f.get(x, y) != black}
        self.assertEqual([p for p in on if not land[p]], [])             # nothing on the water
        self.assertEqual(on, drawn)
        self.assertEqual(max(x for x, y in on if land[(x, y)]), 7)      # the river runs to the last land

    def test_bigger_map_natural_rivers(self):
        """x3 rivers drawn the natural way: a bend's point moves into the bend, a straight run swings a pixel to
        its lower side (no relief here: the middle) - and still one unbroken river (side by side only), as many ends as
        before, every pixel inside its old tiles' 3 x 3 blocks (a corner link: the one beside), a ford on the river, never two pixels wide (no 2 x 2
        square anywhere); the same map, the same river."""
        from campaign_editor import upscale
        river, ford, black = (0, 0, 255), (0, 255, 255), (0, 0, 0)
        n = 14
        px = [[black] * n for _ in range(n)]
        for x in range(1, 12):
            px[2][x] = river                                  # a long straight run west to east...
        for y in range(3, 9):
            px[y][11] = river                                 # ...a bend, south...
        for i in range(1, 5):
            px[8 + i][11 - i] = river                         # ...then a diagonal of corner links
        px[2][6] = ford
        path = os.path.join(self.root, "feat.tga")
        write_tga(path, n, n, px)
        old = {(x, y) for y in range(n) for x in range(n) if px[y][x] != black}
        _, plain = upscale.features_scaled(path)
        _, nat = upscale.features_scaled(path, natural=True)
        self.assertEqual(upscale.features_scaled(path, natural=True)[1], nat)            # the same each time
        self.assertNotEqual(nat, plain)
        for q in nat:                         # in its old tiles' blocks (a corner link: the block beside it too)
            bx, by = q[0] // 3, q[1] // 3
            self.assertTrue((bx, by) in old or any((bx + a, by) in old and (bx, by + b) in old
                                                   for a in (-1, 1) for b in (-1, 1)), q)
        seen, todo = {next(iter(nat))}, [next(iter(nat))]
        while todo:
            x, y = todo.pop()
            for q in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if q in nat and q not in seen:
                    seen.add(q)
                    todo.append(q)
        self.assertEqual(seen, nat)                                                     # one unbroken river

        def ends(px):
            return sum(1 for p in px if sum((p[0] + a, p[1] + b) in px for a, b in ((1, 0), (-1, 0), (0, 1),
                                                                                        (0, -1))) == 1)
        self.assertEqual(ends(nat), ends(plain))
        self.assertFalse([q for q in nat if (q[0] + 1, q[1]) in nat and (q[0], q[1] + 1) in nat and
                          (q[0] + 1, q[1] + 1) in nat])                               # never wider than one pixel
        bend = (11 * 3 + 1, 2 * 3 + 1)                                                  # the corner tile's middle
        self.assertNotIn(bend, nat)                                                     # cut, not a right angle

    def test_bigger_map_no_islands_in_a_navigable_river(self):
        """A tester's DaC x3 (Medieval II with M2EX): small islands inside a navigable river - a river map_regions
        calls the province's land and the heights call water, with a sea tile here and there. The smooth coast gave
        the 8 pixels round such a sea tile the province (land), and the heights followed map_regions there because
        the old tile agreed (sea in both): a ring of land rose in the water. Inside water all round the heights keep
        their own coast: no land there."""
        from campaign_editor import upscale
        P, S, LAND, WATER = (200, 40, 40), (41, 140, 233), (60, 60, 60), (0, 0, 120)
        regions = [[S if (x, y) == (2, 2) else P for x in range(5)] for y in range(5)]
        rpath = os.path.join(self.root, "regions.tga")
        write_tga(rpath, 5, 5, regions)
        heights = [[WATER if 3 <= x <= 7 else LAND for x in range(11)] for y in range(11)]   # tiles 1-3 water
        hpath = os.path.join(self.root, "heights.tga")
        write_tga(hpath, 11, 11, heights)
        info = {}
        upscale.regions_scaled(rpath, {P}, None, (), info)
        agree = upscale._agreement(rpath, hpath, {P})
        wet = upscale.heights_from_tiles(info["land"], agree, upscale.heights_mask(hpath))
        ring = [(2 * X + 1, 2 * Y + 1) for X in range(6, 9) for Y in range(6, 9)]     # the old sea tile's new 3 x 3
        self.assertTrue(all(wet[p] for p in ring), [p for p in ring if not wet[p]])
        self.assertFalse(wet[(1, 1)])                                   # the bank (heights land) stays land

    def test_bigger_map_winding_coast_and_borders(self):
        """x3 the natural way: the coast runs smooth (the water finds its level - not along the 3 x 3 blocks), the
        borders between regions wind, while
        every old tile's middle keeps its region or sea, each region stays in as many pieces as before and the
        ground's edges wind too - the same map gives the same picture."""
        from campaign_editor import upscale
        from campaign_editor.tga import read_tga
        A, B, S = (200, 40, 40), (40, 200, 40), (41, 140, 233)
        n = 14
        old = [[S if x + y < 6 else (A if x < 7 else B) for x in range(n)] for y in range(n)]
        rpath = os.path.join(self.root, "regions.tga")
        write_tga(rpath, n, n, old)
        flat = upscale.coast_mask(rpath, {A, B})
        bent = upscale.coast_mask(rpath, {A, B}, natural=True)
        edge = [next(X for X in range(flat.W) if bent[(X, Y)]) for Y in range(flat.H)]      # the first land
        self.assertTrue(all(abs(a - b) <= 2 for a, b in zip(edge, edge[1:])), edge)  # no 3 x 3 steps
        self.assertEqual(bytes(bent.b), bytes(upscale.coast_mask(rpath, {A, B}, natural=True).b))
        out = os.path.join(self.root, "regions3.tga")
        with open(out, "wb") as fh:
            fh.write(upscale.regions_scaled(rpath, {A, B}, bent, (), {}, natural=True))
        g, first = read_tga(out), read_tga(rpath)
        W = n * 3
        for x in range(n):
            for y in range(n):
                self.assertEqual(g.get(3 * x + 1, 3 * y + 1), first.get(x, y))
        cols = lambda c: [(X, Y) for X in range(W) for Y in range(W) if g.get(X, Y) == c]
        for c in (A, B):
            px = set(cols(c))
            seen, st = {next(iter(px))}, [next(iter(px))]
            while st:
                a, b = st.pop()
                for q in ((a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)):
                    if q in px and q not in seen:
                        seen.add(q)
                        st.append(q)
            self.assertEqual(seen, px)                                  # one piece, as before
        border = {X for X in range(W) for Y in range(W) if g.get(X, Y) == A and X + 1 < W and g.get(X + 1, Y) == B}
        self.assertEqual(len(border), 1)                    # smooth: a straight border stays one straight line
        with open(out, "wb") as fh:                         # winding (the modder's other pick) and no relief: as is
            fh.write(upscale.regions_scaled(rpath, {A, B}, upscale.coast_mask(rpath, {A, B}, True, "winding"), (),
                                            {}, natural=True, edges="winding"))
        g = read_tga(out)
        border = {X for X in range(W) for Y in range(W) if g.get(X, Y) == A and X + 1 < W and g.get(X + 1, Y) == B}
        self.assertEqual(len(border), 1)
        # with the old map's relief - land rising to the east, ridges and valleys across it - the border bends by
        # them (a tester's report #195: by the land's own shapes, not by golden-ratio waves)
        hpath = os.path.join(self.root, "heights.tga")
        write_tga(hpath, 2 * n + 1, 2 * n + 1, [[(min(255, 40 + 6 * x + (50 if (y // 4) % 2 else 0)),) * 3
                                                 for x in range(2 * n + 1)] for y in range(2 * n + 1)])
        with upscale.relief(hpath):
            with open(out, "wb") as fh:
                fh.write(upscale.regions_scaled(rpath, {A, B}, upscale.coast_mask(rpath, {A, B}, True, "winding"),
                                                (), {}, natural=True, edges="winding"))
        g = read_tga(out)
        border = {X for X in range(W) for Y in range(W) if g.get(X, Y) == A and X + 1 < W and g.get(X + 1, Y) == B}
        self.assertGreater(len(border), 1)
        self.assertEqual(upscale.RELIEF, [])                                   # only while the x3 runs

    def test_bigger_map_bends_by_the_old_relief(self):
        """Report #195: the x3 lines bent by the old map's own relief, not golden-ratio waves: where a ridge comes down
        to the sea the coast runs out (the bend looks inland, uphill: land), where a valley does it draws back (it
        looks seaward: a bay); flat land, no relief's bend; a river on a straight run lies on the lower side of its valley; a
        one-tile islet loses the corner facing the lowest ground."""
        from campaign_editor import upscale as U
        n = 21                                                     # points: 10 x 10 old tiles; the sea to the west
        def h(x, y):
            v = 20 + 8 * x
            if 10 <= y <= 12:
                v += 60                                            # a ridge running out to the west at tile 5
            if 4 <= y <= 6:
                v -= 15                                            # a valley at tile 2
            return (max(1, min(255, v)),) * 3
        path = os.path.join(self.root, "heights.tga")
        write_tga(path, n, n, [[h(x, y) for x in range(n)] for y in range(n)])
        self.assertEqual(U._warp(10, 16), (0.0, 0.0))             # no x3 running: no bend
        with U.relief(path):
            ridge, valley = U._warp(3 * 3 + 1, 3 * 5 + 1), U._warp(3 * 3 + 1, 3 * 2 + 1)
            self.assertGreater(ridge[0], 0.3)                      # inland (east, uphill): a cape
            self.assertLess(valley[0], -0.3)                       # seaward: a bay
            self.assertTrue(all(abs(v) <= U.BEND + 1e-9 for v in ridge + valley))
            self.assertEqual(U._meander(3, 3, True), -1)           # tile 3: lower to the south (the valley side)
            corners = [(0, 0), (2, 0), (2, 2), (0, 2)]
            self.assertIn((0, 0), U._cut_corners(corners, 3, 3))   # toward the valley and the sea: south-west
        self.assertEqual(U.RELIEF, [])
        flat = os.path.join(self.root, "flat.tga")
        write_tga(flat, n, n, [[(90, 90, 90)] * n for _ in range(n)])
        with U.relief(flat) as r:                                  # flat land: no relief's bend, only a smooth
            self.assertTrue(all(v == (0.0, 0.0) for v in r.shift))  # coast's small detail (half as rough)
            self.assertTrue(all(abs(v) <= 0.7 for v in U._warp(16, 16)))
            self.assertEqual(U._meander(3, 3, True), 0)

    def test_bigger_map_small_islands_and_coast_rules(self):
        """x3 rules from the user's look at the bigger map: a small islet or lake keeps its size and comes out whole and
        round (no cross / clover), a cape one tile wide stays one strip (no line of crosses); the sea beside the land
        is shallow, the beach one pixel wide, no speck of deep water in the shallows."""
        from campaign_editor import upscale
        n = 12
        islet = lambda x, y: not (x == 6 and y == 6) and not (x == 6 and y == 7)          # a two-tile islet
        m = upscale._smooth_water(islet, n, n)
        land = {(X, Y) for X in range(m.W) for Y in range(m.H) if m[(X, Y)]}
        self.assertEqual(len(land), 18)                                                   # its size kept
        start = next(iter(land))
        seen, st = {start}, [start]
        while st:
            a, b = st.pop()
            for q in ((a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)):
                if q in land and q not in seen:
                    seen.add(q)
                    st.append(q)
        self.assertEqual(seen, land)                                                      # one piece
        cape = lambda x, y: not (y == 6 and x <= 8)                                        # a cape one tile wide
        m = upscale._smooth_water(cape, n, n)
        for X in range(3, 3 * 8):                                    # along it, at least 2 pixels across everywhere
            self.assertGreaterEqual(sum(1 for Y in range(m.H) if m[(X, Y)]), 2, X)
        # the ground: deep water touching the land, a beach two wide, a speck of deep water
        land_c, deep, beach, shallow = (0, 128, 0), (128, 0, 0), (255, 255, 255), (196, 0, 0)
        px = [[deep] * 30 for _ in range(30)]
        for y in range(30):
            for x in range(10):
                px[y][x] = land_c
            px[y][10] = beach
            px[y][11] = beach
        px[15][20] = deep
        for y in range(12, 19):
            for x in range(12, 26):
                if (x, y) != (20, 15):
                    px[y][x] = shallow
        path = os.path.join(self.root, "g.tga")
        write_tga(path, 30, 30, px)
        with open(path, "rb") as fh:
            out = upscale.shallow_coast(fh.read())
        with open(path, "wb") as fh:
            fh.write(out)
        from campaign_editor.tga import read_tga
        g = read_tga(path)
        self.assertEqual(g.get(10, 5), land_c)                        # no beach on the bigger map: the land round it
        self.assertEqual(g.get(11, 5), land_c)                        # (it is land - never sea ground on the land)
        self.assertEqual(g.get(12, 5), shallow)                       # the sea within a tile of the coast is shallow
        self.assertEqual(g.get(13, 5), shallow)
        self.assertEqual(g.get(20, 15), shallow)                      # the speck of deep water joins the shallows
        self.assertEqual(g.get(28, 2), deep)                          # the open sea stays deep

    def test_bigger_map_river_reaches_the_sea_by_one_pixel(self):
        """R-20261014-5D5543 / C73129: after x3 a river ran 2-3 pixels along the shore past its mouth - the game drew
        it lying on the beach with a hook. river_mouths takes the dead-end pixels on the shore out, one by one from
        the end: one pixel by the water stays, as in the games' own maps; a fork inland is left alone."""
        from campaign_editor import upscale
        from campaign_editor.tga import read_tga_bytes
        W, H = 6, 5
        river, none = (0, 0, 255), (0, 0, 0)
        f = [[none] * W for _ in range(H)]
        for t in ((0, 1), (1, 1), (2, 1), (3, 1), (3, 2), (3, 3)):   # along y = 1, then down the shore at x = 3
            f[t[1]][t[0]] = river
        heights = [[(0, 0, 253) if X >= 9 else (40, 40, 40) for X in range(2 * W + 1)] for _ in range(2 * H + 1)]
        fp, hp = os.path.join(self.root, "f.tga"), os.path.join(self.root, "h.tga")
        write_tga(fp, W, H, f)
        write_tga(hp, 2 * W + 1, 2 * H + 1, heights)
        out, n = upscale.river_mouths(open(fp, "rb").read(), open(hp, "rb").read())
        self.assertEqual(n, 2)
        g = read_tga_bytes(out)
        self.assertEqual([g.get(3, y) for y in (1, 2, 3)], [river, none, none])   # the mouth stays, the run goes
        self.assertEqual(g.get(0, 1), river)

    def test_bigger_map_edges_three_ways(self):
        """x3 lines drawn three ways (the modder picks in the x3 window): smooth, light (1.5 x weaker) and winding.
        The blur's weights add up to one, every old middle keeps its kind, a one-tile river of sea tiles on a
        diagonal runs on unbroken in both smooth ways, and the lone middle of a one-tile islet gets a small piece of
        land round it (no single tile in the water)."""
        from campaign_editor import upscale
        for e in ("smooth", "light"):
            for X, Y, pts in upscale._smooth_sources(5, 5, e):
                self.assertAlmostEqual(sum(wt for _, _, wt in pts), 1.0, 6)
        n = 16
        sea = lambda x, y: x == y or (x, y) == (3, 12)                 # a diagonal river, a one-tile lake
        islet = lambda x, y: not (x == 12 and y == 3)                   # sea everywhere but one tile
        for e in ("smooth", "light"):
            m = upscale._smooth_water(sea, n, n, e)
            wet = {(X, Y) for X in range(m.W) for Y in range(m.H) if not m[(X, Y)]}
            start = (1, 1)
            seen, st = {start}, [start]
            while st:
                a, b = st.pop()
                for q in ((a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)):
                    if q in wet and q not in seen and abs(q[0] - q[1]) < 6:
                        seen.add(q)
                        st.append(q)
            self.assertIn((3 * n - 2, 3 * n - 2), seen, e)               # the river runs on to the far corner
            for x in range(n):
                for y in range(n):
                    self.assertEqual(m[(3 * x + 1, 3 * y + 1)], not sea(x, y))
            m = upscale._smooth_water(islet, n, n, e)
            c = (3 * 12 + 1, 3 * 3 + 1)
            self.assertTrue(m[c] and sum(m[(c[0] + a, c[1] + b)] for a, b in ((1, 0), (-1, 0), (0, 1), (0, -1))) >= 2)

    def test_addon_told_its_game(self):
        """A script for both games is told the game it is put in (Avoid Growth guessed Barbarian Invasion was
        Medieval II and put its tick in the wrong place): 'rome' for Rome and BI, 'medieval2' for Medieval II."""
        from campaign_editor import addons as A, limits as L
