    def test_map_size_names_what_stands_on_the_part_cut_off(self):
        """Map size: the places are read once and any cut checked against them at once (the window checks each
        dragged edge and rings them red on the map) - a town and the character in it on the columns cut off are
        named with their tiles, nothing when tiles are only added; the refusal of a cut says the same."""
        from campaign_editor import mapresize as MR
        from campaign_editor.plan import Plan
        mod = ModData(self.root)
        img = mod.region_map("test")
        found = MR.places(mod, "test")
        self.assertEqual(MR.blocking(found, img.width, img.height), [])
        self.assertEqual(MR.blocking(found, img.width, img.height, left=3, right=1, top=2, bottom=5), [])
        cut = MR.blocking(found, img.width, img.height, left=-2)            # columns 0 and 1 go
        self.assertEqual([x[1] for x in cut], [(1, 1), (2, 2), (1, 1)])    # B_R's town at column 2: the new edge
        self.assertEqual([x[2:] for x in cut], [("town", "A_R"), ("town", "B_R"), ("character", "family")])
        self.assertIn("the town of A_R (1, 1)", cut[0][0])
        self.assertIn("Aaron Alphid", cut[2][0])
        self.assertEqual(MR.off_map(mod, "test", -2, 0, 0, 0), [x[0] for x in cut])
        self.assertEqual([x[2:] for x in MR.blocking(found, img.width, img.height, right=-1)],
                         [("town", "B_R")])        # column 3 holds nothing, but B_R's town would be on the new edge
        # report #158: a town (or port) the cut leaves on the new edge goes too - the game cannot place one there;
        # a character there stays
        edge = MR.blocking(found, img.width, img.height, left=-1)
        self.assertEqual([x[2:] for x in edge], [("town", "A_R")])
        self.assertEqual(MR.lost_factions(mod, "test", left=-1), MR.lost_factions(mod, "test", left=-2))
        with self.assertRaises(ValueError) as said:
            MR.plan_resize(Plan(mod, "map", "map_size", {}), "test", left=-2)
        self.assertIn("the town of A_R", str(said.exception))

    def test_map_cut_takes_off_what_stands_there_after_a_yes(self):
        """A cut asked to clear its part (the modder said yes): the town there goes with its region everywhere (all its
        land was on the part cut off), an agent there goes, a family member moves into the nearest town his faction
        keeps; a faction that would keep no town is refused before anything is written. Restore gives every byte
        back."""
        from campaign_editor import mapresize as MR
        from campaign_editor.plan import Plan, restore
        self._three_towns()
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        write(os.path.join(camp, "descr_strat.txt"), STRAT.replace(
            "\ncharacter\tAaron Alphid, named character, leader, age 40, , x 1, y 1",
            "\nsettlement\n{\n\tlevel village\n\tregion C_R\n\tpopulation 400\n}\n\n"
            "character\tAaron Alphid, named character, leader, age 40, , x 5, y 1").replace(
            ";#####<\n\n;#####>\nfaction\tslave",
            "character\tSilus, spy, age 30, , x 4, y 2\n;#####<\n\n;#####>\nfaction\tslave", 1))
        before = tree_hash(self.root)
        mod = ModData(self.root)
        self.assertEqual(MR.places(mod, "test")[-2][2:], ("character", "spy"))
        img = mod.region_map("test")
        hit = MR.blocking(MR.places(mod, "test"), img.width, img.height, right=-2)
        words = " | ".join(MR.cut_words(hit))
        for want in ("1 town(s) with their regions: C_R", "1 army / fleet / agent (1 spy)", "1 family member(s)"):
            self.assertIn(want, words)
        with self.assertRaises(ValueError) as said:                 # without the yes: refused, as before
            MR.plan_resize(Plan(mod, "map", "map_size", {}), "test", right=-2)
        self.assertIn("the town of C_R", str(said.exception))
        with self.assertRaises(ValueError) as said:                 # both of alpha's towns on the parts cut off
            MR.plan_resize(Plan(mod, "map", "map_size", {}), "test", left=-2, right=-2, clear=True)
        self.assertIn("alpha would keep no town", str(said.exception))
        plan = Plan(mod, "map", "map_size", {})
        MR.plan_resize(plan, "test", right=-2, clear=True)
        bdir = plan.apply()
        mod = ModData(self.root)
        self.assertEqual((mod.region_map("test").width, mod.region_map("test").height), (4, 4))
        self.assertNotIn("C_R", mod.regions("test"))
        with open(os.path.join(camp, "descr_strat.txt"), encoding="latin-1") as fh:
            strat = fh.read()
        self.assertNotIn("region C_R", strat)
        self.assertNotIn("Silus", strat)
        self.assertIn("Aaron Alphid, named character, leader, age 40, , x 1, y 1", strat)
        restore(mod, bdir)
        self.assertEqual(tree_hash(self.root), before)

    def test_map_cut_gives_the_land_left_of_a_town_it_takes_to_the_wasteland(self):
        """A cut that takes a town off but leaves part of its land: the region goes from the files and the land left
        never stays without a region (report #178: 'Region has no descr_regions.txt entry', then a crash). With REX /
        M2EX it goes to the ONE common wasteland (the user, 2026-10-10: 'variant B - all the free land into ONE
        common wasteland region'), made once and kept for the next; without an engine to the neighbour that stays
        (the original exes know no wasteland); land with no neighbour to go to is refused in words."""
        from campaign_editor import mapresize as MR
        from campaign_editor import regiondelete as RD
        from campaign_editor.plan import Plan, restore
        self._three_towns()
        for engine in (False, True):
            if engine:
                write(os.path.join(self.root, "data", "descr_ex.txt"), "max_factions 21\n")
            before = tree_hash(self.root)
            mod = ModData(self.root)
            self.assertEqual(RD.common_wasteland(mod, "test") is not None, engine)
            plan = Plan(mod, "map", "map_size", {})
            MR.plan_resize(plan, "test", right=-1, clear=True)
            bdir = plan.apply()
            mod = ModData(self.root)
            regions = mod.regions("test")
            self.assertNotIn("C_R", regions)                         # the region is gone from the files
            img = mod.region_map("test")
            self.assertEqual(sum(1 for _ in img.find((0, 255, 0))), 0)          # none of its colour left
            known = {v["colour"] for v in regions.values()} | {(0, 0, 0), (255, 255, 255)}
            self.assertEqual({img.get(x, y) for x in range(img.width) for y in range(img.height)} - known, set())
            if engine:
                self.assertTrue(regions["Wasteland"]["wasteland"])
                self.assertEqual(sum(1 for _ in img.find(regions["Wasteland"]["colour"])), 4)
                # the next free land joins the same one: no second wasteland is made
                self.assertEqual(RD.common_wasteland(mod, "test")[:1] + RD.common_wasteland(mod, "test")[2:],
                                 ("Wasteland", False))
            else:
                self.assertEqual(sum(1 for _ in img.find((0, 0, 255))), 7 + 4)    # B_R took the 4 tiles left
            restore(mod, bdir)
            self.assertEqual({k: v for k, v in tree_hash(self.root).items() if not k.startswith("CampaignEditor_")},
                             {k: v for k, v in before.items() if not k.startswith("CampaignEditor_")})

    def test_check_problems_worst_first_with_the_place_to_fix(self):
        """Check mod files groups its problems by when the game meets them - would not start, campaign loads with
        something lost, battle, play - and names the place each is put right in."""
        from campaign_editor import check as CK
        probs = ["descr_strat.txt has a block for 'x', which descr_sm_factions.txt does not know",
                 "win condition of 'y' names a region the map lacks z",
                 "A (b): a town without its governor's building (core 1) - the game stops: 'has not been given a "
                 "core building'",
                 "3 battle model(s) give a faction its texture but no weapons texture"]
        self.assertEqual([CK.when_of(p) for p in probs], ["start", "play", "load", "battle"])
        self.assertEqual([h for h, _ in CK.grouped(probs)], [h for _, h, _ in CK.WHEN])
        self.assertEqual(CK.fix_of(probs[2])[1], "edit")
        self.assertEqual(CK.fix_of(probs[3])[1], "units")
        self.assertIsNone(CK.fix_of("something nobody knows"))

    def test_credits_page_and_window_text(self):
        """CREDITS.md - the page on GitHub and the Tools > Credits... window - names the author and its sections;
        the window shows it without Markdown marks (bold, italics, links keep their words), a paragraph or item over
        several lines as one block."""
        from campaign_editor import credits as CR
        parts = CR.blocks(CR.read())
        heads = [w for k, w in parts if k == "heading"]
        for want in ("The author", "A special thank you", "Thank you for the reports", "Supporters",
                     "How to get in"):
            self.assertIn(want, heads)
        self.assertEqual(parts[0], ("title", "Credits"))
        self.assertIn('Pfadfinder ("Adam")', " ".join(w for _, w in parts))
        self.assertFalse([w for _, w in parts if "**" in w or "](" in w])
        self.assertEqual(CR.blocks("# T\n\n- one\n  two\n> said\n> it\n\nA *b*\nc [d](x)"),
                         [("title", "T"), ("item", "one two"), ("quote", "said it"), ("text", "A b c d")])

    def test_start_the_game_checks_first(self):
        """Before the game starts: a script that starts an exe the game folder lacks is refused, a Medieval II .cfg
        not naming the mod's folder is asked about, a 32-bit exe without Large Address Aware is a note."""
        from campaign_editor import launch

        def put(path, data=b""):
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "wb") as fh:
                fh.write(data)
        pe = bytearray(512)
        pe[:2], pe[60:64] = b"MZ", (128).to_bytes(4, "little")
        pe[128:132], pe[132:134] = b"PE\0\0", (0x14c).to_bytes(2, "little")
        m2 = os.path.join(self.root, "m2p")
        put(os.path.join(m2, "medieval2.exe"), bytes(pe))
        self.assertIs(launch.large_address_aware(os.path.join(m2, "medieval2.exe")), False)
        pe[150:152] = (0x20).to_bytes(2, "little")
        put(os.path.join(m2, "medieval2.exe"), bytes(pe))
        self.assertIs(launch.large_address_aware(os.path.join(m2, "medieval2.exe")), True)
        put(os.path.join(m2, "mods", "x", "data", "descr_sm_factions.txt"))
        put(os.path.join(m2, "mods", "x", "x.cfg"), b"[features]\r\nmod = mods/y\r\n")
        data = os.path.join(m2, "mods", "x", "data")
        how = launch.start_line(data)
        # names mods/y, not mods/x: the folder is said to be misnamed, and the .cfg asked about
        self.assertEqual([s for s, _ in launch.problems(how, data)], [True, False])
        put(os.path.join(m2, "mods", "x", "x.cfg"), b"[features]\r\nmod = mods/x\r\n")
        self.assertEqual(launch.problems(how, data), [])
        put(os.path.join(m2, "mods", "x", "Start_x.bat"), b"kingdoms.exe @mods/x/x.cfg\r\n")
        bat = launch.start_line(data)
        self.assertEqual([s for s, _ in launch.problems(bat, data)], [True])       # kingdoms.exe is not there
        # the mod's own files look for another folder (a tester's mod unpacked into 'Neuer Ordner'): said first
        self.assertIsNone(launch.named_folder(data))
        put(os.path.join(m2, "mods", "x", "Start_x.bat"), b"cd ..\\..\r\nM2EX.exe @mods\\kirsi\\configuration.cfg\r\n")
        put(os.path.join(m2, "mods", "x", "x.cfg"), b"[features]\r\nmod = mods/kirsi\r\n")
        self.assertEqual(launch.named_folder(data), "kirsi")
        self.assertTrue(any(st and "rename the folder to kirsi" in w for st, w in launch.problems(bat, data)))

    def test_start_the_game_with_the_loaded_mod(self):
        """Start the game: the mod's own start script (Start_<name>.bat first; not an unpacker's .bat), else the
        engine's start script in the game folder naming it (REX's Barbarian Invasion.bat -bi, M2EX's Teutonic.bat
        mods/teutonic), else the engine's line (-nm -show_err -mod:<name>, --features.mod=mods/<name>, @<cfg>); the
        plain game with its exe; no exe or no .cfg said in words; not on Windows: the line to start by hand."""
        from campaign_editor import launch

        def put(path, text=""):
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w") as fh:
                fh.write(text)

        def data(root, *parts):
            d = os.path.join(root, *parts, "data")
            put(os.path.join(d, "descr_sm_factions.txt"))
            return d
        rome = os.path.join(self.root, "rome")
        put(os.path.join(rome, "REX.exe"))
        put(os.path.join(rome, "Barbarian Invasion.bat"), 'start "" "%~dp0REX.exe" -bi\r\n')
        plain = launch.start_line(data(rome))
        self.assertEqual((os.path.basename(plain["exe"]), plain["args"]), ("REX.exe", []))
        self.assertEqual(launch.start_line(data(rome, "bi"))["bat"], os.path.join(rome, "Barbarian Invasion.bat"))
        self.assertEqual(launch.start_line(data(rome, "alexander"))["args"], ["-alx"])
        hlr = data(rome, "HLR")
        put(os.path.join(rome, "HLR", "unpack_all.bat"), "unpacker.exe --source=packs\r\n")
        self.assertEqual(launch.start_line(hlr)["args"], ["-nm", "-show_err", "-mod:HLR"])   # no unpacker's script
        put(os.path.join(rome, "HLR", "Start_mod.bat"), "cd ..\\.\r\nstart REX.exe -nm -show_err -mod:HLR -multirun\r\n")
        self.assertEqual(os.path.basename(launch.start_line(hlr)["bat"]), "Start_mod.bat")
        put(os.path.join(rome, "HLR", "Start_HLR.bat"), "start REX.exe -mod:HLR\r\n")
        self.assertEqual(os.path.basename(launch.start_line(hlr)["bat"]), "Start_HLR.bat")
        deeper = data(rome, "mods", "my_r2")            # report #177: a Rome mod in mods/<name>
        self.assertEqual(launch.start_line(deeper)["args"], ["-nm", "-show_err", "-mod:mods/my_r2"])
        self.assertEqual(launch.what(deeper), ("Rome", "my_r2"))
        put(os.path.join(rome, "my_r2.bat"), "start REX.exe -nm -mod:mods/my_r2\r\n")
        self.assertEqual(launch.start_line(deeper)["bat"], os.path.join(rome, "my_r2.bat"))
        m2 = os.path.join(self.root, "m2")
        put(os.path.join(m2, "M2EX.exe"))
        put(os.path.join(m2, "Teutonic.bat"), 'start "" "%~dp0M2EX.exe" --features.mod=mods/teutonic\r\n')
        self.assertEqual(launch.start_line(data(m2, "mods", "teutonic"))["bat"], os.path.join(m2, "Teutonic.bat"))
        put(os.path.join(m2, "mods", "DaC", "DaC_launcher.bat"), "medieval2.exe @mods/DaC/DaC.cfg\r\n")
        dac = launch.start_line(data(m2, "mods", "DaC"))   # its own script starts the plain exe: M2EX's line instead
        self.assertEqual((os.path.basename(dac["exe"]), dac["args"], dac["cwd"]),
                         ("M2EX.exe", ["--features.mod=mods/DaC"], m2))
        old = os.path.join(self.root, "old")
        put(os.path.join(old, "medieval2.exe"))
        with self.assertRaises(ValueError):
            launch.start_line(data(old, "mods", "x"))                 # no script, no x.cfg
        put(os.path.join(old, "mods", "x", "x.cfg"), "[features]\r\nmod = mods/x\r\n")
        self.assertEqual(launch.start_line(os.path.join(old, "mods", "x", "data"))["args"], ["@mods\\x\\x.cfg"])
        bare = os.path.join(self.root, "bare")
        put(os.path.join(bare, "RomeTW-BI.exe"))
        with self.assertRaises(ValueError):
            launch.start_line(data(bare))                             # no RomeTW.exe for the plain game
        self.assertEqual(os.path.basename(launch.start_line(data(bare, "bi"))["exe"]), "RomeTW-BI.exe")
        if sys.platform != "win32":
            with self.assertRaises(OSError) as e:
                launch.start(launch.start_line(hlr))
            self.assertIn("Start_HLR.bat", str(e.exception))
        from unittest import mock
        with mock.patch.object(launch.sys, "platform", "win32"), mock.patch.object(launch.subprocess, "Popen") as run:
            launch.start(launch.start_line(hlr))                      # the script, run from its own folder
            self.assertEqual(run.call_args[0][0], ["cmd", "/c", os.path.join(rome, "HLR", "Start_HLR.bat")])
            self.assertEqual(run.call_args[1]["cwd"], os.path.join(rome, "HLR"))
            launch.start(dac)                                         # the engine, from the game folder
            self.assertEqual(run.call_args[0][0], [os.path.join(m2, "M2EX.exe"), "--features.mod=mods/DaC"])
            self.assertEqual(run.call_args[1]["cwd"], m2)

    def test_bigger_map_says_what_to_look_over(self):
        """Once the map is 3 x bigger the window says what to look over by hand (no rule draws every map 100 %
        right) and adds what the editor could not do itself - short, at most 8 lines of it."""
        from campaign_editor import upscale
        text = upscale.look_over()
        for words in ("100 %", "coasts and river mouths", "along a river", "Put the old map back", "Paint with"):
            self.assertIn(words, text)
        many = ["campaign_script.txt: line(s) %d hold numbers" % k + " x" * 400 for k in range(10)]
        text = upscale.look_over(many)
        self.assertIn("could not do itself", text)
        self.assertIn("... and 2 more in the editor's log", text)
        self.assertTrue(all(len(line) <= 302 for line in text.splitlines()))
        # the original exes skip coastlines past their strip buffer; REX / M2EX grow it
        self.assertIn("without sand or surf", upscale.look_over())
        self.assertNotIn("without sand or surf", upscale.look_over(engine="REX.exe"))

    def test_bigger_map_natural_heights(self):
        """x3 heights the natural way: the sea and land as the mask says, no slope (times the heights' growth)
        steeper than the old map's steepest, a river's valley lower than the land beside it, the land round a town
        smooth, and the .hgt the game reads made the same way; the same map, the same heights."""
        from campaign_editor import upscale
        import random
        rnd = random.Random(5)
        n = 21                                                       # heights points (10 x 10 tiles)
        SEA = (0, 0, 120)
        grey = [[(v, v, v) for v in (rnd.randrange(20, 240) for _ in range(n))] for _ in range(n)]
        for y in range(n):
            grey[y][0] = SEA                                         # a sea column on the left
        hpath = os.path.join(self.root, "heights.tga")
        write_tga(hpath, n, n, grey)
        mask = upscale.Mask(61, 61)
        for Y in range(61):
            for X in range(3):
                mask[(X, Y)] = True
        rivers = [(15, Y) for Y in range(5, 25)]
        towns = [(22, 22)]
        flat = upscale.smooth_scaled(hpath, "corners", sea=True, mask=mask)
        nat = upscale.smooth_scaled(hpath, "corners", sea=True, mask=mask, natural=True, rivers=rivers, towns=towns,
                                    vertical=3.0)
        self.assertEqual(nat, upscale.smooth_scaled(hpath, "corners", sea=True, mask=mask, natural=True,
                                                    rivers=rivers, towns=towns, vertical=3.0))
        self.assertNotEqual(flat, nat)
        out = os.path.join(self.root, "heights3.tga")
        with open(out, "wb") as fh:
            fh.write(nat)
        from campaign_editor.tga import read_tga
        g, old = read_tga(out), read_tga(hpath)
        steep = max(abs(old.get(x + 1, y)[0] - old.get(x, y)[0]) for x in range(1, n - 1) for y in range(n))
        for X in range(61):
            for Y in range(61):
                c = g.get(X, Y)
                self.assertEqual(c[0] == 0 and c[1] == 0, mask[(X, Y)], (X, Y))
                if X >= 4 and X + 1 < 61:
                    self.assertLessEqual(3 * abs(g.get(X + 1, Y)[0] - c[0]), steep + 3, (X, Y))
        valley = [g.get(31, Y)[0] for Y in range(15, 45)]           # the river's tiles' middles (2X + 1)
        with open(out, "wb") as fh:
            fh.write(flat)
        f = read_tga(out)
        self.assertLess(sum(valley), sum(f.get(31, Y)[0] for Y in range(15, 45)))   # carved
        hgt = os.path.join(self.root, "heights.hgt")
        with open(hgt, "wb") as fh:
            fh.write(struct.pack("<II", n, n) + struct.pack("<%df" % (n * n), *[
                (-5.0 if grey[n - 1 - y][x] == SEA else float(grey[n - 1 - y][x][0])) for y in range(n) for x in range(n)]))
        data = upscale.hgt_scaled(hgt, hpath, mask, 3.0, natural=True, rivers=rivers, towns=towns)
        W, H = struct.unpack_from("<II", data)
        vals = struct.unpack_from("<%df" % (W * H), data, 8)
        self.assertEqual((W, H), (61, 61))
        self.assertTrue(all((v <= 0) == mask[(i % W, i // W)] or v == 0 for i, v in enumerate(vals)))

    def test_bigger_map_shore_falls_as_the_games_own(self):
        """x3 heights by the water: one point is as long in the game on any map, so the shore must fall to the
        water as the games' own maps do (map_heights.hgt medians 1, 2, 3 points from the water: Medieval II 70 / 232 /
        353) - the first land point about 0.3 of the second, the second about 0.65 of the third. A straight 1/3, 2/3
        slope left the x3 shore twice as high as the games' own (a tester's DaC x3: 'terrain too tall near the
        water')."""
        from campaign_editor import upscale
        from campaign_editor.tga import read_tga
        n, SEA = 11, (0, 0, 120)
        grey = [[SEA if x == 0 else (200, 200, 200) for x in range(n)] for _ in range(n)]
        hpath = os.path.join(self.root, "plateau.tga")
        write_tga(hpath, n, n, grey)
        W = 3 * (n - 1) + 1
        mask = upscale.Mask(W, W)
        for Y in range(W):
            for X in range(3):
                mask[(X, Y)] = True
        out = os.path.join(self.root, "plateau3.tga")
        with open(out, "wb") as fh:
            fh.write(upscale.smooth_scaled(hpath, "corners", sea=True, mask=mask, natural=True, vertical=3.0))
        g = read_tga(out)
        for Y in range(6, W - 6):
            d1, d2, d3 = (g.get(X, Y)[0] - 1 for X in (3, 4, 5))
            self.assertLess(d1, d2, Y)
            self.assertLessEqual(d2, d3, Y)
            self.assertLessEqual(d3, 200 / 3.0 + 1, Y)       # never above the old map's own shore (vanilla_shore)

    def test_bigger_map_no_islets_no_spikes(self):
        """x3 heights' coast: a land point the old heights held inside a navigable river (map_regions calls the
        river land) came out as a small square island; corners of an older coast stuck out as thin wedges lying on
        the water's level (they flicker in the game, z-fighting). Afterwards: no land in the river, no point with
        the other kind on 3 or 4 sides except the tiles' middles map_regions decided."""
        from campaign_editor import upscale
        P, S, LAND, WATER = (200, 40, 40), (41, 140, 233), (60, 60, 60), (0, 0, 120)
        n = 8
        regions = [[S if x + y < 4 else P for x in range(n)] for y in range(n)]       # a sea corner, land
        rpath = os.path.join(self.root, "regions.tga")
        write_tga(rpath, n, n, regions)
        hn = 2 * n + 1
        heights = [[WATER if (x + y < 8 or 9 <= x <= 11) and (x, y) != (10, 10) else LAND for x in range(hn)]
                   for y in range(hn)]                                                # a river, a land point in it
        hpath = os.path.join(self.root, "heights.tga")
        write_tga(hpath, hn, hn, heights)
        info = {}
        coast = upscale.coast_mask(rpath, {P}, natural=True)
        upscale.regions_scaled(rpath, {P}, coast, (), info, natural=True)
        agree = upscale._agreement(rpath, hpath, {P})
        wet = upscale.heights_from_tiles(info["land"], agree, upscale.heights_mask(hpath, True))
        W = wet.W
        river = [(X, Y) for X in range(29, 32) for Y in range(27, 34)]                # round the old point 10, 10
        self.assertTrue(all(wet[p] for p in river), [p for p in river if not wet[p]])
        for X in range(1, W - 1):
            for Y in range(1, W - 1):
                if X % 2 and Y % 2:
                    continue
                other = sum(1 for a, b in ((1, 0), (-1, 0), (0, 1), (0, -1)) if wet[(X + a, Y + b)] != wet[(X, Y)])
                self.assertLess(other, 3, (X, Y))

    def test_bigger_map_beach_one_tile_wide(self):
        """The beach stays one tile wide along the new coast, as in both games' own maps (a tester's DaC x3: grown
        3 x it was a wide band of sand)."""
        from campaign_editor import upscale
        from campaign_editor.tga import read_tga
        sea, beach, farm = (196, 0, 0), (255, 255, 255), (0, 128, 0)
        kind = lambda x: sea if x < 2 else (beach if x < 4 else farm)      # points: tile 0 sea, 1 beach, 2-3 farm
        path = os.path.join(self.root, "ground.tga")
        write_tga(path, 9, 9, [[kind(x) for x in range(9)] for y in range(9)])
        wet = upscale.Mask(25, 25)                       # the heights' sea mask: True = sea
        for X in range(25):
            for Y in range(25):
                wet[(X, Y)] = X < 6                      # new tiles 0-2 sea, 3 on is land
        data = upscale.ground_scaled(path, wet, {sea})
        with open(path, "wb") as fh:
            fh.write(data)
        g = read_tga(path)
        tiles = [g.get(2 * t + 1, 13) for t in range(12)]
        self.assertEqual(tiles[:3], [sea] * 3)
        self.assertEqual(tiles[3], beach)                                    # the tile on the sea
        self.assertNotIn(beach, tiles[4:])                                   # none further in
        self.assertFalse([X for X in range(9, 25) if g.get(X, 13) == beach])  # nor the points between

    def test_map_made_three_times_bigger(self):
        """Every tile a 3 x 3 block: towns and characters in their blocks' middles, rivers 1 pixel wide (a corner
        link a staircase), descr_terrain's size x 3 and its heights x 3, map_heights.hgt at the new size (3 x higher),
        map.rwm removed; Restore gives every byte back."""
        from campaign_editor.plan import Plan
        from campaign_editor import upscale
        from campaign_editor.tga import read_tga
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        river, black = (0, 0, 255), (0, 0, 0)
        px = [[black] * 4 for _ in range(4)]
        px[0][0] = px[0][1] = px[1][2] = river              # (0,0)-(1,0) straight, (1,0)-(2,1) a corner
        write_tga(os.path.join(camp, "map_features.tga"), 4, 4, px)
        write(os.path.join(camp, "descr_terrain.txt"), "dimensions\n{\n\twidth  4\n\theight  4\n}\n"
              "heights\n{\n\tmin_sea_height  -3122.256\n\tmax_land_height  7511.272\n}\n")
        import struct
        hp = [[(0, 0, 253) if x < 3 else (51, 51, 51) for x in range(9)] for y in range(9)]   # sea west, land east
        write_tga(os.path.join(camp, "map_heights.tga"), 9, 9, hp)
        with open(os.path.join(camp, "map_heights.hgt"), "wb") as fh:          # the game's own copy, read instead
            fh.write(struct.pack("<II", 9, 9) + struct.pack("<81f", *[(-24.5 if x < 3 else 1502.3)
                                                                     for y in range(9) for x in range(9)]))
        write(os.path.join(camp, "map.rwm"), "cache")
        write_tga(os.path.join(camp, "radar_map1.tga"), 4, 4, [[(9, 90, 9)] * 4 for _ in range(4)])   # the minimap
        with open(os.path.join(camp, "radar_map1.tga"), "rb") as fh:
            radar = fh.read()
        # the campaign's script: campaign-map places move with the map (a tester's DaC: scripted armies stood in the
        # clouds at their old places), battle positions in the same script stay
        write(os.path.join(camp, "campaign_script.txt"),
              "script\n\tspawn_army\n\t\tfaction romans_julii\n"
              "\t\tcharacter\tGaius, named character, age 30, x 1, y 2, family\n"
              "\t\tunit\t\troman generals guard cavalry early\texp 1 armour 0 weapon_lvl 0\n\tend\n"
              "\tsnap_strat_camera 2, 1\t\t\t; the camera 2, 1\n"
              "\treposition_character Gaius Julius, 0, 3\n"
              "\tif I_CharacterTypeNearTile romans_julii named_character, 0 1, 1 and I_TurnNumber > 2\n"
              "\t\treveal_area 0, 0, 1, 2\n\tend_if\n"
              "\tunit_order_move cohort1 100 60 run\n"
              "\tset_camera_bookmark 1, 100, 0, 100, 100, 0, 0\n"
              "\tset_counter ghost 3, 4\n"
              "end_script\n")
        before = tree_hash(self.root)
        mod = ModData(self.root)
        tiles = mod.city_tiles("test")
        plan = Plan(mod, "map", "map_x3", {})
        warn = upscale.plan_upscale(plan, "test")
        bdir = plan.apply()
        with open(os.path.join(camp, "radar_map1.tga"), "rb") as fh:     # the minimap kept (size not tied to the
            self.assertEqual(fh.read(), radar)                            # map; a big one crashes plain Rome)
        script = open(os.path.join(camp, "campaign_script.txt")).read().splitlines()
        self.assertIn("x 4, y 7, family", script[3])                                    # spawned: (1, 2)
        self.assertEqual(script[6], "\tsnap_strat_camera 7, 4\t\t\t; the camera 2, 1")    # comment as it was
        self.assertEqual(script[7], "\treposition_character Gaius Julius, 1, 10")
        self.assertEqual(script[8], "\tif I_CharacterTypeNearTile romans_julii named_character, 1 4, 4 "
                                    "and I_TurnNumber > 2")                            # distance 0 = its block
        self.assertEqual(script[9], "\t\treveal_area 0, 0, 5, 8")                         # whole blocks
        self.assertEqual(script[11:13], ["\tunit_order_move cohort1 100 60 run",          # battle places stay
                                         "\tset_camera_bookmark 1, 100, 0, 100, 100, 0, 0"])
        self.assertTrue(any("campaign_script.txt: line(s) 14 " in w for w in warn))      # not known: by hand
        mod = ModData(self.root)
        self.assertEqual({r: xy for r, xy in mod.city_tiles("test").items()},
                         {r: upscale.new_xy(*xy) for r, xy in tiles.items()})
        s = Strat(mod.load(mod.campaign_file("test", "descr_strat.txt")))
        self.assertIn((4, 4), [c.xy for fb in s.factions for c in fb.characters])        # was (1, 1)
        f = read_tga(os.path.join(camp, "map_features.tga"))
        self.assertEqual((f.width, f.height), (12, 12))
        rivers = {(x, y) for x in range(12) for y in range(12) if f.get(x, y) == river}
        self.assertTrue({(1, 1), (7, 4)} <= rivers)                    # its two ends in their blocks' middles
        self.assertTrue(all((x // 3, y // 3) in {(0, 0), (1, 0), (2, 1), (2, 0), (1, 1)} for x, y in rivers))
        seen, todo = {(1, 1)}, [(1, 1)]                                # (natural rivers: the bend's point moved)
        while todo:
            x, y = todo.pop()
            for q in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if q in rivers and q not in seen:
                    seen.add(q)
                    todo.append(q)
        self.assertEqual(seen, rivers)                                 # one unbroken river, side by side only
        self.assertFalse(any({(x, y), (x + 1, y), (x, y + 1), (x + 1, y + 1)} <= rivers
                             for x in range(11) for y in range(11)))                     # never 2 x 2
        self.assertIn("width  12", open(os.path.join(camp, "descr_terrain.txt")).read())
        self.assertIn("max_land_height  22533.816", open(os.path.join(camp, "descr_terrain.txt")).read())  # x 3
        with open(os.path.join(camp, "map_heights.hgt"), "rb") as fh:
            raw = fh.read()
        hw, hh = struct.unpack_from("<II", raw)
        self.assertEqual((hw, hh), (25, 25))                                   # the picture's new size: 6W+1
        vals = struct.unpack_from("<625f", raw, 8)
        self.assertAlmostEqual(vals[24], 1502.3 * 3, 1)                        # land, 3 x higher
        self.assertTrue(-24.5 * 3 - 0.1 <= vals[0] < 0)          # sea by the coast: the old map's own depth eased
        hi = read_tga(os.path.join(camp, "map_heights.tga"))
        self.assertEqual((hi.width, hi.height), (25, 25))
        self.assertFalse(os.path.exists(os.path.join(camp, "map.rwm")))
        from campaign_editor.plan import restore
        restore(ModData(self.root), bdir)
        self.assertEqual({k: v for k, v in tree_hash(self.root).items() if not k.startswith(("faction_tool_backups", "CampaignEditor_backups"))},
                         before)

    def test_bigger_map_with_an_empty_hgt(self):
        """A tester's Rome mod carried an empty map_heights.hgt (0 bytes): x3 stopped with 'unpack_from requires a
        buffer of at least 8 bytes'. It is made again from the new map_heights.tga instead (as the game converts it),
        said in the warnings; Restore gives the empty file back."""
        from campaign_editor.plan import Plan, restore
        from campaign_editor import upscale
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        write(os.path.join(camp, "descr_terrain.txt"), "dimensions\n{\n\twidth  4\n\theight  4\n}\n"
              "heights\n{\n\tmin_sea_height  -3122.256\n\tmax_land_height  7511.272\n}\n")
        hp = [[(0, 0, 253) if x < 3 else (51, 51, 51) for x in range(9)] for y in range(9)]
        write_tga(os.path.join(camp, "map_heights.tga"), 9, 9, hp)
        open(os.path.join(camp, "map_heights.hgt"), "wb").close()
        before = tree_hash(self.root)
        mod = ModData(self.root)
        plan = Plan(mod, "map", "map_x3", {})
        warn = upscale.plan_upscale(plan, "test")
        self.assertTrue(any("map_heights.hgt was empty" in w for w in warn), warn)
        bdir = plan.apply()
        with open(os.path.join(camp, "map_heights.hgt"), "rb") as fh:
            raw = fh.read()
        self.assertEqual(struct.unpack_from("<II", raw), (25, 25))
        vals = struct.unpack_from("<625f", raw, 8)
        self.assertLess(vals[0], 0)                                           # the sea in the west
        self.assertAlmostEqual(vals[24], 51 * 7511.272 * 3 / 255, 0)          # land: grey x the new top / 255
        restore(ModData(self.root), bdir)
        self.assertEqual({k: v for k, v in tree_hash(self.root).items()
                          if not k.startswith(("faction_tool_backups", "CampaignEditor_backups"))}, before)

    def test_bigger_map_keeps_towns_ports_bridges_and_ground(self):
        """x3 on a map like a tester's DaC: a town in a region descr_regions does not list (Erebor became 9 town
        pixels), a port (ports were left off the water), a land bridge over a strait (left as dots), forests painted
        as dense-forest tile middles with wilderness between (Mirkwood turned to wilderness). Afterwards: one town
        pixel each with its own region round it, the port on land touching the sea and its region, map_regions and
        the heights agree on every tile, every land tile still dense forest, the bridge one unbroken chain."""
        from campaign_editor.plan import Plan
        from campaign_editor import upscale
        from campaign_editor.upscale import _pixels, _heights_sea
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        S, R, B, U, T, P = (40, 140, 230), (255, 0, 0), (0, 0, 255), (10, 200, 10), (0, 0, 0), (255, 255, 255)
        rows = ["SSSSSSSSSS", "SBTBBSSSSS", "SBBBBSSSSS", "SRRRPSUUUS", "SRTRRSUTUS", "SRRRRSUUUS", "SSSSSSSSSS"]
        key = {"S": S, "R": R, "B": B, "U": U, "T": T, "P": P}
        px = [[key[c] for c in row] for row in rows]                   # rows[y], y = 0 at the bottom
        write_tga(os.path.join(camp, "map_regions.tga"), 10, 7, px)
        land = lambda x, y: 0 <= x < 10 and 0 <= y < 7 and px[y][x] != S
        hp, gp = [], []
        for j in range(15):
            hrow, grow = [], []
            for i in range(21):
                tiles = [(a, b) for a in ((i - 1) // 2,) if i % 2 for b in ((j - 1) // 2,) if j % 2] or \
                    [(a, b) for a in {(i - 1) // 2, i // 2} for b in {(j - 1) // 2, j // 2}
                     if 0 <= a < 10 and 0 <= b < 7]
                on = any(land(a, b) for a, b in tiles)
                hrow.append((60, 60, 60) if on else (0, 0, 253))
                grow.append(((0, 64, 0) if i % 2 and j % 2 else (0, 0, 0)) if on else (196, 0, 0))
            hp.append(hrow)
            gp.append(grow)
        write_tga(os.path.join(camp, "map_heights.tga"), 21, 15, hp)
        write_tga(os.path.join(camp, "map_ground_types.tga"), 21, 15, gp)
        fp = [[(0, 0, 0)] * 10 for _ in range(7)]
        for x in (4, 5, 6):
            fp[4][x] = (0, 255, 0)                                     # red land - the strait - the unlisted land
        write_tga(os.path.join(camp, "map_features.tga"), 10, 7, fp)
        mod = ModData(self.root)
        plan = Plan(mod, "map", "map_x3", {})
        upscale.plan_upscale(plan, "test")
        plan.apply()
        _, W, H, _, _, at = _pixels(os.path.join(camp, "map_regions.tga"))
        _, _, _, _, _, hat = _pixels(os.path.join(camp, "map_heights.tga"))
        _, _, _, _, _, gat = _pixels(os.path.join(camp, "map_ground_types.tga"))
        _, _, _, _, _, fat = _pixels(os.path.join(camp, "map_features.tga"))
        sea = _heights_sea(hat)
        self.assertEqual((W, H), (30, 21))
        towns = [(x, y) for y in range(H) for x in range(W) if at(x, y) == T]
        self.assertEqual(sorted(towns), sorted(upscale.new_xy(*t) for t in ((2, 1), (2, 4), (7, 4))))
        for x, y in towns:                                             # its own region (or sea) all round it
            ring = {at(x + a, y + b) for a in (-1, 0, 1) for b in (-1, 0, 1) if a or b}
            self.assertEqual(len(ring - {S}), 1, (x, y, ring))
        self.assertEqual({at(x + 1, y) for x, y in towns if (x, y) == upscale.new_xy(7, 4)}, {U})
        ports = [(x, y) for y in range(H) for x in range(W) if at(x, y) == P]
        self.assertEqual(len(ports), 1)
        (x, y), = ports
        sides = ((1, 0), (-1, 0), (0, 1), (0, -1))
        self.assertFalse(sea(2 * x + 1, 2 * y + 1))                    # a port stands on land
        self.assertTrue(any(sea(2 * (x + a) + 1, 2 * (y + b) + 1) for a, b in sides))
        self.assertTrue(any(at(x + a, y + b) == R for a, b in sides))
        for Y in range(H):
            for X in range(W):
                self.assertEqual(at(X, Y) != S, not sea(2 * X + 1, 2 * Y + 1), (X, Y))   # one coast
                if at(X, Y) != S:
                    self.assertEqual(gat(2 * X + 1, 2 * Y + 1), (0, 64, 0), (X, Y))      # the forest stays
        bridge = {(X, Y) for X in range(W) for Y in range(H) if fat(X, Y) == (0, 255, 0)}
        seen, todo = set(), [next(iter(bridge))]
        while todo:
            q = todo.pop()
            seen.add(q)
            todo += [(q[0] + a, q[1] + b) for a, b in sides if (q[0] + a, q[1] + b) in bridge - seen]
        self.assertEqual(seen, bridge)                                 # one unbroken chain ...
        self.assertTrue({at(*q) for q in bridge} >= {R, U, S})         # ... from land over the water to land

    def test_new_region_colour_on_a_full_map(self):
        """A map whose regions already use the 200 colours the old walk could make (a tester's big map: 'no free
        colour left') still gets a new colour, one no pixel has."""
        from campaign_editor.regionedit import free_colour
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        old = sorted({((i * 97) % 200 + 30, (i * 57) % 200 + 30, (i * 37) % 200 + 30) for i in range(1, 5000)})
        self.assertEqual(len(old), 200)
        px = [old[y * 20:(y + 1) * 20] for y in range(10)]
        write_tga(os.path.join(camp, "map_regions.tga"), 20, 10, px)
        mod = ModData(self.root)
        c = free_colour(mod, "test", [(1, 2, 3)])
        self.assertNotIn(c, set(old))
        self.assertNotEqual(c, (1, 2, 3))
        many = []
        for _ in range(300):                                  # and hundreds more after it
            many.append(free_colour(mod, "test", many))
        self.assertEqual(len(set(many)), 300)
        self.assertFalse(set(many) & set(old))

    def test_new_region_carved_out(self):
        from campaign_editor.edit import edit
        from campaign_editor.tga import read_tga
        mod = ModData(self.root)
        new = {"name": "N_R", "settlement": "Ntown", "creator": "alpha", "rebels": "Rebels", "resources": [],
               "city": (0, 3), "owner": "alpha", "level": "village"}
        painted = {(0, 3): "N_R", (1, 3): "N_R", (0, 2): "N_R"}
        for bad in ({(1, 1): "N_R"}, {(0, 3): "Nowhere"}):          # a town pixel; an unknown region
            with self.assertRaises(ValueError):
                edit(ModData(self.root), "test", "alpha", {"regions": {"painted": bad, "new": [new]}})
        plan = edit(mod, "test", "alpha", {"regions": {"painted": painted, "new": [new]}})
        bdir = plan.apply()
        m2 = ModData(self.root)
        self.assertEqual(m2.regions("test")["N_R"]["settlement"], "Ntown")
        self.assertEqual(m2.city_tiles("test")["N_R"], (0, 3))
        img = read_tga(m2.campaign_file("test", "map_regions.tga"))
        self.assertEqual(img.get(1, 3), m2.regions("test")["N_R"]["colour"])
        self.assertEqual(Strat(m2.load(m2.campaign_file("test", "descr_strat.txt"))).owners()["N_R"], "alpha")
        labels = open(m2.region_labels_file("test"), "rb").read().decode("utf-16")
        self.assertIn("{N_R}", labels)
        self.assertIn("{Ntown}", labels)
        restore(m2, bdir)
        self.assertNotIn("N_R", ModData(self.root).regions("test"))

    def test_new_region_in_a_medieval2_map_with_legion_lines(self):
        """Discord 2026-10-20 (Mekkermann, a Medieval II map whose regions carry 'legion:' lines): a new region got a
        Barbarian Invasion beliefs line ('pagan 100') before its religions { } line - Medieval II read it as the next
        region and found none of the new ones ('cannot find this pixel colour ... in the region_db'). Now a new
        region there is legion + 8 lines + religions, and Load's check takes such lines out of an older file."""
        from campaign_editor import gamefix
        from campaign_editor.edit import edit
        rp = os.path.join(self.root, "data", "world", "maps", "campaign", "test", "descr_regions.txt")
        text = REGIONS.replace("\t1\nB_R", "\t1\n\treligions { catholic 100 pagan 0 }\nB_R").rstrip("\n") + \
            "\n\treligions { catholic 0 pagan 100 }\n"
        text = text.replace("A_R\n", "A_R\n\tlegion: LA\n", 1).replace("B_R\n", "B_R\n\tlegion: LB\n", 1)
        write(rp, text)
        mod = ModData(self.root)
        new = {"name": "N_R", "settlement": "Ntown", "creator": "alpha", "rebels": "Rebels", "resources": [],
               "city": (0, 3), "owner": "alpha", "level": "village"}
        edit(mod, "test", "alpha", {"regions": {"painted": {(0, 3): "N_R", (1, 3): "N_R"}, "new": [new]}}).apply()
        with open(rp, encoding="latin-1") as fh:
            lines = [ln.strip() for ln in fh.read().split("\n")]
        at = lines.index("N_R")
        self.assertTrue(lines[at + 1].startswith("legion:"))
        self.assertTrue(lines[at + 9].startswith("religions {"), lines[at:at + 11])
        self.assertEqual(ModData(self.root).regions("test")["N_R"]["settlement"], "Ntown")
        self.assertIsNone(gamefix.m2_beliefs_lines(ModData(self.root)))
        # an older editor's file: the stray line found and taken out
        with open(rp, encoding="latin-1") as fh:
            old = fh.read().replace("\treligions { catholic 0 pagan 100 }", "\tpagan 100\n\treligions { catholic 0 pagan 100 }", 1)
        write(rp, old)
        found = gamefix.m2_beliefs_lines(ModData(self.root))
        self.assertEqual(len(found["rows"]), 1)
        gamefix.fix_plan(ModData(self.root), [found]).apply()
        self.assertIsNone(gamefix.m2_beliefs_lines(ModData(self.root)))

    def test_new_region_gets_its_slaves_resource_in_rome(self):
        """Rome: every region carries a 'resource slaves' (the enslaved people go there); a new region without one
        stops the game ("could not find slave resource in CE Newland(97), every region must have one" - the
        a tester's test mod). A game whose regions do not all carry one is left alone."""
        from campaign_editor import resources as R
        from campaign_editor.edit import edit
        mod = ModData(self.root)
        img = mod.region_map("test")
        seed = Plan(mod, "res", "", {})
        added = []
        for name, info in mod.regions("test").items():
            cells = [tuple(p) for p in img.find(tuple(info["colour"])) if tuple(p) not in ((0, 3), (1, 3), (0, 2))]
            added.append({"type": "slaves", "xy": cells[0]})
        R.apply(seed, "test", {"added": added})
        seed.apply()
        mod = ModData(self.root)
        new = {"name": "N_R", "settlement": "Ntown", "creator": "alpha", "rebels": "Rebels", "resources": [],
               "city": (0, 3), "owner": "alpha", "level": "village"}
        painted = {(0, 3): "N_R", (1, 3): "N_R", (0, 2): "N_R"}
        plan = edit(mod, "test", "alpha", {"regions": {"painted": painted, "new": [new]}})
        sf = plan.edit(mod.campaign_file("test", "descr_strat.txt"))
        slaves = [r for r in R.read(sf) if r.kind == "slaves"]
        self.assertEqual(len(slaves), len(added) + 1)
        self.assertTrue(any(tuple(r.xy) in painted and tuple(r.xy) != (0, 3) for r in slaves))
        restore(mod, backups(mod)[0])

    def test_slaves_on_the_town_tile_count_for_its_region(self):
        """HLR keeps every region's slaves resource on the town's own tile (a black pixel of map_regions): those
        regions have theirs - none is added - and the check reads descr_regions once, not for every tile (on HLR's
        750 regions Preview of a new faction froze for many minutes)."""
        from unittest import mock
        from campaign_editor import regionedit, resources as R
        mod = ModData(self.root)
        towns = mod.city_tiles("test")
        seed = Plan(mod, "res", "", {})
        R.apply(seed, "test", {"added": [{"type": "slaves", "xy": xy} for xy in towns.values()]})
        seed.apply()
        mod = ModData(self.root)
        plan = Plan(mod, "probe", "", {})
        colours = {k: v["colour"] for k, v in mod.regions("test").items()}
        with mock.patch.object(ModData, "regions", autospec=True, side_effect=ModData.regions) as reads:
            regionedit._slave_resources(plan, "test", {}, colours, [])
        self.assertLessEqual(reads.call_count, 3)
        sf = plan.files[mod.campaign_file("test", "descr_strat.txt")]
        self.assertEqual(len([r for r in R.read(sf) if r.kind == "slaves"]), len(towns))
        restore(mod, backups(mod)[0])

