    def test_medieval_unpack(self):
        # a Medieval II straight from Steam: packs only; the unpacker needs two DLLs next to it
        import stat, sys, tempfile
        from campaign_editor import gamefix
        game = tempfile.mkdtemp()
        os.makedirs(os.path.join(game, "packs"))
        os.makedirs(os.path.join(game, "data"))
        open(os.path.join(game, "packs", "data_0.pack"), "wb").close()
        self.assertIsNone(gamefix.unpack_needed(game))              # no unpacker: nothing to offer
        self.assertIn("Verify integrity", gamefix.unpacker_missing(game))   # ... but it says where to get one
        camp0 = os.path.join(game, "mods", "americas")                      # a Kingdoms campaign the same
        os.makedirs(os.path.join(camp0, "packs"))
        open(os.path.join(camp0, "packs", "data_0.pack"), "wb").close()
        self.assertIn("(americas)", gamefix.unpacker_missing(camp0))
        tools = os.path.join(game, "tools", "unpacker")
        os.makedirs(tools)
        exe = os.path.join(tools, "unpacker.exe")
        with open(exe, "w") as fh:                                  # a stand-in that 'unpacks' - as the real one
            # only after THREE yes answers (the terms, 'are you sure', 'this will overwrite files'; a tester's screen
            # 2026-10-18: two were given, the third read an empty line as no, exit 0 and nothing unpacked)
            fh.write("#!%s\nimport os, sys\nfor q in range(3):\n    if sys.stdin.readline().strip().lower() != 'y':"
                     "\n        sys.exit(0)\nopen(os.path.join('..', '..', 'data', 'descr_sm_factions.txt'), 'w')"
                     ".write('faction x')\n" % sys.executable)
        os.chmod(exe, os.stat(exe).st_mode | stat.S_IEXEC)
        for d in gamefix.UNPACK_DLLS:
            open(os.path.join(game, d), "wb").write(b"dll")
        need = gamefix.unpack_needed(os.path.join(game, "data"))
        self.assertEqual(need["dlls"], list(gamefix.UNPACK_DLLS))
        if os.name != "nt":
            gamefix.unpack(need)
            self.assertTrue(all(os.path.exists(os.path.join(tools, d)) for d in gamefix.UNPACK_DLLS))
            self.assertIsNone(gamefix.unpack_needed(game))          # unpacked now
            self.assertEqual(gamefix.unpacker_missing(game), "")
        # a Kingdoms campaign straight from Steam (a tester: 'no descr_sm_factions.txt in ...\\mods\\british_isles'):
        # its own packs, only a few files in its data - the same offer, with its own unpack script
        camp = os.path.join(game, "mods", "british_isles")
        os.makedirs(os.path.join(camp, "packs"))
        os.makedirs(os.path.join(camp, "data"))
        open(os.path.join(camp, "packs", "british_isles_0.pack"), "wb").close()
        open(os.path.join(tools, "unpack_britannia.bat"), "w").close()
        need = gamefix.unpack_needed(os.path.join(camp, "data"))
        self.assertEqual((need["campaign"], os.path.basename(need["bat"]), need["data"]),
                         ("british_isles", "unpack_britannia.bat", os.path.join(camp, "data")))
        open(os.path.join(camp, "data", "descr_sm_factions.txt"), "w").close()
        self.assertIsNone(gamefix.unpack_needed(camp))              # unpacked: nothing to offer

    def test_beach_is_land_as_in_both_games(self):
        # the beach (white ground) lies on LAND tiles along the coast in both games' own maps (M2TW 503 of 503, Rome
        # 580 of 580; every beach point on land heights) - it was a sea brush allowed on sea tiles only, so its sand
        # lay on the water; now a land brush, refused on the sea like any land ground, inland allowed (Rome has 126)
        from campaign_editor import terrain as T

        class Map:
            w = h = 5

            def is_sea(self, x, y):
                return x >= 2
        self.assertIn(T.BEACH, T.LAND_BRUSHES)
        self.assertNotIn(T.BEACH, T.SEA_BRUSHES)
        self.assertIn(T.BEACH, T.ground_brushes("medieval2", "m2ex")[0])
        self.assertEqual(T.GROUND[T.BEACH], "beach")
        self.assertTrue(T.is_land_ground(T.BEACH))
        self.assertIsNone(T.paint_problem(Map(), "ground", (1, 2), T.BEACH, set()))        # the land by the sea
        self.assertIsNone(T.paint_problem(Map(), "ground", (0, 2), T.BEACH, set()))        # inland too
        self.assertIsNotNone(T.paint_problem(Map(), "ground", (2, 2), T.BEACH, set()))     # the sea: no

    def test_coast_pull_and_push(self):
        """The user (2026-10-09): 'grab a point of the border and pull it - draw shapes that way; push from outside or
        inside to make the line nicer; the relief and the rest follow by itself' (like a painter's liquify). Pull:
        the coast under the brush goes with the mouse, most in its middle, the coast far away stays; Push: from the
        land the land grows, from the water the water does; tiles follow by their middles."""
        from collections import Counter
        from campaign_editor import terrain as T
        from campaign_editor.tga import Image
        W, H = 14, 12                                                       # tiles; land on x < 5
        red, sea = (200, 0, 0), (41, 140, 233)

        def world():
            regions = Image(W, H, [(red if x < 5 else sea) for y in range(H) for x in range(W)])

            class Map:
                w, h, ports, info = W, H, {}, {"red_r": {"colour": red}}

                def is_sea(self, x, y):
                    return regions.get(x, y) == sea

                def region_at(self, x, y):
                    return "red_r" if 0 <= x < W and 0 <= y < H and regions.get(x, y) == red else None
            PW, PH = 2 * W + 1, 2 * H + 1
            heights = Image(PW, PH, [((3, 3, 3) if px <= 10 else (0, 0, 253)) for py in range(PH) for px in range(PW)])
            ground = Image(PW, PH, [((0, 128, 0) if px <= 10 else (64, 0, 0)) for py in range(PH) for px in range(PW)])
            sc = T.ShapeCoast(heights, ground, Map(), set(), {}, Counter({"red_r": 5 * H}), sea, 7511.272, -3406.782)

            def lay(got):
                for q, c in got["heights"].items():
                    heights.set(*q, c)
                for q, c in got["ground"].items():
                    ground.set(*q, c)
                for t, c in got["regions"].items():
                    regions.set(*t, c)
                return got
            return sc, lay, regions

        def shore_x(sc, y):                                                 # the game's shore along row y
            xs = [x for a, b in T.shore_segments(sc.metres, 0, y - 1, 2 * W, y + 1)
                  for (x, yy) in (a, b) if abs(yy - y) < 0.6]
            return max(xs) if xs else None
        sc, lay, regions = world()
        self.assertAlmostEqual(shore_x(sc, 12), 10.5, delta=0.3)
        got = None
        for k in range(8):                                                  # grab the coast, drag it 4 points out
            got = lay(sc.pull((10.5 + 0.5 * k, 12.0), (11.0 + 0.5 * k, 12.0), 4.0))
        self.assertGreater(shore_x(sc, 12), 13.5)                           # the middle went with the mouse
        self.assertAlmostEqual(shore_x(sc, 2), 10.5, delta=0.3)             # far away: as it was
        self.assertEqual(regions.get(6, 5), red)                            # middle (13, 11): land now
        self.assertTrue(got["hgt"])
        self.assertEqual(sc.pull((12.0, 12.0), (12.0, 12.0), 4.0)["heights"], {})   # no move, no change
        sc, lay, regions = world()
        for _ in range(6):
            lay(sc.push((9.0, 12.0), 3.0, True))                            # pushed from the land: it grows
        self.assertGreater(shore_x(sc, 12), 11.5)
        self.assertAlmostEqual(shore_x(sc, 2), 10.5, delta=0.3)
        sc, lay, regions = world()
        for _ in range(6):
            lay(sc.push((11.0, 12.0), 3.0, False))                          # from the water: the water grows
        self.assertLess(shore_x(sc, 12), 9.5)

    def test_coast_as_a_shape(self):
        """The user (2026-10-09, his bay and island in the game: stairs at 90 / 45 degrees, 'can you propose a
        solution'): the game cuts every square of 4 heights points into 2 triangles and lays the water at 0, so the
        coast is kept as a shape - each point's distance from the shore - and the heights near the water follow it
        on one slope: the game's own cut then falls on the edge the brush drew. Tiles follow by their middles (new
        land joins the nearest region), the ground follows, a town keeps land round it; Smooth eases a stair; Apply
        writes the exact heights into map_heights.hgt."""
        import math
        import struct
        from collections import Counter
        from campaign_editor import terrain as T
        from campaign_editor.plan import Plan
        from campaign_editor.tga import Image, read_tga
        W, H = 12, 10                                                       # tiles; land on x < 5
        red, sea = (200, 0, 0), (41, 140, 233)
        regions = Image(W, H, [(red if x < 5 else sea) for y in range(H) for x in range(W)])

        class Map:
            w, h, ports, info = W, H, {}, {"red_r": {"colour": red}}

            def is_sea(self, x, y):
                return regions.get(x, y) == sea

            def region_at(self, x, y):
                return "red_r" if 0 <= x < W and 0 <= y < H and regions.get(x, y) == red else None
        PW, PH = 2 * W + 1, 2 * H + 1
        heights = Image(PW, PH, [((3, 3, 3) if px <= 10 else (0, 0, 253)) for py in range(PH) for px in range(PW)])
        ground = Image(PW, PH, [((0, 128, 0) if px <= 10 else (64, 0, 0)) for py in range(PH) for px in range(PW)])
        top, low = 7511.272, -3406.782
        town = (4, 8)
        sc = T.ShapeCoast(heights, ground, Map(), {town}, {}, Counter({"red_r": 5 * H}), sea, top, low)

        def lay(got):
            for p, c in got["heights"].items():
                heights.set(*p, c)
            for p, c in got["ground"].items():
                ground.set(*p, c)
            for t, c in got["regions"].items():
                regions.set(*t, c)
        a, b = (10.0, 6.0), (17.0, 6.0)                                     # a cape out into the sea, 2 points wide
        got = sc.stroke(a, b, 2.0, True)
        lay(got)
        self.assertIn((7, 2), got["tiles"])                                  # middle (15, 5) inside the cape
        self.assertEqual(regions.get(7, 2), red)
        self.assertTrue(got["hgt"] and all(isinstance(v, float) for v in got["hgt"].values()))
        segs = T.shore_segments(sc.metres, 8, 0, 22, 14)
        for k in range(12):                                                  # the game's shore on the brush's edge
            ang = math.pi / 2 + k * math.pi / 11                             # round the far end and along the sides
            q = (b[0] + 2.0 * math.cos(ang - math.pi), b[1] + 2.0 * math.sin(ang - math.pi))
            if q[0] > 11.5:
                self.assertLess(min(T.seg_dist(q, s0, s1) for s0, s1 in segs), 0.25, q)
        self.assertTrue(T.is_land_ground(ground.get(15, 6)))                 # the ground followed
        self.assertEqual(ground.get(15, 3), T.SHALLOW_SEA)                   # shallow water along the new shore
        # the sea brush over the town: it keeps land round its middle, the rest of its coast goes
        got = sc.stroke((9.0, 17.0), (9.0, 17.0), 2.5, False)
        lay(got)
        self.assertTrue(got["kept"])
        self.assertTrue(T.is_land_height(heights.get(9, 17)))               # the town's middle
        self.assertEqual(regions.get(*town), red)
        # the 3D heights brush on the water (ShapeCoast.lift, the game's way: the water a sheet at 0): the sea's floor
        # raised out of it becomes land - its tile joins the region, the ground follows, the height kept exactly;
        # lowered back under, water again
        mid = (2 * 9 + 1, 2 * 5 + 1)                                        # tile (9, 5), far out at sea
        self.assertLess(sc.metres(*mid), 0)
        got = sc.lift({mid: 120.0})
        lay(got)
        self.assertEqual(got["tiles"], {(9, 5): "land"})
        self.assertEqual(regions.get(9, 5), red)
        self.assertTrue(T.is_land_height(heights.get(*mid)))
        self.assertAlmostEqual(sc.metres(*mid), 120.0)                      # exact: no 29 m step
        self.assertTrue(T.is_land_ground(ground.get(*mid)))
        got = sc.lift({mid: -40.0})
        lay(got)
        self.assertEqual(got["tiles"], {(9, 5): "sea"})
        self.assertEqual(regions.get(9, 5), sea)
        self.assertEqual(ground.get(*mid), T.SHALLOW_SEA)
        got = sc.lift({(9, 17): -50.0})                                     # the town's middle: kept land, said why
        self.assertTrue(got["kept"])
        self.assertGreater(sc.metres(9, 17), 0)
        # Smooth the coast: a stair of tiles (the old tile brush's look) gets shorter, no tile middle lost
        for x, y in ((5, 6), (5, 7), (6, 7)):
            for i in range(3):
                for j in range(3):
                    heights.set(2 * x + i, 2 * y + j, (3, 3, 3))
            regions.set(x, y, red)

        def length():
            return sum(math.hypot(q[0] - p[0], q[1] - p[1]) for p, q in T.shore_segments(sc.metres, 9, 11, 17, 19))
        before = length()
        for _ in range(4):
            lay(sc.smooth((12.0, 14.0), 3.0))
        self.assertLess(length(), before * 0.9)
        self.assertTrue(T.is_land_height(heights.get(9, 17)))
        # Apply: the exact heights go into map_heights.hgt where the picture still has the colour they were made with
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        rows = [[(3, 3, 3) if px <= 10 else (0, 0, 253) for px in range(PW)] for py in range(PH)]
        write_tga(os.path.join(camp, "map_heights.tga"), PW, PH, rows)
        with open(os.path.join(camp, "map_heights.hgt"), "wb") as fh:
            fh.write(struct.pack("<II", PW, PH) + b"".join(struct.pack("<f", T.hgt_value(c, top, low))
                                                           for r in rows for c in r))
        write(os.path.join(camp, "descr_terrain.txt"), "max_land_height %.3f\nmin_sea_height %.3f\n" % (top, low))
        mod = ModData(self.root)
        m = 0.37 * T.SHAPE_SLOPE
        plan = Plan(mod, "terrain", "terrain")
        T.apply(plan, "test", coast={"tiles": {}, "regions": {}, "ground": {}, "heights": {(11, 4): T.tga_colour(
            m, top, low)}, "hgt": {(11, 4): m, (3, 3): 999.0}})
        plan.apply()
        w, h, fl = T.read_hgt(os.path.join(camp, "map_heights.hgt"))
        self.assertAlmostEqual(fl[4 * w + 11], m, places=3)                  # exact
        self.assertAlmostEqual(fl[3 * w + 3], T.hgt_value((3, 3, 3), top, low), places=3)   # stale: left alone
        self.assertEqual(read_tga(os.path.join(camp, "map_heights.tga")).get(11, 4), T.tga_colour(m, top, low))

    def test_ground_on_the_wrong_side_of_the_coast(self):
        """The user (2026-10-09): 'textures crawled onto the water though the tile is not, and the other way round
        holes in the land'. A land ground on a water point of map_heights or a sea ground on a land point is found
        and put right under the heights (the ground round it on its own side; the heights lead); the ground brush
        keeps a coastal tile's ground on its side of the waterline (its 3 x 3 block reaches over the coast); Apply
        does the same with the heights it writes."""
        from campaign_editor import terrain as T
        from campaign_editor.plan import Plan
        from campaign_editor.tga import Image, read_tga
        farm, hills = (0, 128, 0), (128, 128, 64)
        n = 9                                                           # points: land left of x = 4, water from 4
        heights = Image(n, n, [((5, 5, 5) if x < 4 else (0, 0, 253)) for y in range(n) for x in range(n)])
        ground = Image(n, n, [(farm if x < 4 else T.SHALLOW_SEA) for y in range(n) for x in range(n)])
        self.assertEqual(T.ground_off_heights(heights, ground), [])
        ground.set(5, 2, hills)                                         # land texture on the water
        ground.set(1, 6, (64, 0, 0))                                    # a hole of sea (ocean) in the land
        ground.set(6, 6, T.BEACH)                                       # sand on the water
        wrong = T.ground_off_heights(heights, ground)
        self.assertEqual(sorted(wrong), [(1, 6, "land"), (5, 2, "water"), (6, 6, "water")])
        fixed = T.ground_under_heights(heights, ground, wrong)
        self.assertEqual(fixed, {(5, 2): T.SHALLOW_SEA, (1, 6): farm, (6, 6): T.SHALLOW_SEA})
        for p, c in fixed.items():
            ground.set(*p, c)
        self.assertEqual(T.ground_off_heights(heights, ground), [])
        # the same without the fast path (pictures with get() only), and pictures of two sizes: nothing compared

        class Pic:
            def __init__(self, img):
                self.width, self.height, self.get = img.width, img.height, img.get
        ground.set(5, 2, hills)
        self.assertEqual(T.ground_off_heights(Pic(heights), Pic(ground)), [(5, 2, "water")])
        self.assertEqual(T.ground_off_heights(heights, Image(3, 3)), [])
        # the ground brush on the coastal land tile 1 (points 2..4): point 4 is water - it keeps its sea ground
        land_at = T.land_points(heights)
        block = T.ground_changes({(1, 1): hills}, land_at)
        self.assertNotIn((4, 3), block)
        self.assertEqual(block[(3, 3)], hills)
        self.assertEqual(len(T.ground_changes({(1, 1): hills})), 9)                  # no heights: the whole block
        self.assertNotIn((3, 3), T.ground_changes({(1, 1): T.SHALLOW_SEA}, land_at))  # nor sea in the land
        self.assertFalse(land_at(4, 3))
        self.assertTrue(T.land_points(heights, {(4, 3): (2, 2, 2)})(4, 3))           # the coast's points first
        self.assertIsNone(land_at(-1, 0))
        # Apply: the painted ground stays off the water; the coast's new land point under it takes it
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        rows = lambda img: [[img.get(x, y) for x in range(n)] for y in range(n)]      # noqa: E731
        ground.set(5, 2, T.SHALLOW_SEA)
        write_tga(os.path.join(camp, "map_ground_types.tga"), n, n, rows(ground))
        write_tga(os.path.join(camp, "map_heights.tga"), n, n, rows(heights))
        mod = ModData(self.root)
        plan = Plan(mod, "terrain", "terrain")
        T.apply(plan, "test", {(1, 1): hills, (1, 2): hills},
                coast={"tiles": {}, "regions": {}, "ground": {}, "heights": {(4, 5): (2, 2, 2)}})
        plan.apply()
        g = read_tga(os.path.join(camp, "map_ground_types.tga"))
        self.assertEqual(g.get(3, 3), hills)
        self.assertEqual(g.get(4, 3), T.SHALLOW_SEA)                    # water: not painted
        self.assertEqual(g.get(4, 5), hills)                            # made land by the coast in the same Apply
        self.assertEqual(T.ground_off_heights(read_tga(os.path.join(camp, "map_heights.tga")), g), [])

