    def test_upkeep_addon_doubles_and_takes_out_exactly(self):
        """Upkeep x 2 as an add-on of its own (the user, 2026-10-09: 'no huge armies - put in and taken out, on any
        mod'): every unit's upkeep (stat_cost's third number) doubled, the old numbers kept beside the file; Take it
        out puts the file back byte for byte; a unit changed since is left and named."""
        import re as _re
        from campaign_editor import addons as AD, upkeep as UK
        from campaign_editor.plan import Plan
        mod = ModData(self.root)
        edu = mod.file("edu")
        with open(edu, "ab") as fh:                              # two units with their costs (Rome's 6 numbers)
            fh.write(b"\r\ntype             test spear\r\nstat_cost        1, 400, 150, 50, 60, 400\r\n"
                     b"\r\ntype             test horse\r\nstat_cost        2,  690,  215 , 80, 70, 690 ; a comment\r\n")
        with open(edu, "rb") as fh:
            before = fh.read()

        def upkeeps():
            with open(edu, encoding="latin-1") as fh:
                return [int(m.group(1)) for m in _re.finditer(r"^\s*stat_cost\s+[^,]+,[^,]+,\s*(\d+)", fh.read(), _re.M)]
        old = upkeeps()
        self.assertTrue(old)
        a = AD.by_key("upkeep_x2")
        self.assertIsNone(AD.installed(mod, a))
        plan = Plan(mod, "addon", a.key, {})
        AD.plan_install(plan, a, {"FACTOR": 2.0}, mod)
        plan.apply()
        self.assertEqual(upkeeps(), [2 * v for v in old])
        self.assertEqual(AD.installed(ModData(self.root), a), {"FACTOR": 2.0})
        self.assertTrue(os.path.isfile(UK.mark_path(mod)))
        plan = Plan(ModData(self.root), "addon", a.key, {})
        AD.plan_install(plan, a, {"FACTOR": 3.0}, mod)          # again with x 3: from the old numbers, not x 6
        plan.apply()
        self.assertEqual(upkeeps(), [3 * v for v in old])
        plan = Plan(ModData(self.root), "addon", a.key, {})
        AD.plan_remove(plan, a, mod)
        plan.apply()
        with open(edu, "rb") as fh:
            self.assertEqual(fh.read(), before)                 # byte for byte
        self.assertFalse(os.path.isfile(UK.mark_path(mod)))
        self.assertIsNone(AD.installed(ModData(self.root), a))

    def test_one_recruitment_grid_addon(self):
        """One Recruitment Grid (the user, 2026-10-15: on the Add-ons page): Medieval II's recruitment panel as one
        grid, as in Rome - descr_campaign_db.xml's recruitment_sort_simple set to true, put back on Take it out, byte
        for byte; a mod without the file gets the game's copy and loses it again."""
        from campaign_editor import addons as AD, onegrid as OG
        xml = ("<campaign_db>\n  <display>\n    <recruitment_sort_simple bool=\"false\"/>\n  </display>\n"
               "</campaign_db>\n")
        game = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, game)
        write(os.path.join(game, "medieval2.exe"), "exe")
        write(os.path.join(game, "data", "descr_campaign_db.xml"), xml)
        shutil.copytree(self.root, os.path.join(game, "mods", "m"))
        a = AD.by_key("one_recruit_grid")
        self.assertTrue(a.fits("medieval2") and not a.fits("rome"))
        mod = ModData(os.path.join(game, "mods", "m"))
        data = mod.data
        own = os.path.join(data, "descr_campaign_db.xml")
        if os.path.isfile(own):
            os.remove(own)
        for has_own in (True, False):
            if has_own:
                write(own, xml)
            self.assertIsNone(AD.installed(mod, a))
            plan = Plan(mod, "addon", a.key, {})
            AD.plan_install(plan, a, {}, mod)
            plan.apply()
            with open(own, encoding="utf-8") as fh:
                self.assertIn('<recruitment_sort_simple bool="true"/>', fh.read())
            self.assertEqual(AD.installed(ModData(data), a), {})
            plan = Plan(ModData(data), "addon", a.key, {})
            AD.plan_remove(plan, a, mod)
            plan.apply()
            if has_own:
                with open(own, encoding="utf-8") as fh:
                    self.assertEqual(fh.read(), xml)
                os.remove(own)
            else:
                self.assertFalse(os.path.isfile(own))              # the copy it put in is gone again
            self.assertFalse(os.path.isfile(OG.mark_path(mod)))

