    def test_english_text_wins(self):
        # the game reads data/text/english first (Medieval II keeps its tables only there):
        # the tool reads and writes that copy, and a new town gets the core level of its size
        from campaign_editor.edit import edit
        d = os.path.join(self.root, "data", "text")
        write(os.path.join(d, "english", "test_regions_and_settlement_names.txt"), "{Alpha}\t\tA\n", utf16=True)
        write(os.path.join(d, "english", "extra.txt"), "{X}\t\tx\n", utf16=True)
        mod = ModData(self.root)
        self.assertIn(os.path.join("english", "test_regions"), mod.region_labels_file("test"))
        names = [os.path.relpath(p, d) for p in mod.text_files()]
        self.assertIn(os.path.join("english", "extra.txt"), names)
        self.assertNotIn("test_regions_and_settlement_names.txt", names)     # hidden by the english copy
        write(os.path.join(self.root, "data", "export_descr_buildings.txt"),
              "building core_building\n{\n    levels hut hall\n    {\n        hut requires factions { alpha, }\n"
              "        {\n            settlement_min village\n        }\n        hall requires factions { alpha, }\n"
              "        {\n            settlement_min town\n        }\n    }\n}\n")
        new = {"name": "N_R", "settlement": "Ntown", "creator": "alpha", "rebels": "Rebels", "resources": [],
               "city": (0, 3), "owner": "alpha", "level": "town"}
        plan = edit(ModData(self.root), "test", "alpha", {"regions": {"painted": {(0, 3): "N_R"}, "new": [new]}})
        plan.apply()
        m2 = ModData(self.root)
        self.assertIn("{N_R}", open(m2.region_labels_file("test"), "rb").read().decode("utf-16"))
        s = Strat(m2.load(m2.campaign_file("test", "descr_strat.txt")))
        st = next(x for x in s.faction("alpha").settlements if x.region == "N_R")
        from campaign_editor.buildings import settlement_info
        self.assertEqual(settlement_info(s.lines[st.start:st.end]), ("town", [("core_building", "hut")]))

    def test_new_region_takes_after_its_land(self):
        # 'built by' and the rebels left empty: those of the region its land is cut from; the
        # owner's new town takes a garrison in the same Apply (one backup, not two)
        from campaign_editor.edit import edit
        new = {"name": "N_R", "settlement": "Ntown", "creator": "", "rebels": "", "resources": [],
               "city": (0, 3), "owner": "alpha", "level": "village"}
        plan = edit(ModData(self.root), "test", "alpha", {
            "regions": {"painted": {(0, 3): "N_R", (1, 3): "N_R"}, "new": [new]},
            "garrisons": {"N_R": ["alpha general"]}})
        plan.apply()
        m2 = ModData(self.root)
        info = m2.regions("test")["N_R"]
        donor = m2.regions("test")["A_R"]
        self.assertEqual((info["creator"], info["rebels"]), (donor["creator"], donor["rebels"]))
        s = Strat(m2.load(m2.campaign_file("test", "descr_strat.txt")))
        self.assertIn("N_R", [st.region for st in s.faction("alpha").settlements])
        self.assertTrue(any(c.xy == (0, 3) for c in s.faction("alpha").characters))     # its garrison

    def test_new_region_religions_never_broken(self):
        from campaign_editor.regionedit import religions_for
        regions = {"A": {"religions": {"catholic": 90, "pagan": 10}}, "B": {"religions": {"catholic": 90, "pagan": 10}},
                   "C": {"religions": {"islam": 100}}}
        self.assertEqual(religions_for(regions, {"catholic": 0, "pagan": 0}, "C"), {"islam": 100})   # zeros: the donor's
        self.assertEqual(religions_for(regions, None, None), {"catholic": 90, "pagan": 10})         # most common
        self.assertEqual(religions_for(regions, {"pagan": 100}, "C"), {"pagan": 100})             # given, sums to 100

    def test_brought_faction_garrisons_and_family(self):
        # a faction brought from another mod: no armies of its start - a town's garrison is drawn from its own units
        # the way an empty town given on the map gets one (3-6, upkeep capped); its family stands by the capital,
        # its records and family tree after every character (the game crashes on a character after them)
        from types import SimpleNamespace
        from campaign_editor.start import _family, brought_garrison, unit_name
        self.assertIsNone(brought_garrison(SimpleNamespace()))
        plan = SimpleNamespace(new="celts", notes=[], note=lambda f, m: plan.notes.append(m), bring_start={
            "pool": [("celtic spearman", 100), ("gallowglass", 150)], "bodyguard": "unit celtic warlord exp 0",
            "family": {"men": [{"name": "Angus", "line": "character\tAngus, named character, leader, age 65, , x 1, y 2",
                                "rest": ["traits FactionLeader 1"], "bodyguard": "unit celtic warlord exp 0"},
                               {"name": "Brude", "line": "character\tBrude, named character, age 40, , x 9, y 9",
                                "rest": [], "bodyguard": "unit celtic warlord exp 0"}],
                       "records": ["character_record\tKeyne, female, age 47, alive, never_a_leader"],
                       "relatives": ["relative\tAngus, Keyne, end"]}})
        for _ in range(20):
            got = [unit_name(x) for x in brought_garrison(plan)]
            self.assertTrue(3 <= len(got) <= 6 and set(got) <= {"celtic spearman", "gallowglass"}, got)
        f = TextFile.from_bytes("s", b"")
        men, tree = _family(plan, f, plan.bring_start, "Capital", lambda r, what: (5, 6),
                            {"leader": {"name": "Angus"}})
        men = [str(x) for x in men]
        self.assertTrue(any("Brude" in x and "x 5, y 6" in x for x in men))
        self.assertFalse(any("Angus" in x for x in men))                    # the leader is the window's
        self.assertEqual(sum(1 for x in men if "celtic warlord" in x), 1)     # Brude with his bodyguard only
        self.assertEqual(len([x for x in tree if "Keyne" in str(x)]), 2)
        # a captain of another faction joining with a town takes a free name of its own list
        from campaign_editor.start import _own_name
        chunk = ["character\tDumnorix of Bibrax, general, age 20, , x 94, y 90", "army", "unit gallowglass exp 0"]
        used = {"Alpin"}
        got, name = _own_name(plan, f, chunk, "Dumnorix of Bibrax", "general",
                              {"characters": ["Alpin", "Brude"]}, used)
        self.assertEqual((name, got[0].split(",")[0]), ("Brude", "character\tBrude"))
        self.assertIn("Brude", used)
        self.assertEqual(_own_name(plan, f, got, "Brude", "general", {"characters": ["Brude"]}, set())[1], "Brude")

    def test_brought_faction_keeps_the_name_list_typed_in_the_window(self):
        """Report R-20261018-B80774: a faction brought from another mod with a name list typed in the window - the
        other mod's list took its place, so the leader typed from it was refused ('not in the england name list',
        the template named, not the faction). The typed list wins now."""
        from types import SimpleNamespace
        from unittest import mock
        from campaign_editor import factionbring as FB
        notes, called = [], []
        mod = SimpleNamespace(factions=lambda: [("alpha", "c")], file=lambda k: None)
        plan = SimpleNamespace(new="beta", template="alpha", mod=mod, opts={"names": {"characters": ["Adenin"]},
                                                                         "copy_art": False},
                               note=lambda f, m: notes.append(m), warn=lambda f, m: notes.append(m),
                               edit=lambda p: None)
        src = SimpleNamespace(culture=lambda f: None)
        stubs = dict(bring_units=lambda *a: ([], [], {}), start_of=lambda *a: None, bring_sm_files=lambda *a: None,
                     own_select_map=lambda *a: None, bring_characters=lambda *a: None, bring_figures=lambda *a: None,
                     bring_names=lambda *a: called.append(a))
        with mock.patch.multiple(FB, **stubs), mock.patch("campaign_editor.moddata.ModData", lambda p: src), \
                mock.patch("campaign_editor.packs.game_kind", lambda m: "medieval2"):
            FB.overlay(plan, "test", {"src": "/x/data", "faction": "brittany"})
            self.assertEqual(called, [])
            self.assertTrue(any("typed in the window" in n for n in notes))
            plan.opts.pop("names")
            FB.overlay(plan, "test", {"src": "/x/data", "faction": "brittany"})
            self.assertEqual(len(called), 1)                    # none typed: the other mod's lists come along

    def test_brought_faction_family_placed_by_create(self):
        """The tester (2026-10-17): Create faction for every faction brought from another mod stopped with "'list'
        object is not callable" - the family's places by the capital ran into the leader's lines named like the
        land's own(). The whole build with a brought family now writes it."""
