    def test_general_card_is_his_portrait(self):
        # a general's own unit shows his face beside his army's cards, as in the game: the portrait card of the
        # number the character editor picks for his name (portraits/cards/<age>/generals)
        import tempfile
        from campaign_editor.family import general_card
        from campaign_editor.moddata import ModData
        with tempfile.TemporaryDirectory() as root:
            data = os.path.join(root, "data")
            os.makedirs(data)
            with open(os.path.join(data, "descr_sm_factions.txt"), "w") as fh:
                fh.write("faction gauls\nculture barbarian\n")
            for sub in ("portraits/young/generals", "cards/young/generals", "portraits/old/generals",
                        "cards/old/generals"):
                d = os.path.join(data, "ui", "barbarian", "portraits", *sub.split("/"))
                os.makedirs(d)
                for n in ("000.tga", "001.tga"):
                    open(os.path.join(d, n), "w").close()
            mod = ModData(data)
            mod.factions = lambda: [("gauls", "barbarian")]
            got = general_card(mod, "gauls", "character\tBrennus, named character, leader, age 50, , x 1, y 2", False)
            self.assertIsNotNone(got)
            path, words = got
            self.assertIn(os.path.join("cards", "old", "generals"), path)
            self.assertIn("Brennus", words)
            again = general_card(mod, "gauls", "character\tBrennus, named character, age 50, , x 9, y 9", False)
            self.assertEqual(again[0], path)                              # one face a name, every time

    def test_leader_face_replace_writes_a_leader_pic_of_its_own(self):
        """The user, 2026-10-15: the faction's leader's face (the select screen) gets Replace... in both games - a
        faction with no leader_pic_<faction>.tga gets one in the campaign folder (every game reads it first), the size
        of the campaign's other leader pictures, else of a portrait card."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("no Pillow")
        from campaign_editor import factionart as FA
        from campaign_editor.plan import Plan
        mod = ModData(self.root)
        self.assertEqual(FA.leader_pic_size(mod, "test"), (69, 96))
        folder = mod.campaign_dir("test")
        Image.new("RGB", (80, 100), (1, 2, 3)).save(os.path.join(folder, "leader_pic_beta.tga"))
        self.assertEqual(FA.leader_pic_size(mod, "test"), (80, 100))
        src = os.path.join(self.root, "face.png")
        Image.new("RGB", (160, 200), (200, 10, 10)).save(src)
        rel = os.path.relpath(os.path.join(folder, "leader_pic_alpha.tga"), mod.data).replace(os.sep, "/")
        plan = Plan(mod, "art", "art", {})
        FA.write_art(plan, "alpha", rel, src)
        plan.apply()
        with Image.open(os.path.join(folder, "leader_pic_alpha.tga")) as im:
            self.assertEqual(im.convert("RGB").getpixel((10, 10)), (200, 10, 10))

    def test_brought_faction_select_map_is_an_empty_stand_in(self):
        """Report #270 and the user, 2026-10-15: a brought faction keeps nothing of its frame (the template) - its
        faction-select map is not the frame's copy but a stand-in, this map with no land lit (Draw from the map lights
        it once its towns are given); a picture of its own given wins."""
        try:
            import PIL  # noqa: F401
        except ImportError:
            self.skipTest("no Pillow")
        from campaign_editor import factionart as FA
        from campaign_editor import factionbring as FB
        from campaign_editor.plan import Plan
        mod = ModData(self.root)
        plan = Plan(mod, "alpha", "picts", {})
        path = FB.own_select_map(plan, "test", "picts")
        mine = os.path.relpath(os.path.join(mod.campaign_dir("test"), "map_picts.tga"), mod.data).replace(os.sep, "/")
        self.assertEqual(plan.opts["art"][mine], path)
        self.assertNotIn("select_map", plan.opts)                      # nothing drawn in its colour
        from PIL import Image, ImageChops
        bare = FA.map_drawing(mod, "test", [], (128, 128, 128))
        self.assertIsNone(ImageChops.difference(Image.open(path).convert("RGB"), bare).getbbox())
        plan = Plan(mod, "alpha", "picts", {"art": {mine: "/x/own.png"}})
        self.assertIsNone(FB.own_select_map(plan, "test", "picts"))   # a picture of its own wins
        self.assertEqual(plan.opts["art"][mine], "/x/own.png")

    def test_brought_faction_has_no_picture_of_its_frame(self):
        """The user, 2026-10-21: 'I got the Huns' flags - flags, icons, pictures: zero'. Every picture the frame's
        copy put under the new name that the brought faction has none of is made EMPTY (a clear picture, the file
        there for the game); its own pictures, the modder's picks, shared pictures and the select map's stand-in are
        left alone."""
        try:
            import PIL  # noqa: F401
        except ImportError:
            self.skipTest("no Pillow")
