    def test_unit_pack_paths_from_the_game_root(self):
        # Barbarian Invasion's lines name files from the game's root ('bi/data/...'): found under data and written
        # the way the receiving mod reads its own
        from campaign_editor.packs import _data_rel, _rebase_line
        self.assertEqual(_data_rel("bi/data/models_unit/a.tga"), "models_unit/a.tga")
        self.assertEqual(_data_rel("data/models_unit/a.tga"), "models_unit/a.tga")
        self.assertEqual(_data_rel("unit_models/a.mesh"), "unit_models/a.mesh")
        self.assertEqual(_rebase_line("texture celts, bi/data/models_unit/textures/a.tga ; c", "rome"),
                         "texture celts, data/models_unit/textures/a.tga ; c")
        self.assertEqual(_rebase_line("model_flexi data/models_unit/a.cas, max", "rome"),
                         "model_flexi data/models_unit/a.cas, max")
        self.assertEqual(_rebase_line("texture x, mods/m/data/unit_models/a.texture", "medieval2"),
                         "texture x, unit_models/a.texture")

    def test_unit_pack_round_trip(self):
        # a unit taken out with its model, mount, texture, card, texts and recruit place, put into
        # another mod where its names and its model's name are taken: all renamed, nothing overwritten
        from campaign_editor import packs
        from campaign_editor.plan import Plan
        d = os.path.join(self.root, "data")
        write(os.path.join(d, "export_descr_unit.txt"), EDU.replace(
            "ownership\talpha", "soldier\t\talpha_model, 20, 0, 1\nmount\t\tlight horse\nownership\talpha"))
        write(os.path.join(d, "descr_model_battle.txt"),
              "type\t\talpha_model\ntexture\t\talpha, data/models_unit/textures/a.tga\n"
              "model_flexi\t\tdata/models_unit/a.cas, max\n\n"
              "type\t\thorse_model\ntexture\t\talpha, data/models_unit/textures/h.tga\n")
        write(os.path.join(d, "descr_mount.txt"), "type\t\tlight horse\nclass\t\thorse\nmodel\t\thorse_model\n")
        write(os.path.join(d, "models_unit", "textures", "a.tga.dds"), "A-texture")      # Rome keeps .tga.dds
        write(os.path.join(d, "models_unit", "a.cas"), "A-model")
        write(os.path.join(d, "models_unit", "textures", "h.tga.dds"), "H-texture")
        write(os.path.join(d, "export_descr_buildings.txt"),
              "building barracks\n{\n    levels hall\n    {\n        hall requires factions { alpha, }\n"
              "        {\n            capability\n            {\n                recruit \"alpha general\"  0  "
              "requires factions { alpha, }\n            }\n        }\n    }\n}\n")
        write(os.path.join(d, "text", "export_units.txt"),
              "{alpha_general}Alpha Guard\n{alpha_general_descr}Good\nmen\n{alpha_general_descr_short}Good\n",
              utf16=True)
        pack = os.path.join(self.root, "alpha.zip")
        man = packs.export_pack(ModData(self.root), ["alpha general"], pack)
        self.assertEqual(sorted(man["blocks"]["model"]), ["alpha_model", "horse_model"])
        self.assertIn("models_unit/textures/a.tga.dds", man["files"])
        self.assertEqual(man["recruit"][0]["chain"], "barracks")
        # the target: a copy whose alpha_model is another model
        target = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, target)
        shutil.copytree(self.root, os.path.join(target, "mod"))
        troot = os.path.join(target, "mod")
        write(os.path.join(troot, "data", "descr_model_battle.txt"),
              "type\t\talpha_model\nmodel_flexi\t\tdata/models_unit/other.cas, max\n\n"
              "type\t\thorse_model\ntexture\t\talpha, data/models_unit/textures/h.tga\n")
        before = tree_hash(troot)
        manifest, files = packs.read_pack(pack)
        tmod = ModData(troot)
        plan = Plan(tmod, "pack", "pack", {})
        packs.import_pack(plan, manifest, files, ["alpha"])
        bdir = plan.apply()
        m2 = ModData(troot)
        edu = m2.load(m2.file("edu"))
        blocks = packs.type_blocks(edu)
        self.assertIn("alpha general 2", blocks)
        unit = "\n".join(edu.text(i) for i in range(*blocks["alpha general 2"]))
        self.assertIn("alpha_model_2", unit)                       # its model, renamed with it
        self.assertIn("alpha_general_2", unit)
        models = packs.type_blocks(m2.load(os.path.join(troot, "data", "descr_model_battle.txt")))
        self.assertEqual(sorted(models), ["alpha_model", "alpha_model_2", "horse_model"])   # horse shared
        self.assertTrue(os.path.exists(os.path.join(troot, "data", "ui", "units", "alpha", "#alpha_general_2.tga")))
        txt = open(m2.text_file("export_units.txt"), "rb").read().decode("utf-16")
        self.assertIn("{alpha_general_2_descr}Good", txt)
        self.assertIn('recruit "alpha general 2"', open(m2.file("edb")).read())
        # brought again later: the one brought before is known as the same unit under its new names (#298: the
        # same 67 units brought twice - every card twice in the recruitment panel)
        src_edu = ModData(self.root).load(ModData(self.root).file("edu"))
        self.assertEqual(packs._unit_print(packs._block_lines(edu, blocks["alpha general 2"])),
                         packs._unit_print(packs._block_lines(src_edu, packs.type_blocks(src_edu)["alpha general"])))
        self.assertIn(packs.brought_before(m2, ModData(self.root)).get("alpha general"),
                      ("alpha general", "alpha general 2"))
        restore(ModData(troot), bdir)
        after = {k: v for k, v in tree_hash(troot).items() if "_backups" not in k}
        self.assertEqual(after, before)                              # Restore: byte for byte
        # R-20261014-6CD955: brought chariots wore the Britons' chariots - the target has the same model lines but
        # ANOTHER texture file at the same path: the brought one comes in under a name of its own, its model too,
        # and the target's own texture stays as it was
        write(os.path.join(troot, "data", "models_unit", "textures", "h.tga.dds"), "THE TARGET'S HORSE")
        plan = Plan(ModData(troot), "pack", "pack", {})
        manifest, files = packs.read_pack(pack)
        packs.import_pack(plan, manifest, files, ["alpha"])
        plan.apply()
        tex = os.path.join(troot, "data", "models_unit", "textures")
        self.assertEqual(open(os.path.join(tex, "h.tga.dds")).read(), "THE TARGET'S HORSE")
        self.assertEqual(open(os.path.join(tex, "h_2.tga.dds")).read(), "H-texture")
        dmb = open(os.path.join(troot, "data", "descr_model_battle.txt")).read()
        self.assertIn("horse_model_2", dmb)
        self.assertIn("data/models_unit/textures/h_2.tga", dmb)
        mount = open(os.path.join(troot, "data", "descr_mount.txt")).read()
        self.assertIn("horse_model_2", mount)                        # its mount follows its model

    def test_unit_pack_chariot_wears_its_own_body(self):
        # R-20261014-6AD7ED (#250): Scotti chariots brought from Barbarian Invasion into Rome for the Gauls rode a
        # chariot with the Britons' blue stag banner. The chariot's body (descr_mount 'lod' .cas) names its texture
        # itself ('textures\\##chariot_low_poly.tga') and the game takes <name>_<faction> when there is one (Rome's
        # ##chariot_low_poly_slave), else the plain file - the target's plain one is another faction's look. The
        # source's look comes in as <name>_<owner>; the target's own files stay as they are
        from campaign_editor import packs
        from campaign_editor.plan import Plan
        d = os.path.join(self.root, "data")
        write(os.path.join(d, "export_descr_unit.txt"), EDU.replace(
            "ownership\talpha", "mount\t\tbarbarian heavy chariot\nownership\talpha"))
        write(os.path.join(d, "descr_mount.txt"),
              "type\t\tlight horse\nclass\t\thorse\n\n"
              "type\t\tbarbarian heavy chariot\nclass\t\tchariot\nhorse_type\t\tlight horse\nlods\t\t1\n"
              "lod\t\tmount_chariot_high.cas,\t50\n")
        mu = os.path.join(d, "models_unit")
        os.makedirs(mu, exist_ok=True)
        with open(os.path.join(mu, "mount_chariot_high.cas"), "wb") as fh:
            fh.write(b"CAS\x00\x10textures\\##chariot.tga\x00more")
        write(os.path.join(mu, "textures", "##chariot.tga.dds"), "GREEN TRISKEL")
        write(os.path.join(mu, "textures", "##chariot_slave.tga.dds"), "GREY KNOT")
        pack = os.path.join(self.root, "chariot.zip")
        man = packs.export_pack(ModData(self.root), ["alpha general"], pack)
        self.assertIn("light horse", man["blocks"]["mount"])             # the chariot's horses come along
        self.assertEqual(man["skins"]["models_unit/textures/##chariot"],
                         {"": "models_unit/textures/##chariot.tga.dds",
                          "slave": "models_unit/textures/##chariot_slave.tga.dds"})
        target = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, target)
        troot = os.path.join(target, "mod")
        shutil.copytree(self.root, troot)
        tex = os.path.join(troot, "data", "models_unit", "textures")
        write(os.path.join(tex, "##chariot.tga.dds"), "BLUE STAG")            # the target's: another faction's look
        before = tree_hash(troot)
        manifest, files = packs.read_pack(pack)
        plan = Plan(ModData(troot), "pack", "pack", {})
        packs.import_pack(plan, manifest, files, ["alpha"])
        bdir = plan.apply()
        self.assertEqual(open(os.path.join(tex, "##chariot_alpha.tga.dds")).read(), "GREEN TRISKEL")
        self.assertEqual(open(os.path.join(tex, "##chariot.tga.dds")).read(), "BLUE STAG")     # untouched
        self.assertFalse(os.path.exists(os.path.join(tex, "##chariot_2.tga.dds")))   # no renamed copy: the .cas
        restore(ModData(troot), bdir)                                                 # names it itself
        self.assertEqual({k: v for k, v in tree_hash(troot).items() if "_backups" not in k}, before)
        # the target's own <name>_<faction> stays (that faction's chariots look so already)
        write(os.path.join(tex, "##chariot_alpha.tga.dds"), "ALPHA'S OWN")
        plan = Plan(ModData(troot), "pack", "pack", {})
        packs.import_pack(plan, manifest, files, ["alpha"])
        plan.apply()
        self.assertEqual(open(os.path.join(tex, "##chariot_alpha.tga.dds")).read(), "ALPHA'S OWN")

    def test_unit_pack_model_skeletons_the_target_lacks(self):
        # R-20261014-EFB5F2 (#260): every Gaul unit brought from HLR into Rome (with REX) - the game stopped at once:
        # "Unable to find skeleton 'fs_hc_spearman_classic'" (descr_model_battle). HLR's skeletons live in its own
        # animation packs; the target's descr_skeleton has none of them. Each brought model's skeleton the target
        # lacks becomes the target's nearest one (fs_hc_spearman_classic -> fs_hc_spearman, fs_s1_gladius ->
        # fs_swordsman, fs_m_bearer -> fs_standard_bearer), said in the preview; a skeleton the target has stays
        from campaign_editor import packs
        from campaign_editor.plan import Plan
        d = os.path.join(self.root, "data")
        write(os.path.join(d, "export_descr_unit.txt"), EDU.replace(
            "ownership\talpha", "soldier\t\talpha_model, 20, 0, 1\nownership\talpha"))
        write(os.path.join(d, "descr_model_battle.txt"),
              "type\t\talpha_model\nskeleton\t\t\tfs_s1_gladius, fs_m_bearer\r\n"
              "skeleton_horse\t\tfs_hc_spearman_classic, fs_hc_swordsman ; riders\n"
              "texture\t\talpha, data/models_unit/textures/a.tga\nmodel_flexi\t\tdata/models_unit/a.cas, max\n")
        write(os.path.join(d, "models_unit", "a.cas"), "A-model")
        pack = os.path.join(self.root, "alpha.zip")
        packs.export_pack(ModData(self.root), ["alpha general"], pack)
        target = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, target)
        troot = os.path.join(target, "mod")
        shutil.copytree(self.root, troot)
        write(os.path.join(troot, "data", "descr_model_battle.txt"), "type\t\tother\nskeleton\t\tfs_swordsman\n")
        write(os.path.join(troot, "data", "descr_skeleton.txt"),
              "".join("type\t\t%s\nanim\t\tstand\tdata/animations/x.cas\n\n" % s for s in
                      ("fs_swordsman", "fs_slow_swordsman", "fs_hc_spearman", "fs_hc_swordsman",
                       "fs_standard_bearer")))
        manifest, files = packs.read_pack(pack)
        plan = Plan(ModData(troot), "pack", "pack", {})
        packs.import_pack(plan, manifest, files, ["alpha"])
        said = " ".join(str(w) for w in plan.warnings)
        self.assertIn("fs_hc_spearman_classic -> fs_hc_spearman", said)
        plan.apply()
        with open(os.path.join(troot, "data", "descr_model_battle.txt")) as fh:
            dmb = fh.read()
        self.assertIn("skeleton\t\t\tfs_swordsman, fs_standard_bearer", dmb)
        self.assertIn("skeleton_horse\t\tfs_hc_spearman, fs_hc_swordsman ; riders", dmb)
        self.assertNotIn("classic", dmb)
        self.assertEqual(packs.near_skeleton("fs_s1_slow_barbswordsman", {"fs_slow_swordsman", "fs_swordsman"}),
                         "fs_slow_swordsman")
        self.assertEqual(packs.near_skeleton("fs_thp_m_spearman", {"fs_spearman"}), "fs_spearman")
        self.assertEqual(packs.near_skeleton("fs_phalanx_pikeman", {"fs_semi_fast_spearman"}),
                         "fs_semi_fast_spearman")
        self.assertIsNone(packs.near_skeleton("fs_kraken", {"fs_spearman"}))
        # Check mod files names a model whose skeleton the mod lacks (a mod brought into before this fix)
        from campaign_editor.check import skeleton_problems
        self.assertEqual(skeleton_problems(ModData(troot)), [])
        with open(os.path.join(troot, "data", "descr_model_battle.txt"), "a") as fh:
            fh.write("\ntype\t\tbroken\nskeleton\t\tfs_hc_spearman_classic, fs_swordsman ; old\n")
        self.assertEqual(skeleton_problems(ModData(troot)), [("broken", ["fs_hc_spearman_classic"])])

    def test_medieval2_animation_set_takes_a_carried_skeleton(self):
        """Bring in Medieval II (BACKLOG B): the game's own data/Animations set is read (its 112 skeletons, 2401
        animations) and one carried skeleton with its animations appended reads back the same - when the game's
        files are here."""
        import tempfile as _tf
        from campaign_editor import animpacks as AP
        folder = "/home/user/m2tw-game-data/Medieval II Total War/data/Animations"
        base = AP.AnimSet.at(folder) if os.path.isdir(folder) else None
        if base is None:
            self.skipTest("no Medieval II animation set here")
        name = sorted(base.skeletons())[0]
        rec = base.record(name)
        carried = {"skeletons": {name + "_brought": rec},
                   "anims": {k: base.anim_bytes(k) for k in AP.anim_paths(rec)}}
        out, added, _ = AP.merged(base, carried)
        self.assertEqual(added, [name + "_brought"])
        with _tf.TemporaryDirectory() as d:
            for n, b in out.items():
                with open(os.path.join(d, n), "wb") as fh:
                    fh.write(b)
            back = AP.AnimSet.at(d)
            self.assertIsNotNone(back)
            self.assertEqual(len(back.skeletons()), len(base.skeletons()) + 1)
            self.assertEqual(back.record(name + "_brought"), rec)
            self.assertEqual(len(back.anims()), len(base.anims()))      # its animations: the set has them already

    def test_unit_pack_carries_its_own_skeletons_and_animations(self):
        # the user, 2026-10-14 (after #260): 'a skeleton the target lacks must come along, its animations too' - a mod
        # (HLR) has skeletons of its own in its own animation set; the target's set (its own, or the game's) is
        # written into the target mod with the source's skeleton records and every animation they name appended
        # (each scale; one the target has stays its own), the counts raised - and the model keeps its skeleton
        from unittest import mock
        from campaign_editor import animpacks as AP, packs
        from campaign_editor.plan import Plan

        make_set = _make_anim_set
        d = os.path.join(self.root, "data")
        write(os.path.join(d, "export_descr_unit.txt"), EDU.replace(
            "ownership\talpha", "soldier\t\talpha_model, 20, 0, 1\nownership\talpha"))
        write(os.path.join(d, "descr_model_battle.txt"),
              "type\t\talpha_model\nskeleton\t\tfs_own, fs_swordsman\nmodel_flexi\t\tdata/models_unit/a.cas, max\n")
        write(os.path.join(d, "models_unit", "a.cas"), "A")
        own_a, shared = "data/animations/Own_A.cas", "data/animations/shared.cas"
        make_set(os.path.join(d, "animations"), {"fs_swordsman": [shared], "fs_own": [own_a, shared]},
                 {shared: [(1.0, b"SHARED-SRC")], own_a: [(1.0, b"OWN-1.0"), (1.1, b"OWN-1.1")]})
        # View in 3D: a skeleton no descr_skeleton.txt has (HLR's) takes its animations from the set's record, each
        # named by its file - the play buttons were missing (a tester, 2026-10-17)
        from campaign_editor import animations as AN
        self.assertEqual(AN.of_skeleton(ModData(self.root), "fs_own"),
                         [("own_a", "data/animations/own_a.cas"), ("shared", "data/animations/shared.cas")])
        with mock.patch.object(AP, "game_set", lambda mod: None):
            man, files = packs.collect(ModData(self.root), ["alpha general"])
        self.assertEqual(sorted(man["animations"]["skeletons"]), ["fs_own", "fs_swordsman"])
        target = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, target)
        troot = os.path.join(target, "mod")
        shutil.copytree(self.root, troot)
        tan = os.path.join(troot, "data", "animations")
        shutil.rmtree(tan)
        make_set(tan, {"fs_swordsman": [shared]}, {shared: [(1.0, b"SHARED-TARGET")]})
        write(os.path.join(tan, "aninterp.cache"), "REX CACHE")
        write(os.path.join(troot, "data", "descr_model_battle.txt"), "type\t\tother\nskeleton\t\tfs_swordsman\n")
        before = tree_hash(troot)
        plan = Plan(ModData(troot), "pack", "pack", {})
        packs.import_pack(plan, man, files, ["alpha"])
        self.assertIn("1 skeleton(s) of the brought units added", plan.report())
        self.assertNotIn("fs_own ->", plan.report())
        bdir = plan.apply()
        got = AP.AnimSet.at(tan)
        self.assertEqual(sorted(got.skeletons()), ["fs_own", "fs_swordsman"])
        self.assertEqual(got.record("fs_own"), files[man["animations"]["skeletons"]["fs_own"]])
        self.assertEqual([b for _, b in got.anim_bytes("data/animations/own_a.cas")], [b"OWN-1.0", b"OWN-1.1"])
        self.assertEqual([b for _, b in got.anim_bytes(shared)], [b"SHARED-TARGET"])     # the target's own stays
        self.assertFalse(os.path.exists(os.path.join(tan, "aninterp.cache")))
        with open(os.path.join(troot, "data", "descr_model_battle.txt")) as fh:
            self.assertIn("fs_own, fs_swordsman", fh.read())
        from campaign_editor.check import skeleton_problems
        self.assertEqual(skeleton_problems(ModData(troot)), [])
        restore(ModData(troot), bdir)
        self.assertEqual({k: v for k, v in tree_hash(troot).items() if "_backups" not in k}, before)
        # Medieval II (the user: 'не забывай'): the same set form; its models name skeletons in the modeldb
        self.assertEqual(packs.model_skeletons({}, {"m": {"mounts": [{"primary": "MTW2_Spear", "secondary": ""},
                                                                      {"primary": "MTW2_Spear",
                                                                       "secondary": "MTW2_Sword"}]}}),
                         ["MTW2_Spear", "MTW2_Sword"])

    def test_a_brought_skeleton_never_names_an_animation_found_nowhere(self):
        """Report R-20261018-D47E51: a faction brought from SS 6.3 into Medieval II, the game stopped at its start
        ('skeleton.cpp(1035): adata != 0') - the mangonel's skeleton named a crew animation in no set: SS keeps it as a
        loose .cas file, which was left behind. The loose file comes along now; a skeleton naming one found nowhere
        is not brought (the units take the nearest skeleton) and that is said."""
        from unittest import mock
        from campaign_editor import animpacks as AP, packs
        from campaign_editor.plan import Plan
        d = os.path.join(self.root, "data")
        write(os.path.join(d, "export_descr_unit.txt"), EDU.replace(
            "ownership\talpha", "soldier\t\talpha_model, 20, 0, 1\nownership\talpha"))
        write(os.path.join(d, "descr_model_battle.txt"),
              "type\t\talpha_model\nskeleton\t\tfs_crew, fs_lost\nmodel_flexi\t\tdata/models_unit/a.cas, max\n")
        write(os.path.join(d, "models_unit", "a.cas"), "A")
        inset, loose, lost = "data/animations/in_set.cas", "data/animations/crew/loose.cas", "data/animations/gone.cas"
        _make_anim_set(os.path.join(d, "animations"), {"fs_crew": [inset, loose], "fs_lost": [inset, lost]},
                       {inset: [(1.0, b"IN-SET")]})
        write(os.path.join(d, "animations", "crew", "loose.cas"), "LOOSE")
        with mock.patch.object(AP, "game_set", lambda mod: None):
            man, files = packs.collect(ModData(self.root), ["alpha general"])
        self.assertEqual(files.get("animations/crew/loose.cas"), b"LOOSE")          # the loose file comes along
        target = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, target)
        troot = os.path.join(target, "mod")
        shutil.copytree(self.root, troot)
        tan = os.path.join(troot, "data", "animations")
        shutil.rmtree(tan)
        _make_anim_set(tan, {"fs_swordsman": [inset]}, {inset: [(1.0, b"IN-SET")]})
        write(os.path.join(troot, "data", "descr_model_battle.txt"), "type\t\tother\nskeleton\t\tfs_swordsman\n")
        plan = Plan(ModData(troot), "pack", "pack", {})
        packs.import_pack(plan, man, files, ["alpha"])
        self.assertIn("fs_lost not brought", plan.report() + " ".join(w for _, w in plan.warnings))
        from campaign_editor import gamelog                    # the crash doctor knows that line of the game's log
        self.assertIn("Not a crash", gamelog.explain("[game.script] [error] Condition eval: SettlementName needs a "
                                                     "settlement."))
        self.assertIn("names an animation the game cannot find",
                      gamelog.explain("[core.assert] [fatal] ASSERT FAILED: src\\game\\display\\skeleton.cpp(1035): "
                                      "adata != 0"))
        plan.apply()
        got = AP.AnimSet.at(tan)
        self.assertEqual(sorted(got.skeletons()), ["fs_crew", "fs_swordsman"])         # fs_lost left out
        self.assertTrue(os.path.isfile(os.path.join(tan, "crew", "loose.cas")))

    def test_unit_pack_brings_the_units_own_name_call(self):
        # the user, 2026-10-14: 'sounds too - everything of the unit the target lacks': the unit's own name call
        # (Unit_Select blocks naming it, with their wav files from the source's packs or loose files) comes along
        # for its new name - new loose files, a block of its own in the target's layout, events.dat rebuilt
        from campaign_editor import packs, sounds as SN
        from campaign_editor.plan import Plan
        d = os.path.join(self.root, "data")
        wav = b"RIFF" + struct.pack("<I", 36) + b"WAVEfmt " + struct.pack("<IHHIIHH", 16, 1, 1, 22050, 44100, 2, 16) \
            + b"data" + struct.pack("<I", 0)
        folder = "data/sounds/Voice/Human/Localized/Battle_Map"
        write(os.path.join(d, "sounds", "Voice", "Human", "Localized", "Battle_Map", "Eastern_Heavy_1_name_a_1.wav"),
              wav.decode("latin-1"))
        write(os.path.join(d, SN.VOICE_FILE),
              "BANK: unit_voice\n\tculture eastern,carthaginian\n\t\tclass Heavy_1\n"
              "\t\t\tvocal Unit_Select\n\t\t\t\tunit alpha general,other unit\n\t\t\t\tevent\n"
              "\t\t\t\t\tfolder %s\n\t\t\t\t\tEastern_Heavy_1_name_a_1.wav\n\t\t\t\t\tgroup\n\t\t\t\tend\n" % folder)
        write(os.path.join(d, "descr_sounds_units_charge.txt"),
              "BANK: charge\n\ttype alpha general,east peasant ; the war cry\n\tevent\n\t\tcry.wav\n\tend\n")
        man, files = packs.collect(ModData(self.root), ["alpha general"])
        self.assertEqual(man["sound_lists"]["alpha general"], [{"file": "descr_sounds_units_charge.txt",
                                                                "with": ["east peasant"]}])
        self.assertEqual([(e["group"], e["cls"]) for e in man["voices"]["alpha general"]],
                         [(["eastern", "carthaginian"], "Heavy_1")])
        target = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, target)
        troot = os.path.join(target, "mod")
        shutil.copytree(self.root, troot)
        write(os.path.join(troot, "data", "sounds", "events.dat"), "compiled")
        write(os.path.join(troot, "data", "descr_sounds_units_charge.txt"),
              "BANK: charge\n\ttype greek peasant\n\tevent\n\t\tg.wav\n\tend\n"
              "\ttype east hillmen,east peasant ; the war cry\n\tevent\n\t\tcry.wav\n\tend\n")
        plan = Plan(ModData(troot), "pack", "pack", {})
        packs.import_pack(plan, man, files, ["alpha"])
        plan.apply()
        with open(os.path.join(troot, "data", SN.VOICE_FILE)) as fh:
            text = fh.read()
        self.assertIn("unit alpha general 2", text)
        self.assertIn("Eastern_Heavy_1_name_alpha_general_2_1.wav", text)
        got = os.path.join(troot, "data", "sounds", "Voice", "Human", "Localized", "Battle_Map",
                           "Eastern_Heavy_1_name_alpha_general_2_1.wav")
        with open(got, "rb") as fh:
            self.assertEqual(fh.read(), wav)
        self.assertFalse(os.path.exists(os.path.join(troot, "data", "sounds", "events.dat")))
        with open(os.path.join(troot, "data", "descr_sounds_units_charge.txt")) as fh:
            charge = fh.read()
        self.assertIn("\ttype east hillmen,east peasant, alpha general 2 ; the war cry", charge)
        self.assertIn("\ttype greek peasant\n", charge)

