    def test_map_in_3d_finds_the_game_models_of_what_stands_on_the_map(self):
        """Maps > 3D's models (the user, 2026-10-15: 'towns, resources, units...'): a town takes its level's model
        of its owner's culture - Rome's descr_sm_settlements.txt ('roman { town { normal ... } }') and Medieval II's
        descr_cultures.txt ('culture x' blocks, a model line with a second word) read alike; forts / watchtowers /
        ports by culture; a resource its 'item' model at its descr_strat place."""
        from campaign_editor import mapobjects3d as O
        from campaign_editor.strat import Strat
        d = os.path.join(self.root, "data")
        write(os.path.join(d, "descr_sm_settlements.txt"),
              "symbol\tdata/models_strat/residences/symbol.CAS\n\neastern\n{\n\tvillage\n\t{\n\t\tnormal\t"
              "data/models_strat/residences/e_village.CAS\n\t}\n\ttown\n\t{\n\t\tnormal\t"
              "data/models_strat/residences/e_town.CAS\n\t\tcard\tdata/ui/x.tga\n\t}\n}\n")
        write(os.path.join(d, "descr_sm_forts_ports_watchtowers.txt"),
              "culture\t\teastern\nfort\t\tdata/models_strat/residences/e_fort.CAS\n"
              "port_land\tdata/models_strat/residences/e_port.CAS\n")
        write(os.path.join(d, "descr_sm_resources.txt"), "type\t\tgold\nitem\t\tdata/models_strat/gold.CAS\n")
        mod = ModData(d)
        got = O.culture_models(mod)
        self.assertEqual(got["eastern"]["levels"], {"village": "models_strat/residences/e_village.CAS",
                                                    "town": "models_strat/residences/e_town.CAS"})
        self.assertEqual(got["eastern"]["fort"], "models_strat/residences/e_fort.CAS")
        # a town's walls by the defences built there (the chain's 'levels' order); a port of its two models
        self.assertEqual(O._wall_level(["\ttype defenses stone_wall"], ["wooden_pallisade", "wooden_wall",
                                                                         "stone_wall"]), 3)
        self.assertEqual(O._wall_level(["\ttype core_building x"], ["a"]), 0)
        self.assertEqual(got["eastern"]["port"], "models_strat/residences/e_port.CAS")
        camp = mod.campaign_file("test", "descr_strat.txt")
        with open(camp) as fh:
            text = fh.read()
        write(camp, text.replace("\n;#####>", "\nresource\tgold, 3, 2\n;#####>", 1))
        mod = ModData(d)
        strat = Strat(mod.load(mod.campaign_file("test", "descr_strat.txt")))
        objs = O.objects(mod, "test", strat)
        town = [o for o in objs if o["kind"] == "town" and o["faction"] == "alpha"]
        self.assertEqual(town[0]["model"], "models_strat/residences/e_town.CAS")
        self.assertEqual(town[0]["xy"], tuple(mod.city_tiles("test")["A_R"]))
        self.assertIn({"kind": "resource", "model": "models_strat/gold.CAS", "texture": None, "xy": (3, 2),
                       "scale": 1.0, "faction": None}, objs)
        # an army in a town stands on its roofs, as in the game's own editor - one figure a tile
        from types import SimpleNamespace
        from unittest import mock
        from campaign_editor import stratmodels as SM
        info = SimpleNamespace(meshes=["m.cas"], textures={"": "t.tga"})
        kinds = [{"type": k, "models": ["m"]} for k in ("named character", "general", "admiral", "spy", "diplomat")]
        with mock.patch.object(SM, "figures", lambda mod, f: kinds), mock.patch.object(SM, "mesh_info",
                                                                                      lambda mod, n: info):
            figs = [o for o in O.objects(mod, "test", strat) if o["kind"] == "character"]
        towns = {tuple(xy) for xy in mod.city_tiles("test").values()}
        stand = [o["xy"] for o in figs]
        self.assertEqual(len(stand), len(set(stand)))
        self.assertTrue([o for o in figs if o["in_town"] and o["xy"] in towns])
        # Medieval II's form: everything in descr_cultures.txt, a second word after the model
        write(os.path.join(d, "descr_cultures.txt"),
              "symbol\tdata/models_strat/residences/symbol.CAS\n\nculture\t\tnorthern\nportrait_mapping\tx\n{\n"
              "village\n{\n\tnormal\t\tdata/models_strat/residences/n_village.CAS,\t\tsettlement_level_1\n}\n"
              "}\nfort\t\tdata/models_strat/residences/n_fort.CAS,\t\tfort_barbarian\n")
        got = O.culture_models(ModData(d))
        self.assertEqual(got["northern"]["levels"], {"village": "models_strat/residences/n_village.CAS"})
        self.assertEqual(got["northern"]["fort"], "models_strat/residences/n_fort.CAS")

    def test_engine_found_in_the_game_folder_and_the_limit_raised_in_the_mod(self):
        # M2EX copied over the game's root (any case), the mod in mods/<mod>/data: the engine is seen, the
        # game's descr_ex.txt is NOT read for the mod (engines read a mod's own _ex files only - "Mods that don't
        # ship this file get safe defaults"), and a raise makes the mod's own file - the game's file untouched
        from campaign_editor import limits
        game = os.path.join(self.root, "game")
        os.makedirs(os.path.join(game, "mods"))
        write(os.path.join(game, "medieval2.exe"), "x")
        write(os.path.join(game, "data", "descr_ex.txt"), "; Extended settings\nmax_factions 50\nrolloff 1\n")
        write(os.path.join(game, "data", "descr_sm_factions.txt"), SM)
        write(os.path.join(game, "data", "descr_religions.txt"), "religions\n{\n}\n")
        shutil.copytree(os.path.join(self.root, "data"), os.path.join(game, "mods", "m", "data"))
        mod = ModData(os.path.join(game, "mods", "m", "data"))
        self.assertEqual(limits.engine_of(mod), "M2EX.exe")         # its descr_ex.txt is there
        self.assertIn("taken as installed", limits.engine_report(mod))
        os.rename(os.path.join(game, "data", "descr_ex.txt"), os.path.join(game, "ex.bak"))
        self.assertIsNone(limits.engine_of(mod))
        self.assertIn("not found", limits.engine_report(mod))
        os.rename(os.path.join(game, "ex.bak"), os.path.join(game, "data", "descr_ex.txt"))
        write(os.path.join(game, "m2ex.EXE"), "x")
        self.assertEqual(limits.engine_of(mod), "M2EX.exe")
        lim = limits.faction_limit(mod)
        self.assertEqual((lim["max"], lim["own"], lim["written"]), (31, False, False))   # M2EX's default, not 50
        self.assertIn("built-in defaults", limits.engine_report(mod))
        self.assertEqual(limits.faction_limit(ModData(os.path.join(game, "data")))["max"], 50)  # the game itself
        plan = Plan(mod, "a", "b", {})
        limits.raise_limit(plan, lim, 40)
        plan.apply()
        own = os.path.join(game, "mods", "m", "data", "descr_ex.txt")
        with open(own, "rb") as fh:
            text = fh.read()
        self.assertIn(b"max_factions 40", text)
        self.assertNotIn(b"rolloff", text)                          # only the line meant: the rest stays default
        with open(os.path.join(game, "data", "descr_ex.txt"), "rb") as fh:
            self.assertIn(b"max_factions 50", fh.read())
        lim = limits.faction_limit(ModData(mod.data))
        self.assertEqual((lim["max"], lim["own"]), (40, True))
        restore(ModData(mod.data), backups(ModData(mod.data))[0])
        self.assertFalse(os.path.exists(own))

    def test_engine_files_missing_in_a_mod(self):
        """A mod of a game with M2EX / REX that lacks the engine's own files (*_ex.txt) is told so on Load, and
        with a yes gets the game's copies (backup, Restore removes them)."""
        from campaign_editor import gamefix
        game = os.path.join(self.root, "game")
        write(os.path.join(game, "medieval2.exe"), "x")
        write(os.path.join(game, "M2EX.exe"), "x")
        write(os.path.join(game, "data", "descr_ex.txt"), "max_factions 31\n")
        write(os.path.join(game, "data", "descr_caps_ex.txt"), "sprite_format xml\n")
        write(os.path.join(game, "data", "descr_religions.txt"), "x\n")
        write(os.path.join(game, "data", "descr_sm_factions.txt"), SM)
        shutil.copytree(os.path.join(self.root, "data"), os.path.join(game, "mods", "m", "data"))
        write(os.path.join(game, "mods", "m", "data", "descr_caps_ex.txt"), "sprite_format xml\n")
        mod = ModData(os.path.join(game, "mods", "m", "data"))
        found = [p for p in gamefix.problems(mod) if p["id"] == "engine_files"]
        self.assertEqual(found[0]["names"], ["descr_ex.txt"])
        # not asked on Load any more (the user, 2026-10-10: 'a + c') - Check mod files says it, with a button
        self.assertEqual([p for p in gamefix.problems(mod, on_load=True) if p["id"] == "engine_files"], [])
        from campaign_editor.check import fix_of
        self.assertEqual(fix_of(gamefix.engine_files_words(mod))[1], "engine_files")
        self.assertEqual(gamefix.missing_engine_files(ModData(os.path.join(game, "data"))), [])   # the game itself
        gamefix.fix_plan(mod, found).apply()
        self.assertTrue(os.path.isfile(os.path.join(mod.data, "descr_ex.txt")))
        self.assertEqual(gamefix.missing_engine_files(ModData(mod.data)), [])
        restore(ModData(mod.data), backups(ModData(mod.data))[0])
        self.assertFalse(os.path.exists(os.path.join(mod.data, "descr_ex.txt")))

    def test_new_mod_folder_gets_the_engine_settings_switched_off(self):
        """New mod folder on a game with REX / M2EX puts the engine's settings files the game has into the new mod at
        once, every setting switched off (the mod runs as on the engine's defaults; nothing to ask on Load)."""
        from campaign_editor import gamefix
        from campaign_editor.newmod import create_mod
        game = os.path.join(self.root, "game")
        write(os.path.join(game, "medieval2.exe"), "x")
        write(os.path.join(game, "M2EX.exe"), "x")
        write(os.path.join(game, "data", "descr_ex.txt"), "max_factions 31\n")
        write(os.path.join(game, "data", "descr_religions.txt"), "x\n")
        write(os.path.join(game, "data", "descr_sm_factions.txt"), SM)
        data, stats = create_mod(os.path.join(game, "data"), "fresh")
        with open(os.path.join(data, "descr_ex.txt"), "rb") as fh:
            self.assertEqual(fh.read().replace(b"\r\n", b"\n"), b";max_factions 31\n")
        self.assertEqual(stats["engine_settings"], ["descr_ex.txt"])
        self.assertEqual(gamefix.missing_engine_files(ModData(data)), [])

    def test_engine_files_copied_with_every_setting_off(self):
        """Report #174: the game's descr_caps_ex.txt copied into a mod as it was switched M2EX to
        model_battle_source text - the mod's own battle_models.modeldb went unread and the game closed at start
        ('Could not find soldier battle model'). The copy now has every setting switched off (the mod runs on the
        engine's defaults, as before); the lighting / AI *_ex files are not copied at all."""
        from campaign_editor import gamefix, modeldb, symbols
        game = os.path.join(self.root, "game")
        write(os.path.join(game, "medieval2.exe"), "x")
        write(os.path.join(game, "M2EX.exe"), "x")
        write(os.path.join(game, "data", "descr_caps_ex.txt"),
              "; header\nsprite_format  xml\n\nmodel_battle_source  text ; the game's own\n  ;x\n")
        write(os.path.join(game, "data", "descr_strategy_lighting_ex.txt"), "exposure 1.0\n")
        write(os.path.join(game, "data", "descr_campaign_ai_db_ex.xml"), "<root/>\n")
        write(os.path.join(game, "data", "descr_religions.txt"), "x\n")
        write(os.path.join(game, "data", "descr_sm_factions.txt"), SM)
        shutil.copytree(os.path.join(self.root, "data"), os.path.join(game, "mods", "m", "data"))
        mod = ModData(os.path.join(game, "mods", "m", "data"))
        found = [p for p in gamefix.problems(mod) if p["id"] == "engine_files"]
        self.assertEqual(found[0]["names"], ["descr_caps_ex.txt"])
        gamefix.fix_plan(mod, found).apply()
        with open(os.path.join(mod.data, "descr_caps_ex.txt"), "rb") as fh:
            self.assertEqual(fh.read(), b"; header\r\n;sprite_format  xml\r\n\r\n;model_battle_source  text ; "
                                        b"the game's own\r\n  ;x\r\n")
        mod = ModData(mod.data)
        self.assertFalse(modeldb.text_source(mod))
        self.assertEqual(symbols.sprite_mode(mod), "sd")
        self.assertFalse(os.path.exists(os.path.join(mod.data, "descr_strategy_lighting_ex.txt")))

    def test_model_battle_text_without_the_mods_own_text_file(self):
        """Report #174: a mod with its own battle_models.modeldb, no descr_model_battle.txt of its own and
        model_battle_source text in its descr_caps_ex.txt closes M2EX at start - offered: modeldb."""
        from campaign_editor import gamefix, modeldb
        game = os.path.join(self.root, "game")
        write(os.path.join(game, "medieval2.exe"), "x")
        write(os.path.join(game, "M2EX.exe"), "x")
        write(os.path.join(game, "data", "descr_religions.txt"), "x\n")
        write(os.path.join(game, "data", "descr_sm_factions.txt"), SM)
        write(os.path.join(game, "data", "descr_model_battle.txt"), "type x\n")
        shutil.copytree(os.path.join(self.root, "data"), os.path.join(game, "mods", "m", "data"))
        data = os.path.join(game, "mods", "m", "data")
        write(os.path.join(data, "descr_ex.txt"), "max_factions 31\n")
        write(os.path.join(data, "descr_caps_ex.txt"), "sprite_format  xml\nmodel_battle_source  text\n")
        mod = ModData(data)
        self.assertFalse([p for p in gamefix.problems(mod) if p["id"] == "model_battle_source"])   # no modeldb
        write(os.path.join(data, "unit_models", "battle_models.modeldb"), "22 serialization::archive 3 0 0 0 0 0\n")
        mod = ModData(data)
        found = [p for p in gamefix.problems(mod) if p["id"] == "model_battle_source"]
        self.assertEqual(len(found), 1)
        gamefix.fix_plan(mod, found).apply()
        with open(os.path.join(data, "descr_caps_ex.txt"), "rb") as fh:
            self.assertEqual(fh.read(), b"sprite_format  xml\r\nmodel_battle_source  modeldb\r\n")
        mod = ModData(data)
        self.assertFalse(modeldb.text_source(mod))
        self.assertFalse([p for p in gamefix.problems(mod) if p["id"] == "model_battle_source"])
        write(os.path.join(data, "descr_caps_ex.txt"), "model_battle_source  text\n")
        write(os.path.join(data, "descr_model_battle.txt"), "type x\n")       # its own text file: left alone
        self.assertFalse([p for p in gamefix.problems(ModData(data)) if p["id"] == "model_battle_source"])

    def test_engine_settings_come_from_the_mods_own_files_only(self):
        """REX / M2EX read a mod's descr_ex.txt / descr_caps_ex.txt from the mod alone ("Mods that don't ship this
        file get safe defaults"): the game's data copy says nothing about a mod's sprites or battle models."""
        from campaign_editor import gamefix, limits, modeldb, symbols
        game = os.path.join(self.root, "game")
        write(os.path.join(game, "medieval2.exe"), "x")
        write(os.path.join(game, "M2EX.exe"), "x")
        write(os.path.join(game, "data", "descr_religions.txt"), "x\n")
        write(os.path.join(game, "data", "descr_caps_ex.txt"),
              "sprite_format  xml\nmodel_battle_source  text\nvegetation_source  text\n")
        write(os.path.join(game, "data", "descr_sm_factions.txt"), SM)
        shutil.copytree(os.path.join(self.root, "data"), os.path.join(game, "mods", "m", "data"))
        mod = ModData(os.path.join(game, "mods", "m", "data"))
        self.assertIsNone(limits.ex_file(mod, "descr_caps_ex.txt"))
        self.assertEqual(symbols.sprite_mode(mod), "sd")               # the engine's default for mods
        self.assertFalse(modeldb.text_source(mod))
        self.assertNotIn("vegetation_source", [p["id"] for p in gamefix.problems(mod)])
        self.assertIn("descr_caps_ex.txt", [n for p in gamefix.problems(mod) if p["id"] == "engine_files"
                                            for n in p["names"]])
        gd = ModData(os.path.join(game, "data"))
        self.assertEqual(symbols.sprite_mode(gd), "xml")                # the game's own campaign reads it
        self.assertTrue(modeldb.text_source(gd))
        write(os.path.join(mod.data, "descr_caps_ex.txt"), "sprite_format  xml\n")
        self.assertEqual(symbols.sprite_mode(mod), "xml")
        self.assertFalse(modeldb.text_source(mod))                      # not in the mod's file: default modeldb

    def test_an_army_with_no_unit_is_never_written(self):
        """Report R-20261013-C9ED42 (Medieval II with M2EX): after garrisons were added most factions vanished - the
        game stops reading descr_strat at an army with no unit ('Must add at least one unit to an army') and every
        faction after it is lost. Such an army is refused before anything is written; one the mod had already is
        its own and stays (freedom)."""
        from campaign_editor import textio
        from campaign_editor.strat import Strat, empty_armies
        from campaign_editor.textio import tokens
        before = tree_hash(self.root)
        mod = ModData(self.root)
        plan = build(mod, "test", "alpha", "beta", {
            "display_name": "Betan League", "short_name": "Beta", "adjective": "Betan",
            "start": {"regions": ["B_R"], "leader": {"name": "Boris Alphid", "age": 35}, "denari": 500}})
        sp = mod.campaign_file("test", "descr_strat.txt")
        f = plan.files[sp]
        s = Strat(f)
        c = next(c for fb in s.factions for c in fb.characters
                 if any(tokens(l)[:1] == ["army"] for l in s.lines[c.start:c.end]))
        units = [i for i in range(c.start, c.end) if tokens(s.lines[i])[:1] == ["unit"]]
        self.assertTrue(units)
        for i in reversed(units):
            del f.raw[i]
        self.assertIn(c.name, " ".join(empty_armies(Strat(f))))
        with self.assertRaises(textio.WriteError) as got:
            plan.apply()
        self.assertIn("at least one unit", str(got.exception))
        self.assertIn(c.name, str(got.exception))
        self.assertEqual(tree_hash(self.root), before)
        self.assertEqual(empty_armies(Strat(textio.TextFile.load(sp))), [])
        f.save()                                                     # a mod that has one already: Check says it
        from campaign_editor.check import check_mod
        self.assertIn("%s (%s): an army with no unit" % (c.name, c.owner), check_mod(ModData(self.root), "test"))

    def test_a_refused_write_changes_nothing(self):
        """A file the system refuses half way through Apply (WinError 5: read-only, or held by another program - a
        report from a Medieval II mod): the files written before it go back, the copies go, no temp file and no
        backup stay, and the error says it in plain words. A read-only file is said in Preview and written."""
        import stat
        from unittest import mock
        from campaign_editor import textio
        before = tree_hash(self.root)
        mod = ModData(self.root)
        plan = build(mod, "test", "alpha", "beta", {
            "display_name": "Betan League", "short_name": "Beta", "adjective": "Betan",
            "start": {"regions": ["B_R"], "leader": {"name": "Boris Alphid", "age": 35}, "denari": 500}})
        changed = plan.changed_files()
        self.assertGreater(len(changed), 3)
        victim = changed[2]
        real = textio.os.replace

        def refuse(src, dst):
            if os.path.normcase(dst) == os.path.normcase(victim):
                raise PermissionError(13, "Access is denied", dst)
            return real(src, dst)
        with mock.patch.object(textio.os, "replace", side_effect=refuse), \
                mock.patch.object(textio.time, "sleep"):
            with self.assertRaises(textio.WriteError) as got:
                plan.apply()
        self.assertIn("could not be written", str(got.exception))
        self.assertIn("Nothing was changed", str(got.exception))
        self.assertEqual(tree_hash(self.root), before)                   # byte for byte, no backup, no temp file
        # a read-only file: Preview says so, Apply takes the mark off and writes it
        os.chmod(victim, stat.S_IREAD)
        try:
            mod = ModData(self.root)
            plan = build(mod, "test", "alpha", "beta", {
                "display_name": "Betan League", "short_name": "Beta", "adjective": "Betan",
                "start": {"regions": ["B_R"], "leader": {"name": "Boris Alphid", "age": 35}, "denari": 500}})
            self.assertIn("marked read-only", plan.report())
            plan.apply()
            self.assertTrue(os.stat(victim).st_mode & stat.S_IWRITE)
            restore(ModData(self.root), backups(ModData(self.root))[0])
        finally:
            os.chmod(victim, stat.S_IREAD | stat.S_IWRITE)

    def test_no_rights_disk_full_and_restore_half_way_in_plain_words(self):
        """Windows' corner cases: the mod's folder takes no writes (the backup cannot be made), the disk fills half
        way, a path longer than Windows takes, a file held by the game while Restore runs - each said in plain
        words with what to do, nothing changed or lost, and Restore can be run again."""
        import errno
        from unittest import mock
        from campaign_editor import plan as plan_mod, textio
        before = tree_hash(self.root)
        opts = {"display_name": "Betan League", "short_name": "Beta", "adjective": "Betan",
                "start": {"regions": ["B_R"], "leader": {"name": "Boris Alphid", "age": 35}, "denari": 500}}
        # no rights: the backup folder cannot be made
        real_makedirs = plan_mod.os.makedirs

        def no_rights(p, *a, **k):
            if plan_mod.BACKUP_DIR in p:
                raise PermissionError(13, "Access is denied", p)
            return real_makedirs(p, *a, **k)
        with mock.patch.object(plan_mod.os, "makedirs", side_effect=no_rights):
            with self.assertRaises(textio.WriteError) as got:
                build(ModData(self.root), "test", "alpha", "beta", opts).apply()
        self.assertIn("the system refused", str(got.exception))
        self.assertIn("the backup is made before any file is written", str(got.exception))
        self.assertEqual(tree_hash(self.root), before)
        # the disk fills half way: what was written goes back
        plan = build(ModData(self.root), "test", "alpha", "beta", opts)
        victim, real = plan.changed_files()[2], textio.os.replace

        def full(src, dst):
            if os.path.normcase(dst) == os.path.normcase(victim):
                raise OSError(errno.ENOSPC, "No space left on device", dst)
            return real(src, dst)
        with mock.patch.object(textio.os, "replace", side_effect=full):
            with self.assertRaises(textio.WriteError) as got:
                plan.apply()
        self.assertIn("the disk is full", str(got.exception))
        self.assertIn("Nothing was changed", str(got.exception))
        self.assertEqual(tree_hash(self.root), before)
        self.assertIn("too long", textio.plain("x.txt", OSError(errno.ENAMETOOLONG, "File name too long")))
        self.assertIsNone(textio.plain("x.txt", OSError(errno.EIO, "I/O error")))   # not one we can explain
        # Restore meets a file held by the game: it stops, keeps the backup whole, and runs again later
        bdir = build(ModData(self.root), "test", "alpha", "beta", opts).apply()
        real_copy = plan_mod.shutil.copy2
        held = {"n": 0}

        def busy(src, dst, *a, **k):
            held["n"] += 1
            if held["n"] == 2:
                raise PermissionError(13, "The process cannot access the file", dst)
            return real_copy(src, dst, *a, **k)
        with mock.patch.object(plan_mod.shutil, "copy2", side_effect=busy):
            with self.assertRaises(textio.WriteError) as got:
                restore(ModData(self.root), bdir)
        self.assertIn("Restore stopped half way", str(got.exception))
        self.assertIn("then Restore again", str(got.exception))
        self.assertTrue(os.path.isdir(bdir))                              # still there, not marked restored
        restore(ModData(self.root), bdir)
        self.assertEqual({k: v for k, v in tree_hash(self.root).items() if not k.startswith(plan_mod.BACKUP_DIR)},
                         before)                                         # the mod's files as before, byte for byte

    def test_clone_takes_the_templates_pictures_from_the_games_data(self):
        """A mod that keeps the game's own pictures (its folder holds what it changed): the template's faction
        buttons, unit cards and banner lie in the game's data. The new faction gets copies in the MOD (a tester's
        REX mod: new factions had no buttons on the faction-select screen); the game's data stays untouched."""
        game, hlr = self._game()
        gdata = os.path.join(game, "data")
        write(os.path.join(gdata, "menu", "symbols", "FE_buttons_48", "symbol48_alpha.tga"), "button")
        write(os.path.join(gdata, "ui", "units", "alpha", "#alpha_general.tga"), "card")
        write(os.path.join(gdata, "loading_screen", "symbols", "symbol128_alpha.tga"), "logo")
        shutil.rmtree(os.path.join(hlr, "data", "ui"))                  # the mod keeps none of its own
        before = tree_hash(gdata)
        mod = ModData(os.path.join(hlr, "data"))
        plan = build(mod, "test", "alpha", "beta", {"start": {"regions": ["B_R"], "leader": {"name": "Boris"}}})
        plan.apply()
        d = os.path.join(hlr, "data")
        self.assertTrue(os.path.isfile(os.path.join(d, "menu", "symbols", "FE_buttons_48", "symbol48_beta.tga")))
        self.assertTrue(os.path.isfile(os.path.join(d, "loading_screen", "symbols", "symbol128_beta.tga")))
        self.assertTrue(os.path.isfile(os.path.join(d, "ui", "units", "beta", "#alpha_general.tga")))
        self.assertEqual(tree_hash(gdata), before)                      # nothing written into the game's data
        restore(ModData(d), backups(ModData(d))[0])
        self.assertFalse(os.path.exists(os.path.join(d, "menu")))
        # a template with _ in its name (greek_cities): its buttons were never renamed, so never copied
        from campaign_editor.clone import renamed
        self.assertEqual(renamed("symbol48_greek_cities_grey.tga", "greek_cities", "athens"),
                         "symbol48_athens_grey.tga")
        self.assertEqual(renamed("romans_julii_logo.tga", "romans_julii", "saba"), "saba_logo.tga")
        self.assertEqual(renamed("gaulsx.tga", "gauls", "new"), "gaulsx.tga")
        # the mod's own copy of a template picture wins over the game's
        write(os.path.join(d, "menu", "symbols", "FE_buttons_48", "symbol48_alpha.tga"), "mod's button")
        plan = build(ModData(d), "test", "alpha", "beta", {"start": {"regions": ["B_R"], "leader": {"name": "Boris"}}})
        src = [s_ for s_, d_ in plan.copies if d_.endswith("symbol48_beta.tga")]
        self.assertEqual(src, [os.path.join(d, "menu", "symbols", "FE_buttons_48", "symbol48_alpha.tga")])

    def test_recolour_black_coat_dull_cloak_and_faces(self):
        """A faction in black (the Holy Roman Empire) gets its black coat recoloured where the other factions' copies
        of the card wear other colours; a face stays; a cloak painted duller and darker than the faction's colour
        is taken whole, not in patches; on a symbol (other factions' symbols are other drawings) black is left."""
        try:
            from PIL import Image, ImageDraw
        except ImportError:
            self.skipTest("Pillow is not installed")
        from campaign_editor import recolour as R

        def card(coat, cloak):
            im = Image.new("RGB", (60, 60), (90, 90, 90))       # the coat and cloak a third of it
            d = ImageDraw.Draw(im)
            d.rectangle([4, 4, 18, 30], fill=coat)          # the coat in the faction's first colour
            d.rectangle([22, 4, 36, 30], fill=cloak)        # a cloak in its second colour
            d.rectangle([12, 32, 28, 38], fill=(205, 150, 120))   # a face
            return im
        hre = ((0, 0, 0), (40, 110, 30))                      # black and a green the cloak is painted duller in
        mine = card((15, 15, 15), (70, 100, 55))
        mine.paste((25, 40, 20), (22, 18, 37, 31))           # the cloak's shaded half: dark
        others = [(card((30, 60, 160), (150, 40, 40)), ((30, 60, 160), (150, 40, 40))),
                  (card((200, 170, 20), (40, 40, 150)), ((200, 170, 20), (40, 40, 150))),
                  (card((160, 20, 20), (220, 220, 220)), ((160, 20, 20), (220, 220, 220)))]
        new, share = R.recolour(mine, hre, ((200, 0, 0), (0, 0, 200)), others)
        coat, face = new.getpixel((10, 15)), new.getpixel((20, 35))
        self.assertTrue(coat[0] > 2 * coat[1] and coat[0] > 2 * coat[2] and coat[0] > 8, coat)
        self.assertEqual(face, (205, 150, 120))
        for xy in ((28, 8), (28, 25)):                        # the light and the shaded half of the cloak
            px = new.getpixel(xy)
            self.assertTrue(px[2] > px[1] and px[2] > px[0], (xy, px))
        same, _ = R.recolour(mine, hre, ((200, 0, 0), (0, 0, 200)), others, plain=False)
        self.assertEqual(same.getpixel((10, 15)), (15, 15, 15))

    def test_recolour_gives_the_faction_its_own_far_away_sprites(self):
        """A tester: the recoloured test faction's men were green up close but kept the template's colours far away
        - its model lines named the template's sprite. Recolour gives it its own .spr (copied: it holds no names)
        and pages under its name, recoloured, and points its line at them (Rome's model_sprite here; Medieval II's
        texture line's fourth value the same way)."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("Pillow")
        from campaign_editor import recolour as R
        from campaign_editor.plan import Plan
        d = os.path.join(self.root, "data")
        write(os.path.join(d, "descr_model_battle.txt"),
              "type\tspear\nskeleton\tfs_spearman\n"
              "texture\talpha, data/models_unit/textures/spear_alpha.tga\n"
              "texture\tbeta, data/models_unit/textures/spear_alpha.tga\n"
              "model_sprite\talpha, 60.0, data/sprites/alpha_spear_sprite.spr\n"
              "model_sprite\tbeta, 60.0, data/sprites/alpha_spear_sprite.spr\n\n")
        os.makedirs(os.path.join(d, "sprites"), exist_ok=True)
        with open(os.path.join(d, "sprites", "alpha_spear_sprite.spr"), "wb") as fh:
            fh.write(b"\xad\xad\xbf\xde spr")
        im = Image.new("RGBA", (16, 8), (200, 10, 10, 255))
        im.save(os.path.join(d, "sprites", "alpha_spear_sprite_000.tga"))
        os.makedirs(os.path.join(d, "models_unit", "textures"), exist_ok=True)
        im.save(os.path.join(d, "models_unit", "textures", "spear_alpha.tga"))
        cols = {"alpha": ((215, 0, 0), (255, 210, 0)), "beta": ((215, 0, 0), (255, 210, 0))}
        old = R.faction_colours
        R.faction_colours = lambda m: cols
        try:
            mod = ModData(self.root)
            items = [it for it in R.targets(mod, "test", "beta") if it.get("own_sprite")]
            self.assertEqual([os.path.basename(it["own_sprite"]["page"]) for it in items],
                             ["beta_spear_sprite_000.tga"])
            plan = Plan(mod, "recolour", "beta", {})
            R.plan_recolour(plan, items, ((215, 0, 0), (255, 210, 0)), ((0, 160, 60), (240, 240, 0)))
        finally:
            R.faction_colours = old
        sprites = os.path.join(d, "sprites")
        self.assertEqual(plan.binaries[os.path.join(sprites, "beta_spear_sprite.spr")], b"\xad\xad\xbf\xde spr")
        self.assertIn(os.path.join(sprites, "beta_spear_sprite_000.tga"), plan.binaries)
        text = "\n".join(plan.files[os.path.join(d, "descr_model_battle.txt")].texts())
        self.assertIn("model_sprite\tbeta, 60.0, data/sprites/beta_spear_sprite.spr", text)
        self.assertIn("model_sprite\talpha, 60.0, data/sprites/alpha_spear_sprite.spr", text)  # the template's stays

    def test_recolour_faction_pictures(self):
        """A unit card in the faction's red / yellow next to another faction's blue / white copy: the red and yellow
        parts take the new colours, the brown horse (near red, but the same in both copies and duller) stays;
        written as a TGA of the same depth with a backup, Restore gives the bytes back."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("Pillow")
        from campaign_editor import recolour as R
        d = os.path.join(self.root, "data")
        cols = {"alpha": ((215, 0, 0), (255, 210, 0)), "slave": ((0, 60, 180), (240, 240, 240))}

        def card(c1, c2):
            im = Image.new("RGBA", (40, 30), (0, 0, 0, 0))
            for x in range(40):
                for y in range(30):
                    im.putpixel((x, y), (c1 if x < 8 else c2 if x < 16 else (120, 80, 50)) + (255,))
            return im
        for f, (a, b) in (("alpha", ((200, 10, 10), (250, 200, 20))), ("slave", ((10, 60, 170), (235, 235, 235)))):
            os.makedirs(os.path.join(d, "ui", "units", f), exist_ok=True)
            card(a, b).save(os.path.join(d, "ui", "units", f, "#spear.tga"))
        mod = ModData(self.root)
        R.faction_colours = lambda m: cols                     # the mini mod's factions have no colour lines
        try:
            # Medieval II's siege engine of its own (the carroccio), not its normal map nor another faction's
            sd = os.path.join(d, "siege_engines", "textures")
            os.makedirs(sd)
            for n in ("great_bell_tower_alpha.texture", "great_bell_tower_alpha_normal.texture",
                      "great_bell_tower_slave.texture"):
                open(os.path.join(sd, n), "wb").close()
            engines = [os.path.basename(it["path"]) for it in R.targets(mod, "test", "alpha")
                       if it["label"].startswith("siege engine")]
            self.assertEqual(engines, ["great_bell_tower_alpha.texture"])
            items = [it for it in R.targets(mod, "test", "alpha") if it["path"].endswith("#spear.tga")]
            self.assertEqual(len(items), 1)
            self.assertEqual(len(items[0]["others"]), 1)
            path = items[0]["path"]
            with open(path, "rb") as fh:
                before = fh.read()
            plan = Plan(mod, "recolour", "recolour_alpha", {})
            R.plan_recolour(plan, items, cols["alpha"], ((20, 120, 40), (240, 240, 240)))
            plan.apply()
            im = Image.open(path).convert("RGB")
            r, g, b = im.getpixel((5, 5))
            self.assertTrue(g > r and g > b)                       # red -> green
            r, g, b = im.getpixel((12, 5))
            self.assertTrue(min(r, g, b) > 200)                    # yellow -> white-ish
            self.assertEqual(im.getpixel((30, 5)), (120, 80, 50))  # the horse stays
            restore(ModData(self.root), backups(ModData(self.root))[0])
            with open(path, "rb") as fh:
                self.assertEqual(fh.read(), before)
        finally:
            import importlib
            importlib.reload(R)

    def test_recolour_into_black_white_starts_from_the_nearest_faction(self):
        """A battle texture in red / yellow made black / white (a modder's faction: white bands on the faces, black and
        white patches on the skin): it starts from the same model's texture of the faction whose colours are nearest
        (grey / white - not blue / white), the artist's own black / white kept as they are; the face stays; written
        into the faction's file even where nothing in the start needed recolouring."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("Pillow")
        from campaign_editor import recolour as R
        from campaign_editor.plan import Plan
        d = os.path.join(self.root, "data", "unit_models")
        os.makedirs(d)

        def tex(name, c1, c2):
            im = Image.new("RGBA", (40, 30), (0, 0, 0, 255))
            for x in range(40):
                for y in range(30):
                    im.putpixel((x, y), (c1 if x < 10 else c2 if x < 20 else (200, 150, 120)) + (255,))
            p = os.path.join(d, name)
            im.save(p)
            return p
        mine = tex("knights_alpha.tga", (215, 0, 0), (255, 210, 0))
        grey = tex("knights_beta.tga", (30, 30, 30), (235, 235, 235))
        blue = tex("knights_gamma.tga", (0, 16, 94), (239, 239, 239))
        starts = [(blue, ((0, 16, 94), (239, 239, 239)), "gamma"), (grey, ((70, 70, 70), (250, 250, 255)), "beta")]
        it = {"path": mine, "rel": "unit_models/knights_alpha.tga", "group": "unit textures", "label": "knights",
              "faction": "alpha", "others": [(p, c) for p, c, _ in starts], "starts": starts, "alike": True}
        target = ((20, 20, 20), (240, 240, 240))
        im, src, others, by = R.start_of(it, ((215, 0, 0), (255, 210, 0)), target)
        self.assertEqual(by, "beta")
        self.assertEqual(len(others), 2)                            # the faction's own picture is a copy to compare
        # a green / yellow target turns well from red / yellow: the faction's own picture stays the start
        self.assertIsNone(R.start_of(it, ((215, 0, 0), (255, 210, 0)), ((20, 120, 40), (255, 210, 0)))[3])
        mod = ModData(self.root)
        plan = Plan(mod, "recolour", "recolour_alpha", {})
        R.plan_recolour(plan, [it], ((215, 0, 0), (255, 210, 0)), target)
        import io
        new = Image.open(io.BytesIO(plan.binaries[mine])).convert("RGB")
        self.assertEqual(new.getpixel((5, 5)), (30, 30, 30))        # the artist's black, as it was
        self.assertEqual(new.getpixel((15, 5)), (235, 235, 235))    # his white
        self.assertEqual(new.getpixel((30, 5)), (200, 150, 120))    # the face
        self.assertTrue(any("made from beta's texture" in n for n in plan.report().splitlines()))
        # with no other faction's texture the colours themselves are made black / white, the folds kept
        it2 = dict(it, starts=[], others=[])
        im, src, others, by = R.start_of(it2, ((215, 0, 0), (255, 210, 0)), target)
        self.assertIsNone(by)

    def test_recolour_keeps_what_all_factions_share(self):
        """A banner nearly all in the faction's red, with a bronze (orange-red) star that every faction's banner has:
        the field changes, the star stays - even though most of the picture differs between the factions."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("Pillow")
        from campaign_editor import recolour as R

        def banner(field):
            im = Image.new("RGBA", (40, 40), field + (255,))
            for x in range(30, 38):
                for y in range(30, 38):
                    im.putpixel((x, y), (190, 90, 40, 255))          # bronze: near red in hue
            return im
        mine = banner((200, 20, 20))
        others = [(banner((20, 140, 30)), ((20, 140, 30), (240, 240, 240))),
                  (banner((30, 50, 170)), ((30, 50, 170), (240, 240, 240))),
                  (banner((230, 230, 230)), ((230, 230, 230), (0, 0, 0)))]
        new, share = R.recolour(mine, ((200, 20, 20), (0, 0, 0)), ((30, 60, 180), (240, 240, 240)), others)
        r, g, b, a = new.getpixel((5, 5))
        self.assertTrue(b > r)                                        # the field: blue now
        self.assertEqual(new.getpixel((33, 33)), (190, 90, 40, 255))  # the star: as it was

    def test_medieval2_faction_logo_moves_to_its_own_page(self):
        """M2EX (sprite_format xml): FACTION_LOGO_ALPHA already carries alpha's name and slave borrows it. Replacing
        alpha's logo moves that sprite to a page of alpha's own; slave first gets FACTION_LOGO_SLAVE with the old
        picture - one definition of each name, slave's picture unchanged; Restore gives every file back."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("Pillow is not installed")
        from unittest import mock
        from campaign_editor import symbols as SY
        from campaign_editor.factionart import image_tga
        d = os.path.join(self.root, "data")
        sm = SM.replace("culture\t\teastern\n", "culture\t\teastern\nlogo_index\t\tFACTION_LOGO_ALPHA\n", 1)
        sm = sm.replace("culture\t\tbarbarian\n", "culture\t\tbarbarian\nlogo_index\t\tFACTION_LOGO_ALPHA\n", 1)
        write(os.path.join(d, "descr_sm_factions.txt"), sm)
        write(os.path.join(d, "descr_caps_ex.txt"), "sprite_format  xml\n")
        write(os.path.join(d, "ui", "strategy.sd.xml"), '<sprite_definitions version="7">\n'
              '  <page file="stratpage_02.tga" w="128" h="128">\n'
              '    <sprite name="FACTION_LOGO_ALPHA" x="0" y="0" w="68" h="76" alpha="1"/>\n'
              '    <sprite name="OTHER" x="68" y="0" w="10" h="10" alpha="1"/>\n  </page>\n</sprite_definitions>\n')
        os.makedirs(os.path.join(d, "ui", "southern_european", "interface"))
        with open(os.path.join(d, "ui", "southern_european", "interface", "stratpage_02.tga"), "wb") as fh:
            fh.write(image_tga(Image.new("RGBA", (128, 128), (0, 0, 200, 255))))
        before = tree_hash(self.root)
        with mock.patch.object(SY, "rome", lambda m: False):
            mod = ModData(self.root)
            self.assertEqual([e["rel"] for e in SY.entries(mod, "alpha")], [SY.LOGO])
            plan = Plan(mod, "t", "t", {})
            self.assertEqual(SY.own_logo(plan, "alpha", SY.LOGO, Image.new("RGBA", (40, 40), (220, 0, 0, 255))),
                             "FACTION_LOGO_ALPHA")
            plan.apply()
            mod = ModData(self.root)
            xml = open(os.path.join(d, "ui", "strategy.sd.xml")).read()
            self.assertEqual(xml.count('name="FACTION_LOGO_ALPHA"'), 1)
            self.assertEqual(xml.count('name="FACTION_LOGO_SLAVE"'), 1)
            self.assertIn('name="OTHER"', xml)
            self.assertTrue(SY.logo_of(mod, "alpha", SY.LOGO)["own"])
            self.assertEqual(SY.logo_of(mod, "slave", SY.LOGO)["name"], "FACTION_LOGO_SLAVE")
            self.assertGreater(SY.logo_image(mod, "alpha", SY.LOGO).getpixel((30, 30))[0], 180)
            self.assertEqual(SY.logo_image(mod, "slave", SY.LOGO).getpixel((30, 30))[:3], (0, 0, 200))
            self.assertEqual(SY.logo_image(mod, "alpha", SY.LOGO).size, (68, 76))
            restore(mod, backups(mod)[0])
        after = {k: v for k, v in tree_hash(self.root).items() if not k.startswith("CampaignEditor_backups")}
        self.assertEqual(after, before)

    def test_missing_logo_sprite_shown_and_made_after_the_xml_switch(self):
        """Report R-20261011-477B62 (SSHIP, M2EX): a mod with no descr_caps_ex.txt reads the binary sheets, and a new
        faction's logo_index named a sprite no sheet has - the Art tab left the card out and said nothing. Now the
        card is there (no picture, the reason said, 'Own logos for this mod...' offered); the switch writes
        'sprite_format xml' into the mod's own descr_caps_ex.txt (an old 'sd' line changed, the rest kept); then
        Replace makes the faction a sprite and page of its own. Restore gives every file back."""
        try:
            from PIL import Image
        except ImportError:
            self.skipTest("Pillow is not installed")
        from unittest import mock
        from campaign_editor import limits, symbols as SY
        from campaign_editor.factionart import image_tga
        d = os.path.join(self.root, "data")
        sm = SM.replace("culture\t\teastern\n", "culture\t\teastern\nlogo_index\t\tFACTION_LOGO_GAMMA\n", 1)
        write(os.path.join(d, "descr_sm_factions.txt"), sm)
        write(os.path.join(d, "ui", "strategy.sd.xml"), '<sprite_definitions version="7">\n'
              '  <page file="stratpage_02.tga" w="128" h="128">\n'
              '    <sprite name="OTHER" x="68" y="0" w="10" h="10" alpha="1"/>\n  </page>\n</sprite_definitions>\n')
        os.makedirs(os.path.join(d, "ui", "southern_european", "interface"))
        with open(os.path.join(d, "ui", "southern_european", "interface", "stratpage_02.tga"), "wb") as fh:
            fh.write(image_tga(Image.new("RGBA", (128, 128), (0, 0, 200, 255))))
        before = tree_hash(self.root)
        with mock.patch.object(SY, "rome", lambda m: False), \
                mock.patch.object(limits, "engine_of", lambda m: "M2EX.exe"):
            mod = ModData(self.root)
            self.assertEqual(SY.sprite_mode(mod), "sd")
            card, = SY.entries(mod, "alpha")
            self.assertEqual((card["rel"], card["path"], card["missing"], card["locked"], card["switch"]),
                             (SY.LOGO, None, True, True, True))
            self.assertIn("FACTION_LOGO_GAMMA is on no sheet", card["note"])
            self.assertIn("Own logos for this mod", card["note"])
            plan = Plan(mod, "sprites", "sprite_format", {})
            SY.use_xml(plan)
            plan.apply()
            mod = ModData(self.root)
            self.assertEqual(SY.sprite_mode(mod), "xml")
            card, = SY.entries(mod, "alpha")
            self.assertEqual((card["locked"], card["switch"], card["missing"]), (False, False, True))
            self.assertIn("Replace gives alpha a picture of its own", card["note"])
            plan = Plan(mod, "t", "t", {})
            self.assertEqual(SY.own_logo(plan, "alpha", SY.LOGO, Image.new("RGBA", (40, 40), (220, 0, 0, 255))),
                             "FACTION_LOGO_ALPHA")
            plan.apply()
            mod = ModData(self.root)
            got = SY.logo_of(mod, "alpha", SY.LOGO)
            self.assertTrue(got["own"])
            self.assertEqual(SY.logo_image(mod, "alpha", SY.LOGO).size, (68, 76))
            self.assertGreater(SY.logo_image(mod, "alpha", SY.LOGO).getpixel((30, 30))[0], 180)
            for b in backups(mod):                    # newest first: both writes undone
                restore(mod, b)
        after = {k: v for k, v in tree_hash(self.root).items() if not k.startswith("CampaignEditor_backups")}
        self.assertEqual(after, before)
        # a mod's own descr_caps_ex.txt with 'sd': that line changed, the others and the line ends kept
        with open(os.path.join(d, "descr_caps_ex.txt"), "wb") as fh:
            fh.write(b"; caps\r\ntrade_fleet_source  capability\r\nsprite_format  sd\r\n")
        with mock.patch.object(SY, "rome", lambda m: False):
            plan = Plan(ModData(self.root), "sprites", "sprite_format", {})
            SY.use_xml(plan)
            plan.apply()
        with open(os.path.join(d, "descr_caps_ex.txt"), "rb") as fh:
            self.assertEqual(fh.read(), b"; caps\r\ntrade_fleet_source  capability\r\nsprite_format  xml\r\n")
        # switched off with a ';' (Load's copy of the game's file, every setting off): switched on again
        with open(os.path.join(d, "descr_caps_ex.txt"), "wb") as fh:
            fh.write(b"; sd = legacy binary\n;trade_fleet_source  capability\n;sprite_format  xml\n")
        with mock.patch.object(SY, "rome", lambda m: False):
            plan = Plan(ModData(self.root), "sprites", "sprite_format", {})
            SY.use_xml(plan)
            plan.apply()
        with open(os.path.join(d, "descr_caps_ex.txt"), "rb") as fh:
            self.assertEqual(fh.read(), b"; sd = legacy binary\n;trade_fleet_source  capability\nsprite_format  xml\n")

    def test_release_page_text(self):
        """The release page (release.yml): the download link first (GitHub always puts Assets at the bottom), then the
        short '### In short' part of this version, then everything else of it in a closed fold - no scrolling to the
        bottom to download. A version without 'In short' still gets the link and the fold; no part = no release."""
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "release_notes", os.path.join(os.path.dirname(__file__), "..", ".github", "release_notes.py"))
        RN = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(RN)
        log = ("# Changelog\n\n## Unreleased\n\n### Added\n- later\n\n## 1.2.0 - 2026-10-20\n\n### In short\n"
               "- **Added**: own logos\n- **Fixed**: a crash\n\n### Added\n- Own logos without REX.\n\n### Fixed\n"
               "- A crash on Load.\n\n## 1.1.0 - 2026-10-01\n\n### Added\n- Old.\n")
        body = RN.notes(log, "v1.2.0", "owner/repo")
        url = "https://github.com/owner/repo/releases/download/v1.2.0/RTW-M2TW-Campaign-Editor.exe"
        self.assertTrue(body.startswith("### [⬇ Download RTW-M2TW-Campaign-Editor.exe](%s)" % url))
        short, fold = body.index("- **Added**: own logos"), body.index("<details>")
        self.assertLess(short, fold)
        self.assertIn("<summary>", body)
        self.assertNotIn("### In short", body[fold:])
        self.assertLess(fold, body.index("- Own logos without REX."))
        self.assertLess(body.index("- A crash on Load."), body.index("</details>"))
        self.assertNotIn("later", body)
        self.assertNotIn("Old.", body)
        plain = RN.notes(log, "1.1.0", "owner/repo")
        self.assertLess(plain.index("Download"), plain.index("<details>"))
        self.assertIn("- Old.", plain)
        with self.assertRaises(ValueError):
            RN.notes(log, "9.9.9", "owner/repo")

    def test_sprite_sheet_binary_read_write_and_add(self):
        """The plain games' binary sprite sheets (Rome .rsd version 5, Medieval II .sd version 6): read and written
        back byte for byte; a page added (its click mask from the picture's alpha) and a sprite on it."""
        from campaign_editor import spritesheet as SS
        sh = SS.Sheet(5, "CAMPAIGN_UI_SPRITES", [{"guide": "\\romans\\data\\ui\\roman\\interface\\guides\\p_guides.tga",
                                                  "file": "p.tga", "flag": 0, "w": 3, "h": 3, "mask": b"\x0f\x01"}],
                      [{"name": "A", "page": 0, "x0": 0, "x1": 1, "y0": 1, "y1": 2, "flag": 1, "tail": 0}])
        data = SS.write(sh)
        again = SS.read(data)
        self.assertEqual(SS.write(again), data)
        self.assertEqual(again.find("A"), {"page": "p.tga", "box": (0, 1, 2, 2)})
        with self.assertRaises(ValueError):
            SS.read(data + b"\0")
        for f in glob.glob("/home/user/rtw-game-data/Rome Total War Gold/*/ui/*.rsd") + glob.glob(
                "/home/user/rtw-game-data/Rome Total War Gold/*/data/ui/*.rsd") + glob.glob(
                "/home/user/m2tw-game-data/Medieval II Total War/data/ui/*.sd"):
            with open(f, "rb") as fh:                         # the games' own files, where this machine has them
                b = fh.read()
            self.assertEqual(SS.write(SS.read(b)), b, f)
        try:
            from PIL import Image
        except ImportError:
            return
        im = Image.new("RGBA", (10, 3), (0, 0, 0, 0))
        im.putpixel((0, 0), (1, 1, 1, 255))
        im.putpixel((9, 0), (1, 1, 1, 128))
        im.putpixel((1, 1), (1, 1, 1, 127))                      # 127: not over the line
        i = SS.set_page(again, "faction_logo_x.tga", im)
        SS.set_sprite(again, "FACTION_LOGO_X", i, 0, 0, 10, 3)
        third = SS.read(SS.write(again))
        page = third.pages[1]
        self.assertEqual((page["file"], page["w"], page["h"], len(page["mask"])), ("faction_logo_x.tga", 10, 3, 4))
        self.assertEqual(page["mask"], bytes([0b1, 0b10, 0, 0]))  # pixel 0 and pixel 9
        self.assertTrue(page["guide"].endswith("\\faction_logo_x_guides.tga"))
        self.assertEqual(third.find("FACTION_LOGO_X"), {"page": "faction_logo_x.tga", "box": (0, 0, 10, 3)})

    def test_every_sprite_sheet_as_the_game_reads_it(self):
        """Interface > Sprite sheets: every sheet of the mod's ui folder - the binary .rsd / .sd the plain game reads,
        the .sd.xml an engine on 'sprite_format xml' reads, a sheet with only one of the two that one; its pages with
        their sprites; a page found in each culture folder that has it."""
        from campaign_editor import spritesheet as SS, symbols as SY
        mod = ModData(self.root)
        ui = os.path.join(mod.data, "ui")
        os.makedirs(os.path.join(ui, "roman", "interface"), exist_ok=True)
        sh = SS.Sheet(5, "T", [{"guide": "g", "file": "p.tga", "flag": 0, "w": 4, "h": 4, "mask": b"\0\0\0"}],
                      [{"name": "BIN_A", "page": 0, "x0": 1, "x1": 2, "y0": 0, "y1": 3, "flag": 1, "tail": 0}])
        with open(os.path.join(ui, "strat3.rsd"), "wb") as fh:
            fh.write(SS.write(sh))
        xml = '<sprite_definitions version="7">\n  <page file="p.tga" w="4" h="4">\n    <sprite name="XML_A" x="0" ' \
              'y="1" w="3" h="2" alpha="1"/>\n  </page>\n</sprite_definitions>\n'
        for name in ("strat3.sd.xml", "radar.sd.xml"):
            with open(os.path.join(ui, name), "w") as fh:
                fh.write(xml)
        with open(os.path.join(ui, "roman", "interface", "p.tga"), "wb") as fh:
            fh.write(b"x")
        got = {s["name"]: s for s in SY.all_sheets(mod)}
        self.assertEqual((got["strat3"]["kind"], got["strat3"]["pages"]), ("binary", [("p.tga", [("BIN_A", (1, 0, 2, 4))])]))
        self.assertTrue(got["strat3"]["other"].endswith("strat3.sd.xml"))
        self.assertEqual((got["radar"]["kind"], got["radar"]["other"]), ("text", None))
        self.assertEqual(got["radar"]["pages"], [("p.tga", [("XML_A", (0, 1, 3, 2))])])
        with open(os.path.join(mod.data, "descr_caps_ex.txt"), "w") as fh:
            fh.write("sprite_format xml\n")
        got = {s["name"]: s for s in SY.all_sheets(mod)}
        self.assertEqual((got["strat3"]["kind"], got["strat3"]["pages"][0][1]), ("text", [("XML_A", (0, 1, 3, 2))]))
        self.assertEqual([c for c, _ in SY.page_cultures(mod, "p.tga")], ["roman"])
        with open(os.path.join(ui, "strat3.rsd"), "wb") as fh:
            fh.write(b"bad")
        os.remove(os.path.join(mod.data, "descr_caps_ex.txt"))
        self.assertIn("cannot be read", {s["name"]: s for s in SY.all_sheets(mod)}["strat3"]["error"])

    def test_sprite_sheets_tab_shows_finds_and_saves(self):
        """Interface > Sprite sheets (the window): the sheet, its page and culture on show, the sprites listed; Find
        looks through every sheet and a pick jumps to its page; a sprite saved as a PNG is its box of the page."""
        try:
            from PIL import Image
            import tkinter as tk
            root = tk.Tk()
        except Exception as e:                        # no Pillow / tkinter / display
            self.skipTest("no window: %s" % e)
        from types import SimpleNamespace
        from unittest import mock
        from campaign_editor import gui_sprites
        mod = ModData(self.root)
        ui = os.path.join(mod.data, "ui")
        os.makedirs(os.path.join(ui, "roman", "interface"), exist_ok=True)
        for sheet, page, sprite in (("shared2", "a.tga", "ONE"), ("strat3", "b.tga", "TWO")):
            with open(os.path.join(ui, sheet + ".sd.xml"), "w") as fh:
                fh.write('<sprite_definitions version="7">\n  <page file="%s" w="8" h="8">\n    <sprite name="%s" '
                         'x="2" y="1" w="3" h="4" alpha="1"/>\n  </page>\n</sprite_definitions>\n' % (page, sprite))
            im = Image.new("RGBA", (8, 8), (0, 0, 0, 0))
            im.putpixel((2, 1), (255, 0, 0, 255))
            im.save(os.path.join(ui, "roman", "interface", page))
        try:
            root.withdraw()
            panel = gui_sprites.SpriteSheetsPanel(root, SimpleNamespace(mod=mod))
            panel.pack()
            panel.load()
            root.update()
            self.assertEqual((panel.sheet["name"], panel.page, panel.culture), ("shared2", "a.tga", "roman"))
            self.assertEqual([panel.tv.item(i, "text") for i in panel.tv.get_children()], ["ONE"])
            panel.v_find.set("tw")
            rows = panel.tv.get_children()
            self.assertEqual([panel.tv.item(i, "text") for i in rows], ["TWO"])
            panel.tv.selection_set(rows[0])
            panel._tree_picked()
            self.assertEqual((panel.sheet["name"], panel.page, panel.picked), ("strat3", "b.tga", "TWO"))
            out = os.path.join(self.root, "two.png")
            with mock.patch.object(gui_sprites.filedialog, "asksaveasfilename", return_value=out):
                panel.save_png(True)
            got = Image.open(out)
            self.assertEqual(got.size, (3, 4))
            self.assertEqual(got.getpixel((0, 0)), (255, 0, 0, 255))
            panel.draw()
        finally:
            root.destroy()

