    def test_a_window_on_the_old_mod_never_writes_into_the_clean_one(self):
        """A tester: Bring units into the game -> 'Make my own mod folder' -> made and loaded -> Write again in the
        bring window still open: it went into the game itself, not the new folder. A plan on a root the modder chose
        to keep clean is refused now while another mod is loaded."""
        try:
            from campaign_editor.gui import App
        except ImportError as e:
            self.skipTest("no tkinter: %s" % e)
        from types import SimpleNamespace
        from campaign_editor.textio import NotWritten
        game = os.path.join(self.root, "game", "data")
        mine = os.path.join(self.root, "game", "mine", "data")
        old, new = SimpleNamespace(data=game), SimpleNamespace(data=mine)
        fake = SimpleNamespace(mod=new, _own_folder_asked=set(),
                               _own_folder_wanted={os.path.normcase(os.path.dirname(os.path.abspath(game)))})
        with self.assertRaises(NotWritten):
            App._own_folder_first(fake, SimpleNamespace(mod=old))
        fake._own_folder_wanted = set()                    # never asked: another mod's plan goes on as before
        App._own_folder_first(fake, SimpleNamespace(mod=old))

    def test_a_brought_unit_takes_its_own_factions_look(self):
        """Reports R-20261013-018380 / 4547BC: Barbarian Invasion's saxon hunters brought into Rome came out in the
        rebels' blue - the model has 'texture slave' and 'texture saxons', no mercenaries' line, and the FIRST line
        (slave) was copied. Now the unit's own faction's look is copied (its ownership, the rebels and mercenaries
        last), or the one the modder picks."""
        from campaign_editor import packs
        from campaign_editor import modeldb as MDB
        man = {"units": [{"type": "saxon hunters", "lines": ["type saxon hunters", "ownership slave, saxons, franks"]}]}
        self.assertEqual(packs.look_order(man)[:2], ["saxons", "franks"])
        man["look"] = "franks"
        self.assertEqual(packs.look_order(man)[0], "franks")
        # each model and card: the owners of the units that wear it, not the first brought unit's (a tester: HLR's
        # Gallic units came out in spain's blue - every officer took the first unit's first owner)
        man = {"units": [
            {"type": "a", "dictionary": "a", "lines": ["type a", "soldier a_man, 40, 0, 1", "officer o1",
                                                         "ownership spain, gauls"]},
            {"type": "b", "dictionary": "b", "lines": ["type b", "soldier b_man, 40, 0, 1", "officer o2",
                                                         "ownership britons, gauls"]}]}
        self.assertEqual(packs._model_look(man, "o2")[0], "britons")
        self.assertEqual(packs._model_look(man, "O1")[0], "spain")
        self.assertEqual(packs._model_look(man, "nobody")[0], "spain")       # worn by none here: every unit's
        man["look"] = "gauls"                                                # the faction picked in step 2
        self.assertEqual(packs._model_look(man, "o2")[0], "gauls")
        lines = ["type saxon_hunters", "texture slave, hunters_slave.tga", "texture saxons, hunters_saxons.tga"]
        got, added = packs._owner_textures(lines, ["romans_julii"], ["saxons", "franks"])
        self.assertIn("texture romans_julii, hunters_saxons.tga", got)
        got, _ = packs._owner_textures(lines, ["romans_julii"])               # no order: as before (first line)
        self.assertIn("texture romans_julii, hunters_slave.tga", got)
        m = MDB.Model()                                                    # Medieval II's modeldb the same
        m.textures, m.attach = [["slave", "a"], ["saxons", "b"]], []
        MDB.give_owners(m, ["romans_julii"], ["saxons"])
        self.assertIn(["romans_julii", "b"], m.textures)

    def test_land_no_region_holds_can_be_painted(self):
        """Discord (two modders, 2026-10-13): an island of land whose map_regions colour is no region's could not be
        given to any region - 'tile is sea - only land changes region'. Land the game makes land (map_heights not pure
        blue - the game's own rule) may take a region whatever its colour; real sea still refuses."""
        from campaign_editor.regionedit import region_problems
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        red, blue, black, sea, odd = (255, 0, 0), (0, 0, 255), (0, 0, 0), (41, 140, 233), (120, 90, 40)
        write_tga(os.path.join(camp, "map_regions.tga"), 5, 4, [[red, red, blue, blue, sea],
                                                                 [red, black, blue, blue, sea],
                                                                 [red, red, blue, black, odd],
                                                                 [red, red, blue, blue, sea]])
        write_tga(os.path.join(camp, "map_heights.tga"), 11, 9,                  # tile (4, 2) land, the rest sea
                  [[(60, 60, 60) if x < 9 or (x, y) == (9, 5) else (0, 0, 250) for x in range(11)]
                   for y in range(9)])
        mod = ModData(self.root)
        region = next(r for r, v in mod.regions("test").items() if v["colour"] == blue)
        self.assertTrue(mod.unclaimed_land("test", (4, 2)))
        self.assertFalse(mod.unclaimed_land("test", (4, 1)))
        errors, _ = region_problems(mod, "test", {(4, 2): region}, [])
        self.assertEqual(errors, [])
        errors, _ = region_problems(mod, "test", {(4, 1): region}, [])
        self.assertTrue(any("sea" in e for e in errors))

    def test_slaves_on_land_the_terrain_brush_makes(self):
        """Report R-20261012-C56BB7: the Terrain brush made land out of sea for a wasteland, its slaves resource went
        on that land and the write stopped: 'new slaves at 159, 217: that is sea' - checked against the old map.
        A resource put on land the same write makes is told so; any other still needs land."""
        from campaign_editor import resources as R
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        red, blue, black, sea_c = (255, 0, 0), (0, 0, 255), (0, 0, 0), (41, 140, 233)
        write_tga(os.path.join(camp, "map_regions.tga"), 5, 4, [[red, red, blue, blue, sea_c],
                                                                 [red, black, blue, blue, sea_c],
                                                                 [red, red, blue, black, sea_c],
                                                                 [red, red, blue, blue, sea_c]])
        write_tga(os.path.join(camp, "map_heights.tga"), 11, 9,
                  [[(0, 0, 250) if x >= 9 else (20, 20, 20) for x in range(11)] for y in range(9)])
        mod = ModData(self.root)
        sea = (4, 1)
        self.assertTrue(mod.is_sea("test", sea))
        with self.assertRaises(ValueError):
            R.apply(Plan(mod, "map", "map", {}), "test", {"added": [{"type": "slaves", "xy": sea}]})
        plan = Plan(mod, "map", "map", {})
        R.apply(plan, "test", {"added": [{"type": "slaves", "xy": sea, "land": True}]})
        self.assertTrue(any(r.kind == "slaves" and tuple(r.xy) == sea
                            for r in R.read(plan.files[mod.campaign_file("test", "descr_strat.txt")])))

    def test_a_window_keeps_its_changes_by_itself(self):
        """gui_util.AutoKeep (the user, 2026-10-16: no Keep for Apply): a change is kept a moment later, a refused one
        is kept with its problem (said in the window's line; Apply changes names it), nothing changed takes it out;
        Undo / Redo step the window's own changes; thrown away in Apply's list, the window shows the files again."""
        try:
            import tkinter as tk
            from tkinter import ttk
            root = tk.Tk()
        except Exception as e:
            self.skipTest("no window: %s" % e)
        from campaign_editor.gui_util import AutoKeep
        parts, shown = {}, []

        class Plan1:
            def __init__(self, n):
                self.n = n

            def changed_files(self):
                return ["f"] if self.n else []

        class Win(AutoKeep, tk.Toplevel):
            def __init__(self, app):
                super().__init__(app)
                self.app, self.v = app, tk.StringVar(self, "0")
                self._ak_line = ttk.Label(self)
                self.v.trace_add("write", self.ak_changed)
                self.ak_start()

            def _ak_key(self):
                return "w"

            def _ak_label(self):
                return "W"

            def _ak_plan(self):
                if self.v.get() == "bad":
                    raise ValueError("the game would stop")
                return Plan1(int(self.v.get()))

            def _ak_state(self):
                return self.v.get()

            def _ak_set(self, st):
                self.v.set(st)

            def ak_reload(self):
                shown.append("files")
        root.session_add = lambda key, label, plan, after=None, **kw: parts.__setitem__(key, kw)
        root.session_drop = lambda key: parts.pop(key, None)
        try:
            w = Win(root)
            w.v.set("2")
            w.ak_keep()
            self.assertEqual(parts["w"].get("problem"), None)
            w.v.set("bad")
            w.ak_keep()
            self.assertEqual(parts["w"]["problem"], "the game would stop")
            self.assertIn("the game would stop", w._ak_line.cget("text"))
            w._undo()
            self.assertEqual(w.v.get(), "2")
            w._undo()
            w.ak_keep()
            self.assertNotIn("w", parts)                               # back as it was: nothing waits
            w._redo()
            self.assertEqual(w.v.get(), "2")
            w.ak_close()
            self.assertIn("w", parts)                                  # closing keeps what still waited
            self.assertIs(root._ak_windows["w"], w)
            w.ak_dropped()
            self.assertEqual(shown, ["files"])
        finally:
            root.destroy()

    def test_script_rules_and_traits_windows_keep_by_themselves(self):
        """The user, 2026-10-16: no Keep for Apply anywhere - the Campaign script, Campaign rules and Traits windows
        keep a change by themselves, step it back with Undo, keep what waits on closing, and show it again when
        opened again while it still waits."""
        try:
            import tkinter as tk
            root = tk.Tk()
        except Exception as e:
            self.skipTest("no window: %s" % e)
        from campaign_editor import gui_campaignscript as GS, gui_events as GE, gui_mercenaries as GM
        from campaign_editor import gui_rebels as GRB, gui_rules as GR, gui_traits as GT
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        write(os.path.join(camp, "campaign_script.txt"), "script\n\tif I_LocalFaction alpha\n\t\tset_counter a 1\n"
              "\tend_if\n\tset_counter b 2\nend_script\n")
        parts = {}
        root.mod = ModData(self.root)
        root.v_campaign = tk.StringVar(root, "test")
        root.status = tk.StringVar(root)
        root.session_add = lambda key, label, plan, after=None, **kw: parts.__setitem__(key, (plan, kw))
        root.session_drop = lambda key: parts.pop(key, None)
        root.session_kept = lambda key: key in parts
        root.show_text = lambda *a: None
        root._m2 = lambda: False
        root.town_owners = lambda: {}
        try:
            for cls in (GS.CampaignScriptWindow, GR.RulesWindow, GT.TraitsWindow, GE.EventsWindow, GM.MercWindow,
                        GRB.RebelsWindow):
                buttons, todo = [], []
                w = cls(root, "test") if cls is GS.CampaignScriptWindow else cls(root)
                todo = [w]
                while todo:
                    c = todo.pop(0)
                    buttons += [c.cget("text")] if c.winfo_class() == "TButton" else []
                    todo += c.winfo_children()
                self.assertNotIn("Keep for Apply", buttons, cls.__name__)
                w.close()
            w = GS.CampaignScriptWindow(root, "test")
            first = w.pieces[0]["id"]
            w.remove([first])
            w.ak_keep()
            key = "campaign_script:test"
            self.assertIn(key, parts)
            self.assertEqual(len(parts[key][0].changed_files()), 1)
            w._undo()
            self.assertEqual(w.removed, [])
            w.ak_keep()
            self.assertNotIn(key, parts)
            w._redo()
            w.close()                                                  # closing keeps it
            self.assertIn(key, parts)
            w = GS.CampaignScriptWindow(root, "test")                  # opened again: shown as kept
            self.assertEqual(w.removed, [first])
            w.close()
        finally:
            root.destroy()

    def test_town_window_shows_its_kept_garrison_again(self):
        """Report R-20261012-C56BB7: a garrison kept for Apply in the Town window - opened again, the window showed
        the old one. Since 2026-10-16 the window keeps every change by itself (no Keep button), its Undo / Redo step
        its own changes, closing keeps them; the picks come back while the part is kept, forgotten once written."""
        try:
            import tkinter as tk
            root = tk.Tk()
        except Exception as e:
            self.skipTest("no window: %s" % e)
        try:
            from campaign_editor import gui_town
        except ImportError as e:                         # Pillow (CI's test job has none)
            root.destroy()
            self.skipTest("no Pillow: %s" % e)
        mod = ModData(self.root)
        parts = {}
        root.mod, root.pictures, root.status = mod, None, tk.StringVar(root)
        root.v_campaign = tk.StringVar(root, "test")
        root.kept_view = lambda but=None: mod
        root.session_kept = lambda key: key in parts
        root.session_add = lambda key, label, plan, after=None, **kw: parts.__setitem__(key, (plan, kw))
        root.session_drop = lambda key: parts.pop(key, None)
        root.map_only = lambda: True
        region = next(iter(mod.city_tiles("test")))
        key = "town:%s" % region
        try:
            w = gui_town.TownWindow(root, region)
            buttons, todo = [], [w]
            while todo:
                c = todo.pop(0)
                buttons += [c.cget("text")] if c.winfo_class() == "TButton" else []
                todo += c.winfo_children()
            self.assertNotIn("Keep for Apply", buttons)                # kept by itself (the user, 2026-10-16)
            w.garrison = ["alpha general"]
            w.ak_changed()
            w.ak_keep()                                                # what the moment after the change does
            self.assertIn(key, parts)
            self.assertTrue(parts[key][1].get("quiet"))
            w.v_pop.set("123")                                         # one more change, then Undo steps it back
            w._undo()
            self.assertEqual(w.v_pop.get(), str(w.town.get("population") or ""))
            self.assertEqual(w.garrison, ["alpha general"])
            w._undo()
            self.assertIsNone(w.garrison)
            w.ak_keep()                                                # nothing changed any more: out of the list
            self.assertNotIn(key, parts)
            w._redo()
            self.assertEqual(w.garrison, ["alpha general"])
            w.ak_keep()
            w.load(region)                                             # opened again: its kept picks come back
            self.assertEqual(w.garrison, ["alpha general"])
            w.close()                                                  # closing keeps it, asks nothing
            self.assertIn(key, parts)
            parts.clear()                                              # written (or dropped): the files say it now
            w = gui_town.TownWindow(root, region)
            self.assertIsNone(w.garrison)
        finally:
            root.destroy()

