    def test_map_deletes_a_character_of_any_faction(self):
        """The Map's right-click Delete: a character of any faction goes with his whole block (army too); the leader,
        the heir and one on the family tree are refused."""
        from campaign_editor.edit import map_changes
        mod = ModData(self.root)
        strat = mod.campaign_file("test", "descr_strat.txt")
        s = Strat(mod.load(strat))
        fb = next(fb for fb in s.factions if any(c.xy and not c.role and c.kind != "named character"
                                                 for c in fb.characters))
        c = next(c for c in fb.characters if c.xy and not c.role and c.kind != "named character")
        plan = Plan(mod, "map", "map", {})
        map_changes(plan, "test", {"remove": {fb.name: [{"name": c.name, "from": list(c.xy)}]}})
        after = Strat(plan.files[strat])
        self.assertFalse(any(x.name == c.name and x.xy == c.xy for x in after.faction(fb.name).characters))
        self.assertEqual(len(plan.files[strat].raw), len(mod.load(strat).raw) - (c.end - c.start))
        lead = next((x for f in s.factions for x in f.characters if x.role == "leader" and x.xy), None)
        if lead:
            with self.assertRaises(ValueError):
                map_changes(Plan(mod, "map", "map", {}), "test",
                            {"remove": {lead.owner: [{"name": lead.name, "from": list(lead.xy)}]}})

    def test_a_family_member_taken_off_the_map_stays_on_the_tree(self):
        """Report R-20261012-EEEE61: Flavius Julius's army could not go - Units & armies said 'a member of the family,
        remove him on the family tree', the family tree said 'he is on the map, remove him in Units & armies'. Now he
        leaves the map and stays on the tree as a man who died before the start (character_record ..., dead), so
        the relative lines still name someone; the leader and the heir stay refused (make another one first)."""
        from campaign_editor.edit import map_changes, _army_edits
        mod = ModData(self.root)
        strat = mod.campaign_file("test", "descr_strat.txt")
        f = mod.load(strat)
        i = next(n for n, t in enumerate(f.texts()) if t.startswith(";#####<"))
        f.raw[i:i] = [f.make(x) for x in (
            "character\tAbel Alphid, named character, age 20, , x 2, y 1",
            "army",
            "unit\t\talpha general\t\texp 1 armour 0 weapon_lvl 0",
            "unit\t\talpha general\t\texp 0 armour 0 weapon_lvl 0",
            "character_record\t\tAda, \tfemale, command 0, influence 0, management 0, subterfuge 0, age 38, alive, "
            "never_a_leader",
            "relative \tAaron Alphid, \tAda,\t\tAbel Alphid,\tend")]
        f.save()
        for how in ("map", "units"):
            mod = ModData(self.root)
            plan = Plan(mod, "map", "map", {})
            if how == "map":
                map_changes(plan, "test", {"remove": {"alpha": [{"name": "Abel Alphid", "from": [2, 1]}]}})
            else:
                _army_edits(plan, plan.edit(strat), "alpha", units=[],
                            remove=[{"name": "Abel Alphid", "from": [2, 1]}])
            after = Strat(plan.files[strat])
            fb = after.faction("alpha")
            self.assertFalse(any(c.name == "Abel Alphid" for c in fb.characters))
            texts = [t.strip() for t in after.lines[fb.start:fb.end] if t.strip()]
            rec = [t for t in texts if t.startswith("character_record") and "Abel Alphid" in t]
            self.assertEqual(len(rec), 1)
            self.assertIn("age 20, dead", rec[0])
            self.assertLess(texts.index(rec[0]), next(n for n, t in enumerate(texts) if t.startswith("relative")))
            self.assertTrue(any(t.startswith("relative") and "Abel Alphid" in t for t in texts))
            from campaign_editor.strat import characters_after_tree
            self.assertEqual(characters_after_tree(after), [])
        with self.assertRaises(ValueError):                         # the leader: make another the leader first
            map_changes(Plan(ModData(self.root), "map", "map", {}), "test",
                        {"remove": {"alpha": [{"name": "Aaron Alphid", "from": [1, 1]}]}})

    def test_map_editor_moves_and_arms_any_faction(self):
        """The Map editor (no faction picked): any faction's character dragged elsewhere and any army's units
        changed, written together - units found where the army stands, then the move; a named general keeps his
        bodyguard; Restore puts every byte back."""
        from campaign_editor.edit import map_changes
        from campaign_editor.textio import tokens
        mod = ModData(self.root)
        before = tree_hash(self.root)
        strat = mod.campaign_file("test", "descr_strat.txt")
        taken = set(mod.city_tiles("test").values()) | {(1, 1), (2, 2)}
        to = mod.free_tile("test", "A_R", taken)
        self.assertIsNotNone(to)
        plan = Plan(mod, "map", "map", {})
        map_changes(plan, "test", {
            "army_units": {"slave": [{"name": "Grog", "from": (2, 2), "units": ["rebel spear", "rebel spear"]}],
                           "alpha": [{"name": "Aaron Alphid", "from": (1, 1), "units": ["alpha general"]}]},
            "moves": {"slave": [{"name": "Grog", "from": (2, 2), "to": to}]}})
        s = Strat(plan.files[strat])
        grog = next(c for c in s.faction("slave").characters if c.name == "Grog")
        self.assertEqual(tuple(grog.xy), tuple(to))
        self.assertEqual([tokens(l)[1:3] for l in s.lines[grog.start:grog.end] if tokens(l)[:1] == ["unit"]],
                         [["rebel", "spear"]] * 2)
        aaron = next(c for c in s.faction("alpha").characters if c.name == "Aaron Alphid")
        units = [l for l in s.lines[aaron.start:aaron.end] if tokens(l)[:1] == ["unit"]]
        self.assertEqual(len(units), 2)                              # his bodyguard + the one given
        # an army's last unit taken: the army goes with it, as in the game (never an empty army); a named general
        # keeps his bodyguard - his army stays
        bare = Plan(mod, "map", "map", {})
        map_changes(bare, "test", {"army_units": {"slave": [{"name": "Grog", "from": (2, 2), "units": []}],
                                                  "alpha": [{"name": "Aaron Alphid", "from": (1, 1), "units": []}]}})
        s = Strat(bare.files[strat])
        self.assertFalse([c for c in s.faction("slave").characters if c.name == "Grog"])
        aaron = next(c for c in s.faction("alpha").characters if c.name == "Aaron Alphid")
        self.assertEqual(len([l for l in s.lines[aaron.start:aaron.end] if tokens(l)[:1] == ["unit"]]), 1)
        self.assertIn("left the map with its last unit", bare.report())
        self.assertFalse(bare.crash_problems())
        from campaign_editor import textio
        two = Plan(mod, "map", "map", {})                           # two armies on one tile: said in Preview,
        map_changes(two, "test", {"moves": {"slave": [{"name": "Grog", "from": (2, 2), "to": (1, 1)}]}})
        self.assertIn("Grog", two.report().split("WARNINGS")[0])     # refused at Apply (judged on the end state)
        self.assertIn("two armies on one tile", two.report())
        with self.assertRaises(textio.WriteError):
            two.apply()
        self.assertEqual(tree_hash(self.root), before)
        restore(ModData(self.root), plan.apply())
        self.assertEqual({k: v for k, v in tree_hash(self.root).items() if "_backups" not in k}, before)

    def test_moves_judged_where_everyone_ends(self):
        """Reports R-20261012-79696C / D50F20 (HLR): 'Antigonos cannot go to 251, 215: another army stands there'
        though that army was moved away too - each move was checked against the others' OLD places, in the order
        they came. Now only where everyone ends up counts: an army may take a tile another one leaves, of any
        faction, in any order."""
        from campaign_editor.edit import map_changes
        mod = ModData(self.root)
        strat = mod.campaign_file("test", "descr_strat.txt")
        taken = set(mod.city_tiles("test").values()) | {(1, 1), (2, 2)}
        to = mod.free_tile("test", "A_R", taken)
        plan = Plan(mod, "map", "map", {})
        map_changes(plan, "test", {"moves": {                       # the rebels first: Grog into Aaron's town,
            "slave": [{"name": "Grog", "from": (2, 2), "to": (1, 1)}],          # Aaron out of it after
            "alpha": [{"name": "Aaron Alphid", "from": (1, 1), "to": to}]}})
        s = Strat(plan.files[strat])
        self.assertEqual(next(c.xy for c in s.faction("slave").characters if c.name == "Grog"), (1, 1))
        self.assertNotIn("two armies on one tile", plan.report())
        self.assertEqual(plan.crash_problems(), [])
        # REX / M2EX place another faction's army standalone on a taken tile (their reader): said, not refused
        open(os.path.join(self.root, "REX.exe"), "wb").close()
        from campaign_editor.limits import engine_of
        rex = ModData(self.root)
        self.assertTrue(engine_of(rex))
        both = Plan(rex, "map", "map", {})
        map_changes(both, "test", {"moves": {"slave": [{"name": "Grog", "from": (2, 2), "to": (1, 1)}]}})
        self.assertEqual(both.crash_problems(), [])
        self.assertIn("places one of them standalone", both.report())

    def test_map_changes_for_any_faction(self):
        # a tester: what is put on the Map should not depend on the faction picked elsewhere - a town given to any
        # faction, an army or agent placed for any faction, written with the next Apply
        from campaign_editor.edit import first_units, map_changes
        from campaign_editor.plan import Plan
        mod = ModData(self.root)
        before = tree_hash(self.root)
        free = mod.free_tile("test", "A_R", set(mod.city_tiles("test").values()) | {(1, 1), (2, 2)})
        self.assertIsNotNone(free)
        units = first_units(mod, "test", "alpha", "army", free)
        self.assertEqual(units, ["alpha general"])                   # its nearest army's first unit
        plan = Plan(mod, "map", "map", {})
        map_changes(plan, "test", {"owners": {"B_R": "alpha"},
                                   "characters": {"alpha": [{"kind": "army", "name": "Boris", "age": 30,
                                                             "units": units, "xy": free}]}})
        self.assertIn("B_R: slave -> alpha", plan.report())
        bdir = plan.apply()
        st = Strat(ModData(self.root).load(ModData(self.root).campaign_file("test", "descr_strat.txt")))
        alpha = st.faction("alpha")
        self.assertIn("B_R", [x.region for x in alpha.settlements])
        self.assertIn("Boris", [c.name for c in alpha.characters])
        # report #201: the rebels' garrison left the town given - it gets 3-6 of its new owner's units drawn at
        # random, their upkeep together at most 750, instead of standing empty
        from campaign_editor.start import _units
        tile = ModData(self.root).city_tiles("test")["B_R"]
