    def test_no_resource_on_a_wasteland_in_medieval2(self):
        """Report #186: Medieval II (with M2EX) refuses a resource in a region without a town ('resource silk
        positioned on 289,70 which is an invalid tile') - a region made a wasteland loses the resource lines on its
        land (noted), the others stay - unless the modder answers the one question 'keep them' (then warned); Check
        mod files names one left there; Rome keeps them (its REX wants slaves in
        every region - not known for a wasteland). Restore byte for byte."""
        from campaign_editor import regiondelete as RD, resources as RS
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        write(os.path.join(self.root, "data", "descr_ex.txt"), "max_factions 31\n")
        mod = ModData(self.root)
        b_land = sorted(set(RD.region_pixels(mod, "test", "B_R")) - {mod.city_tiles("test")["B_R"]})
        a_land = sorted(set(RD.region_pixels(mod, "test", "A_R")) - {mod.city_tiles("test")["A_R"]})
        sp = os.path.join(camp, "descr_strat.txt")
        with open(sp) as fh:
            strat = fh.read()
        write(sp, strat + "\nresource\tsilk,\t%d,\t%d\nresource\tiron,\t%d,\t%d\n" % (b_land[0] + a_land[0]))
        for kind in ("rome", "medieval2"):
            if kind == "medieval2":
                write(os.path.join(self.root, "data", "descr_religions.txt"), "religions\n{\n\tcatholic\n}\n")
            before = tree_hash(self.root)
            mod = ModData(self.root)
            plan = Plan(mod, "delete", "B_R", {})
            RD.delete(plan, "test", "B_R", waste=True)
            kinds = [r.kind for r in RS.read(plan.files[sp])]
            self.assertEqual(kinds, ["iron"] if kind == "medieval2" else ["silk", "iron"], kind)
            self.assertEqual(any("resource silk at" in n for _, n in plan.notes), kind == "medieval2")
            self.assertEqual(plan.on_wasteland, ["silk at %d, %d" % b_land[0]] if kind == "medieval2" else [])
            if kind == "medieval2":                        # the modder's answer 'keep them': they stay, warned
                keep = Plan(mod, "delete", "B_R", {})
                keep.wasteland_resources_out = False
                RD.delete(keep, "test", "B_R", waste=True)
                self.assertEqual([r.kind for r in RS.read(keep.files[sp])], ["silk", "iron"])
                self.assertTrue(any("kept on a wasteland's land (silk at" in w for _, w in keep.warnings))
            bdir = plan.apply()
            mod = ModData(self.root)
            self.assertEqual(RS.on_wasteland(mod, "test", RS.read(mod.load(sp))), [])
            if kind == "medieval2":                        # one put back by hand: Check mod files names it
                have = [RS.Resource(0, 0, "silk", b_land[0])]
                self.assertEqual([w for _, w in RS.on_wasteland(mod, "test", have)], ["B_R"])
            restore_to(mod, bdir)
            self.assertEqual({k: v for k, v in tree_hash(self.root).items() if not k.startswith("CampaignEditor_")},
                             {k: v for k, v in before.items() if not k.startswith("CampaignEditor_")})
        os.remove(os.path.join(self.root, "data", "descr_religions.txt"))
        os.remove(os.path.join(self.root, "data", "descr_ex.txt"))
        write(sp, strat)

    def test_delete_as_a_wasteland_and_back(self):
        """Report #154 ('deleting a region must not merge it into others'): under REX / M2EX a town deleted with its
        region leaves the region as a WASTELAND - its descr_regions line says so, its town pixel takes the region's
        colour, its settlement, the rebels in it, its hold_regions and its regions-section block (a watchtower there:
        the game takes them only in a region with a town) go; no neighbour grows; an island can go. The way back
        writes its town on a picked tile (the long form and the short 3-line form). The other way (a neighbour) moves
        its watchtowers to the neighbour's block. Restore byte for byte."""
        from campaign_editor import regiondelete as RD
        from campaign_editor.moddata import region_entries
        camp = os.path.join(self.root, "data", "world", "maps", "campaign", "test")
        R, B, G, Y, k = (255, 0, 0), (0, 0, 255), (0, 255, 0), (255, 255, 0), (0, 0, 0)
        write_tga(os.path.join(camp, "map_regions.tga"), 10, 7, [
            [R, R, B, B, G, G, G, G, G, G],
            [R, k, B, B, G, Y, Y, Y, Y, G],
            [R, R, k, B, G, Y, Y, Y, Y, G],
            [R, R, B, B, G, Y, Y, k, Y, G],
            [R, R, B, B, G, Y, Y, Y, Y, G],
            [R, R, B, B, G, G, G, G, k, G],
            [R, R, B, B, G, G, G, G, G, G]])
        write(os.path.join(camp, "descr_regions.txt"), REGIONS +
              "C_R\n\tCtown\n\tslave\n\tRebels\n\t0 255 0\n\tnone\n\t5\n\t1\n"
              "D_R\n\tDtown\n\tslave\n\tRebels\n\t255 255 0\n\tnone\n\t5\n\t1\n")
        towns = "".join("settlement\n{\n\tlevel village\n\tregion %s\n\tpopulation 400\n}\n\n" % r
                        for r in ("C_R", "D_R"))
        write(os.path.join(camp, "descr_strat.txt"), STRAT.replace(";;\tBtown", towns + ";;\tBtown") +
              "\n; >>>> start of regions section <<<<\n\nregion C_R\nroad_level 0\nfarming_level 0\nfamine_threat 0\n"
              "watchtower \t5 5\n\nregion D_R\nroad_level 0\nfarming_level 0\nfamine_threat 0\nwatchtower \t6 1\n\n"
              "watchtower \t8 4\n")
        write(os.path.join(camp, "descr_win_conditions.txt"), "alpha\nhold_regions A_R D_R\ntake_regions 10\n")
        before = tree_hash(self.root)
        mod = ModData(self.root)
        self.assertFalse(RD.can_waste(mod))                 # the original exe: a neighbour only
        write(os.path.join(self.root, "data", "descr_ex.txt"), "max_factions 21\n")
        with_engine = tree_hash(self.root)
        mod = ModData(self.root)
        self.assertTrue(RD.can_waste(mod))
        self.assertEqual(mod.city_tiles("test")["D_R"], (7, 3))
        self.assertEqual(RD.problems(mod, "test", "D_R", waste=True), ([], []))
        plan = Plan(mod, "delete", "D_R", {})
        self.assertIsNone(RD.delete(plan, "test", "D_R", waste=True))
        plan.apply()
        mod = ModData(self.root)
        regs = mod.regions("test")
        self.assertTrue(regs["D_R"]["wasteland"])                       # the region stays, nobody's
        self.assertEqual(region_entries(mod.load(mod.campaign_file("test", "descr_regions.txt")))["D_R"]["wasteland"][1],
                         "wasteland")
        self.assertNotIn("D_R", mod.city_tiles("test"))
        img = mod.region_map("test")
        self.assertEqual(img.get(7, 3), Y)                              # its town pixel is its land now
        self.assertEqual(sum(1 for _ in img.find(Y)), 16)               # no tile of it went to a neighbour
        self.assertEqual(sum(1 for _ in img.find(G)), 25)
        s = Strat(mod.load(mod.campaign_file("test", "descr_strat.txt")))
        self.assertNotIn("D_R", s.owners())
        self.assertEqual([f.xy for f in s.forts], [(5, 5)])            # D_R's watchtowers went with its block
        with open(os.path.join(camp, "descr_strat.txt")) as fh:
            self.assertNotIn("region D_R", fh.read())
        with open(os.path.join(camp, "descr_win_conditions.txt")) as fh:
            self.assertIn("hold_regions A_R\n", fh.read())
        # the way back: its town on a tile inside its land
        self.assertIn("inside D_R's land", RD.town_problem(mod, "test", "D_R", (5, 2)))
        self.assertIn("already", RD.town_problem(mod, "test", "D_R", (6, 2), "Ctown"))
        self.assertIsNone(RD.town_problem(mod, "test", "D_R", (6, 2), "Dnew"))
        plan = Plan(mod, "town", "D_R", {})
        RD.wasteland_town(plan, "test", "D_R", (6, 2), "Dnew", "slave")
        plan.apply()
        mod = ModData(self.root)
        self.assertFalse(mod.regions("test")["D_R"]["wasteland"])
        self.assertEqual(mod.regions("test")["D_R"]["settlement"], "Dnew")
        self.assertEqual(mod.city_tiles("test")["D_R"], (6, 2))
        self.assertEqual(Strat(mod.load(mod.campaign_file("test", "descr_strat.txt"))).owners()["D_R"], "slave")
        self.assertIn("{Dnew}", "".join(TextFile.load(mod.region_labels_file("test")).texts()))
        for b in backups(mod):
            restore(mod, b)
        self.assertEqual({k: v for k, v in tree_hash(self.root).items() if not k.startswith("CampaignEditor_")},
                         with_engine)
        # the short 3-line form gets its whole block back, as its neighbour's
        write(os.path.join(camp, "descr_regions.txt"), REGIONS + "C_R\n\tCtown\n\tslave\n\tRebels\n\t0 255 0\n"
              "\tnone\n\t5\n\t1\nD_R\n\twasteland\n\t255 255 0\n")
        write_tga(os.path.join(camp, "map_regions.tga"), 10, 7, [[Y if c == k and x == 7 else c for x, c in enumerate(row)]
                                                                 for row in [
            [R, R, B, B, G, G, G, G, G, G], [R, k, B, B, G, Y, Y, Y, Y, G], [R, R, k, B, G, Y, Y, Y, Y, G],
            [R, R, B, B, G, Y, Y, k, Y, G], [R, R, B, B, G, Y, Y, Y, Y, G], [R, R, B, B, G, G, G, G, k, G],
            [R, R, B, B, G, G, G, G, G, G]]])
        write(os.path.join(camp, "descr_strat.txt"), STRAT.replace(";;\tBtown", towns.split("settlement")[0] +
                                                                    "settlement" + towns.split("settlement")[1] +
                                                                    ";;\tBtown"))
        mod = ModData(self.root)
        self.assertTrue(mod.regions("test")["D_R"]["wasteland"])
        plan = Plan(mod, "town", "D_R", {})
        RD.wasteland_town(plan, "test", "D_R", (6, 2), "Dnew", "slave")
        plan.apply()
        mod = ModData(self.root)
        e = mod.regions("test")["D_R"]
        self.assertEqual((e["settlement"], e["creator"], e["rebels"], e["colour"], e["triumph"], e["farming"]),
                         ("Dnew", "slave", "Rebels", Y, "5", "1"))
        # the other way: its land to a neighbour, its watchtowers to that neighbour's block
        write(os.path.join(camp, "descr_regions.txt"), REGIONS +
              "C_R\n\tCtown\n\tslave\n\tRebels\n\t0 255 0\n\tnone\n\t5\n\t1\n"
              "D_R\n\tDtown\n\tslave\n\tRebels\n\t255 255 0\n\tnone\n\t5\n\t1\n")
        write_tga(os.path.join(camp, "map_regions.tga"), 10, 7, [
            [R, R, B, B, G, G, G, G, G, G], [R, k, B, B, G, Y, Y, Y, Y, G], [R, R, k, B, G, Y, Y, Y, Y, G],
            [R, R, B, B, G, Y, Y, k, Y, G], [R, R, B, B, G, Y, Y, Y, Y, G], [R, R, B, B, G, G, G, G, k, G],
            [R, R, B, B, G, G, G, G, G, G]])
        write(os.path.join(camp, "descr_strat.txt"), STRAT.replace(";;\tBtown", towns + ";;\tBtown") +
              "\n; >>>> start of regions section <<<<\n\nregion C_R\nroad_level 0\nfarming_level 0\nfamine_threat 0\n"
              "watchtower \t5 5\n\nregion D_R\nroad_level 0\nfarming_level 0\nfamine_threat 0\nwatchtower \t6 1\n\n"
              "watchtower \t8 4\n")
        mod = ModData(self.root)
        plan = Plan(mod, "delete", "D_R", {})
        self.assertEqual(RD.delete(plan, "test", "D_R"), "C_R")
        plan.apply()
        mod = ModData(self.root)
        self.assertNotIn("D_R", mod.regions("test"))
        with open(os.path.join(camp, "descr_strat.txt")) as fh:
            text = fh.read()
        self.assertNotIn("region D_R", text)
        self.assertEqual(sorted(f.xy for f in Strat(mod.load(mod.campaign_file("test", "descr_strat.txt"))).forts),
                         [(5, 5), (6, 1), (8, 4)])
        self.assertLess(text.index("watchtower \t5 5"), text.index("watchtower \t6 1"))
        del before

    def test_path_guard(self):
        """Every write of a Plan and every Restore stays inside the mod's / game's folder: '../', a link that leads
        out and a crafted backup manifest are refused before anything is written."""
        import json
        from campaign_editor import guard
        from campaign_editor.plan import Plan
        outside = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, outside, True)
        mod = ModData(self.root)
        victim = os.path.join(outside, "victim.txt")
        write(victim, "keep me")
        # a binary / copy whose path climbs out of the mod
        for make in (lambda p: p.binary(os.path.join(self.root, "..", os.path.basename(outside), "victim.txt"), b"x"),
                     lambda p: p.copy(os.path.join(self.root, "data", "descr_sm_factions.txt"),
                                      os.path.join(outside, "copied.txt"))):
            plan = Plan(mod, "t", "t")
            make(plan)
            with self.assertRaises(guard.OutsideError):
                plan.apply()
        self.assertEqual(open(victim).read(), "keep me")
        self.assertFalse(os.path.exists(os.path.join(outside, "copied.txt")))
        # a link inside the mod that leads out
        if hasattr(os, "symlink"):
            link = os.path.join(self.root, "data", "out_link")
            try:
                os.symlink(outside, link)
            except OSError:
                link = None
            if link:
                plan = Plan(mod, "t", "t")
                plan.binary(os.path.join(link, "victim.txt"), b"x")
                with self.assertRaises(guard.OutsideError):
                    plan.apply()
                self.assertEqual(open(victim).read(), "keep me")
                os.remove(link)
        # a normal write passes, and its backup restores
        plan = Plan(mod, "t", "t")
        plan.binary(os.path.join(self.root, "data", "new.bin"), b"ok")
        bdir = plan.apply()
        self.assertTrue(guard.inside(os.path.join(self.root, "data", "new.bin"), self.root))
        # a crafted manifest that names a file outside is refused - the victim stays
        with open(os.path.join(bdir, "manifest.json"), "w") as fh:
            json.dump({"faction": "t", "template": "t", "modified": [], "created": [
                "../" + os.path.basename(outside) + "/victim.txt"]}, fh)
        with self.assertRaises(guard.OutsideError):
            restore(mod, bdir)
        self.assertEqual(open(victim).read(), "keep me")

    def test_addons_never_leave_a_font_open(self):
        """A tester on Medieval II with M2EX: after our add-ons ran, the game's script console and the scripts' texts
        were drawn in another font. A font (or style) scope opened by pushFont and closed by a popFont further down
        stays open when anything between them throws - the console and every later text of the frame then take it
        (the engines say so themselves: 'hand the body to pushFont as a closure and the host pops it for you'). So
        every scope our add-ons open is handed its body as a closure; no pushFont / pushStyle without one in a
        draw, no lone popFont."""
        import re
        folder = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "assets", "addons")
        for name in sorted(os.listdir(folder)):
            with open(os.path.join(folder, name), encoding="utf-8") as fh:
                text = fh.read()
            self.assertNotIn("popFont(", text, name)
            for m in re.finditer(r"\bpushFont\(([^\n]*)", text):
                self.assertIn("function(", m.group(1), "%s: %s" % (name, m.group(0)))
            # a style scope without a closure only where every way out closes it (the modal is made inside one)
            bare = [m.group(0) for m in re.finditer(r"\bpushStyle\(([^\n]*)", text) if "function(" not in m.group(1)]
            self.assertLessEqual(len(bare), 1, name)
            self.assertEqual(text.count("popStyle()"), 2 * len(bare), name)

    def test_addons_draw_game_fonts_unscaled(self):
        """The user's M2EX console (2026-10-09): 'font autoscale: game font 5 draws at the size its font manager baked
        ... turn UI.Cap.autoScaleFonts off for this subtree' - every canvas and box our add-ons draw on turns the
        font scaling off too (both engines know the switch; it is set in a try for an engine that does not)."""
        import re
        folder = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "assets", "addons")
        for name in sorted(os.listdir(folder)):
            with open(os.path.join(folder, name), encoding="utf-8") as fh:
                text = fh.read()
            made = len(re.findall(r"\bui\.(canvas|modal)\(", text))
            if made:
                self.assertGreaterEqual(text.count("autoScaleFonts"), 1, name)
                calls = len(re.findall(r"(?<!function )raze_fonts_fixed\(ui, ", text)) + \
                    len(re.findall(r"setWidgetStyle\(\w+, ui\.Cap\.autoScaleFonts, 0\)", text)) - \
                    (1 if "function raze_fonts_fixed" in text else 0)        # the helper's own body
                self.assertEqual(calls, made, name)

    def test_older_addons_are_put_right_on_load(self):
        """The user (2026-10-09): 'still the same error in the console ... let it fix it for those who have it now'.
        An add-on in the game that is not what this editor writes with the same settings is an older version: Load
        offers to put it in again (gamefix 'old_addons_...'), its settings and the test mod's mark kept; the Add-ons
        window says so. The same version is never offered."""
        from campaign_editor import addons as AD, gamefix
        from campaign_editor.scriptmods import TEST_MARK
        game = tempfile.mkdtemp()
        open(os.path.join(game, "M2EX.exe"), "wb").close()
        write(os.path.join(game, "script", "main.nut"),
              'foreach (name in ::scripting.listModules("modules")) { require(name) }\n')
        data = os.path.join(game, "data")
        make_minimod(game)
        mod = ModData(data)
        a = AD.by_key("avoid_growth")
        values = dict(AD.read_settings(a, a.template()), AG_LABEL="Stay as it is")
        now = AD.with_game(AD.render(a, a.template(), values), mod)
        dst = AD.target(mod, a)
        self.assertEqual(os.path.dirname(dst), os.path.join(game, "script", "modules"))
        old = now.replace("ui.Cap.autoScaleFonts", "ui.Cap.autoScale")         # an older version, say
        write(dst, old.replace("\n", "\r\n") + TEST_MARK + "\r\n")
        found = [p for p in gamefix.problems(mod) if p["id"].startswith("old_addons")]
        self.assertEqual(len(found), 1)
        self.assertIn("Avoid Growth", found[0]["why"])
        gamefix.fix_plan(mod, found).apply()
        with open(dst, encoding="utf-8") as fh:
            got = fh.read()
        self.assertIn("autoScaleFonts", got)
        self.assertIn('local AG_LABEL = "Stay as it is"', got)            # its settings kept
        self.assertIn(TEST_MARK, got)                                       # still the test mod's own copy
        self.assertEqual(AD.outdated(ModData(data)), [])
        self.assertEqual([p for p in gamefix.problems(ModData(data)) if p["id"].startswith("old_addons")], [])
        write(dst, now)                                                     # this version, by hand: nothing to do
        self.assertEqual(AD.outdated(ModData(data)), [])

    def test_addon_goes_where_rex_loads_it(self):
        """REX's own script/main.nut (squi) requires every .nut of the game's script/modules; a mod with a script
        plugin of its own (HLR: manifest.nut + main.nut, no module loading) would never run one put beside it - so
        the add-on goes to the game's script/modules. Its code already pasted into the mod's scripts is refused."""
        from campaign_editor import addons as AD
        game = tempfile.mkdtemp()
        open(os.path.join(game, "REX.exe"), "wb").close()
        write(os.path.join(game, "script", "main.nut"),
              'foreach (name in ::scripting.listModules("modules")) { require(name) }\n')
        data = os.path.join(game, "HLR", "data")
        write(os.path.join(data, "descr_sm_factions.txt"), "")
        write(os.path.join(game, "HLR", "script", "manifest.nut"), 'return { name = "HLR" entry = "main" }\n')
        write(os.path.join(game, "HLR", "script", "main.nut"), 'let events = require("game.events")\n')
        mod = ModData(data)
        sack = AD.by_key("sack_settlement")
        self.assertEqual(os.path.normcase(AD.target(mod, sack)),
                         os.path.normcase(os.path.join(game, "script", "modules", "sack_settlement.nut")))
        self.assertEqual(AD.marker(sack), "[SACK]")
        self.assertFalse(AD.already_in_scripts(mod, sack))
        write(os.path.join(game, "HLR", "script", "main.nut"),
              'let events = require("game.events")\nlocal PREFIX = "[SACK] "\n')
        self.assertTrue(any("main.nut" in p for p in AD.already_in_scripts(mod, sack)))
        self.assertTrue(any("run twice" in x for x in AD.check(sack, {}, mod)))
        # the add-on's OWN file outside script/modules (an older copy put there by hand; a tester: 'it is in my game,
        # the page says not put in, no button to take it out, and Put it in is refused'): in the game, moved by Put
        # it in, taken away by Take it out
        from campaign_editor.plan import Plan, restore
        write(os.path.join(game, "HLR", "script", "main.nut"), 'let events = require("game.events")\n')
        old = os.path.join(game, "HLR", "script", "sack_settlement.nut")
        with open(old, "w", encoding="utf-8") as fh:
            fh.write(sack.template())
        self.assertEqual(AD.stray_copies(mod, sack), [old])
        self.assertFalse(AD.check(sack, AD.read_settings(sack, sack.template()), mod))    # not refused
        self.assertIsNotNone(AD.installed(mod, sack))                                     # the page: in the game
        before = tree_hash(game)
        plan = Plan(AD.plan_mod(mod, sack), "addon", "sack", {})
        AD.plan_install(plan, sack, AD.read_settings(sack, sack.template()), mod)
        self.assertIn("older copy", plan.report())
        bdir = plan.apply()
        self.assertFalse(os.path.exists(old))
        self.assertTrue(os.path.isfile(AD.target(mod, sack)))
        plan = Plan(AD.plan_mod(mod, sack), "addon", "sack", {})
        AD.plan_remove(plan, sack, mod)
        bdir2 = plan.apply()
        self.assertFalse(os.path.exists(AD.target(mod, sack)))
        self.assertIsNone(AD.installed(mod, sack))
        restore(AD.plan_mod(mod, sack), bdir2)
        restore(AD.plan_mod(mod, sack), bdir)
        self.assertEqual({k: v for k, v in tree_hash(game).items() if "_backups" not in k}, before)

    def test_addons_from_anyone(self):
        import zipfile
        from unittest import mock
        from campaign_editor import addons as AD
        script = (
            "// Border Tolls - a toll at every border crossing\n"
            "// @game both\n"
            "// @pick TOLL_FACTIONS factions\n"
            "// @label TOLL_GOLD Money per crossing\n"
            "\n"
            "// switch it off without taking it out\n"
            "local TOLL_ON = true\n"
            "local TOLL_GOLD = 25 // paid by the one who crosses\n"
            "local TOLL_TEXT = \"Toll paid\"\n"
            "local TOLL_FACTIONS = [\"romans_julii\"]\n"
            "local TOLL_SKIP = { slave = true, // the rebels never pay\n}\n"
            "local TOLL_RATE = 0.5\n"
            "local helper = 3\n"
            "function toll() {}\n")
        a = AD.from_script(script, "border_tolls.nut")
        self.assertEqual((a.title, a.game), ("Border Tolls", "both"))
        self.assertTrue(a.fits("rome") and a.fits("medieval2"))
        kinds = {s.var: s.kind for s in a.settings}
        self.assertEqual(kinds, {"TOLL_ON": "bool", "TOLL_GOLD": "int", "TOLL_TEXT": "text",
                                 "TOLL_FACTIONS": "list", "TOLL_SKIP": "set"})       # 0.5 and lower case left out
        help_ = {s.var: s.help for s in a.settings}
        self.assertEqual(help_["TOLL_ON"], "switch it off without taking it out")
        self.assertEqual(help_["TOLL_GOLD"], "paid by the one who crosses")
        self.assertEqual(next(s.label for s in a.settings if s.var == "TOLL_GOLD"), "Money per crossing")
        self.assertEqual(a.picks, {"TOLL_FACTIONS": "factions"})
        self.assertEqual(AD.read_settings(a, script)["TOLL_SKIP"], ["slave"])
        lib = os.path.join(self.root, "addons")
        src = os.path.join(self.root, "share.zip")
        with mock.patch.object(AD, "library_dir", return_value=lib):
            with open(os.path.join(self.root, "border_tolls.nut"), "w") as fh:
                fh.write(script)
            got = AD.add_to_library(os.path.join(self.root, "border_tolls.nut"))
            self.assertEqual([x.key for x in got], ["border_tolls"])
            self.assertIn("border_tolls", [x.key for x in AD.library()])
            own = AD.by_key("border_tolls")
            self.assertTrue(own.own)
            # Share: the script with the picked settings and a README; a zip's folders never reach the disk
            AD.share(own, src, {"TOLL_GOLD": 40})
            with zipfile.ZipFile(src) as z:
                self.assertIn("local TOLL_GOLD = 40", z.read("border_tolls.nut").decode())
                self.assertIn("script/modules", z.read("README.txt").decode())
            evil = os.path.join(self.root, "evil.zip")
            with zipfile.ZipFile(evil, "w") as z:
                z.writestr("../../outside/evil_mod.nut", "local X = 1\n")
            AD.add_to_library(evil)
            self.assertTrue(os.path.isfile(os.path.join(lib, "evil_mod.nut")))
            self.assertFalse(os.path.exists(os.path.join(self.root, "outside")))
            with self.assertRaises(ValueError):
                AD.add_to_library(os.path.join(self.root, "notes.txt"))              # not a script
            with self.assertRaises(ValueError):                       # the built-in one is not added twice
                with open(os.path.join(self.root, "sack_settlement.nut"), "w") as fh:
                    fh.write("local A = 1\n")
                AD.add_to_library(os.path.join(self.root, "sack_settlement.nut"))
            AD.remove_from_library(own)
            self.assertNotIn("border_tolls", [x.key for x in AD.library()])

    def test_forts_moved_removed_added(self):
        from campaign_editor import forts as FT
        from campaign_editor.edit import edit
        path = os.path.join(self.root, "data", "world", "maps", "campaign", "test", "descr_strat.txt")
        with open(path, "rb") as fh:
            before = fh.read()
        # Barbarian Invasion keeps its watchtowers after the diplomacy, under the regions
        with open(path, "wb") as fh:
            fh.write(before + b"\nregion A_R\nwatchtower \t2 3\n\nwatchtower \t0 3 ; west\n")
        mod = ModData(self.root)
        now = FT.read(mod, "test")
        self.assertEqual([(f.kind, f.xy) for f in now], [("watchtower", (2, 3)), ("watchtower", (0, 3))])
        self.assertIn("fort", FT.no_example("fort"))
        # a fort / watchtower right beside a town or another one: plain Rome with REX skipped a watchtower next to a
        # fort ('positioned on an invalid tile'); BI keeps every one 2 tiles away - refused (a wonder may stand there)
        town = next(iter(mod.city_tiles("test").values()))
        apart = ModData(self.root)
        apart.city_tiles = lambda campaign: {"A_R": (9, 9)}
        apart.land_problem = lambda campaign, xy: None
        apart.is_sea = lambda campaign, xy: False
        self.assertIn("beside another fort", FT.problem(apart, "test", (1, 3), [(2, 3)], "watchtower") or "")
        self.assertIsNone(FT.problem(apart, "test", (0, 3), [(2, 3)], "watchtower"))
        self.assertIsNone(FT.problem(apart, "test", (1, 3), [(2, 3)], FT.LANDMARK))
        near = (town[0] + 1, town[1]) if town[0] + 1 < 4 else (town[0] - 1, town[1])
        self.assertIn("beside a town", FT.problem(mod, "test", near, [], "fort") or "")
        self.addCleanup(setattr, FT, "APART", FT.APART)
        FT.APART = 1                                      # the 4 x 4 test map has no room for the rule below
        # no fort line to copy: written under its region in the regions section (the form both exes read there)
        p2 = edit(ModData(self.root), "test", "alpha", {"resources": {"forts": {"added": [{"kind": "fort", "xy": [3, 3]}]}}})
        b2 = p2.apply()
        with open(path) as fh:
            self.assertIn("\nregion B_R\nroad_level 0\nfarming_level 0\nfamine_threat 0\nfort\t3 3", fh.read())
        restore(ModData(self.root), b2)
        with self.assertRaises(ValueError):                  # two on one tile
            edit(ModData(self.root), "test", "alpha", {"resources": {"forts": {"moved": {str(now[0].line): [0, 3]}}}})
        plan = edit(mod, "test", "alpha", {"resources": {"forts": {
            "moved": {str(now[0].line): [3, 3]}, "removed": [now[1].line],
            "added": [{"kind": "watchtower", "xy": [2, 3]}]}}})
        bdir = plan.apply()
        with open(path) as fh:
            new = fh.read()
        # moved onto B_R's tile and added there: both under B_R's one block, never beside a line of another region
        # (BI with REX skipped it: 'watchtower region Sarmatia(157:104) does not match up to region name(Thracia)')
        self.assertIn("region B_R\nroad_level 0\nfarming_level 0\nfamine_threat 0\nwatchtower\t2 3\n"
                      "watchtower \t3 3\n", new)
        self.assertEqual(new.count("region B_R\n"), 2)                     # the settlement's line and the one block
        self.assertNotIn("0 3 ; west", new)
        restore(ModData(self.root), bdir)
        with open(path, "rb") as fh:
            self.assertEqual(fh.read(), before + b"\nregion A_R\nwatchtower \t2 3\n\nwatchtower \t0 3 ; west\n")

