    def test_two_kept_recolours_both_written_into_one_modeldb(self):
        """Report #294: milan, spain and the moors recoloured and kept for one Apply - milan was written, then
        spain and the moors failed: 'battle_models.modeldb was changed by another part of this write'. Each kept
        part changes the modeldb for its own faction; the later ones are now laid over the file as the earlier
        ones left it (modeldb.merged), and two different changes of one row are still refused in plain words."""
        from campaign_editor import modeldb as MDB
        from campaign_editor.plan import Plan, keep, rebased
        def model(name, facs, first=False):
            m = MDB.from_dict({"name": name, "scale": "1", "lods": [["unit_models/x/%s.mesh" % name, "121"]],
                               "textures": [[f, "unit_models/x/%s.texture" % f, "unit_models/x/n.texture", ""]
                                            for f in facs],
                               "attach": [], "mounts": [], "torch": ["-1", "0", "0", "0", "0", "0", "0"]})
            if first:
                m.ci = {k: ["0", "0"] for k in ("lodvec", "lod", "texvec", "tex", "mountvec", "mount", "weapons",
                                                 "torch")}
            return m
        text = "22 serialization::archive 3 0 0 0 0 2 0 0 " + " ".join(MDB.ModelDB.dump_models(
            [model("knights", ["milan", "spain", "moors"], True), model("spears", ["milan", "spain"])]))
        mod = ModData(self.root)
        path = os.path.join(self.root, "unit_models", "battle_models.modeldb")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(text.encode("latin-1"))

        def recolour(fac, tex):
            plan = Plan(mod, "recolour", "recolour %s" % fac)
            db = MDB.ModelDB(text)
            for m in db.models:
                for r in m.textures:
                    if r[0] == fac:
                        r[1] = tex
            plan.binary(path, db.dump().encode("latin-1"))
            return keep(plan)
        parts = [recolour("milan", "unit_models/x/milan_own.texture"),
                 recolour("spain", "unit_models/x/spain_own.texture"),
                 recolour("moors", "unit_models/x/moors_own.texture")]
        clash = recolour("milan", "unit_models/x/milan_other.texture")   # kept too: milan a second way
        for plan in parts:
            rebased(plan).apply()
        db = MDB.load(path)
        got = {(m.name, r[0]): r[1] for m in db.models for r in m.textures}
        self.assertEqual(got[("knights", "milan")], "unit_models/x/milan_own.texture")
        self.assertEqual(got[("knights", "spain")], "unit_models/x/spain_own.texture")
        self.assertEqual(got[("knights", "moors")], "unit_models/x/moors_own.texture")
        self.assertEqual(got[("spears", "spain")], "unit_models/x/spain_own.texture")
        self.assertEqual(db.model("knights").factions(), ["milan", "spain", "moors"])     # the file's order kept
        self.assertEqual(MDB.ModelDB(db.dump()).dump(), db.dump())
        with self.assertRaises(ValueError) as e:
            rebased(clash)
        self.assertIn("knights's textures rows of milan", str(e.exception))

    def test_kept_changes_seen_before_the_write_and_never_kept_twice(self):
        """Keep for Apply (the user, 2026-10-10): pressed five times, the same change stood five times in the list;
        and the window did not show what it had kept (a Market added to many towns was not seen in them). The files
        as the kept parts will leave them are read in memory (plan.kept_texts - each part laid over the ones before
        it), and the same change kept again is not added again."""
        from campaign_editor.plan import Plan, kept_texts
        mod = ModData(self.root)
        path = mod.campaign_file("test", "descr_strat.txt")
        with open(path, "rb") as fh:
            disk = fh.read()
        first, second = Plan(mod, "a", "a"), Plan(mod, "b", "b")
        f = first.edit(path)
        f.raw.insert(0, f.make("; kept one"))
        g = second.edit(path)
        g.raw.append(g.make("; kept two"))
        got = kept_texts([first, second])[path].texts()
        self.assertEqual((got[0], got[-1]), ("; kept one", "; kept two"))
        self.assertEqual(got[1:-1], TextFile.from_bytes(path, disk).texts())
        with open(path, "rb") as fh:
            self.assertEqual(fh.read(), disk)                       # nothing written
        try:
            import tkinter  # noqa: F401
            from types import SimpleNamespace
            from campaign_editor.gui_util import keep_for_apply
        except Exception as e:                        # no tkinter (CI's python3): the rest not tested here
            self.skipTest("no window: %s" % e)
        parts = {}
        said = []
        app = SimpleNamespace(session_parts=lambda: parts, status=SimpleNamespace(set=said.append),
                              session_add=lambda k, label, plan, after=None: parts.__setitem__(k, {"plan": plan}))

        def make():
            p = Plan(mod, "t", "t")
            p.edit(path).raw.insert(0, p.edit(path).make("; market"))
            return p
        win = SimpleNamespace(app=app)
        for k in range(5):
            keep_for_apply(win, "towns:%d" % k, "towns", make)
        self.assertEqual(len(parts), 1)
        self.assertIn("kept already", said[-1])
        # the App itself (the map's right click > Delete the special place) has no .app: it is its own
        keep_for_apply(app, "towns:9", "towns", make)
        self.assertEqual(len(parts), 1)

    def test_closing_the_editor_when_a_command_is_already_gone(self):
        """Closing the editor once showed 'can't delete Tcl command' and then, while it reported that, a Windows box
        'application has been destroyed' (a tester, 0.32.0): a window keeps the names of its callbacks to delete them
        when it goes; a name deleted another way before (a call scheduled by one part and called off through
        another) made the close fail. A name already gone is skipped; every name a window keeps is a real one."""
        try:
            import tkinter as tk
            root = tk.Tk()
        except Exception as e:                        # no tkinter / no display (CI): the window is not tested here
            self.skipTest("no window: %s" % e)
        from campaign_editor.gui_util import unique_tcl_names
        unique_tcl_names()
        try:
            other = tk.Label(root)
            job = root.after(100000, lambda: None)    # scheduled by the main window...
            other.after_cancel(job)                   # ...called off through another part: Tcl deletes the command
            root.bind("<Configure>", lambda e: None, add="+")
            root.after(100000, lambda: None)
            have = set(root.tk.splitlist(root.tk.call("info", "commands")))
            kept = [n for n in root._tclCommands if n not in have]
            self.assertEqual(len(kept), 1)            # the cancelled call's name: the list keeps it, Tcl does not
            other.destroy()
        except BaseException:
            root.destroy()
            raise
        root.destroy()                                # before: TclError "can't delete Tcl command"
        self.assertIsNone(root._tclCommands)

    def test_no_internet_or_a_silent_service_never_hangs(self):
        """No internet, or a report service that takes the call and never answers: the editor gives up after its
        time and says it in plain words (the window runs these in a thread, so it never freezes)."""
        import socket
        from campaign_editor import report, settings
        saved = (settings._data, settings._path)
        tmp = tempfile.mkdtemp()
        settings._data, settings._path = {}, (lambda: os.path.join(tmp, "s.json"))
        silent = socket.socket()
        silent.bind(("127.0.0.1", 0))
        silent.listen(5)                                      # takes the call, never answers
        closed = socket.socket()
        closed.bind(("127.0.0.1", 0))
        port_closed = closed.getsockname()[1]
        closed.close()                                        # nobody there: like no internet
        try:
            settings.put("report_url", "http://127.0.0.1:%d/" % silent.getsockname()[1])
            t = time.time()
            with self.assertRaises(RuntimeError) as e:
                report.answers([{"id": "R-1", "issue": 1}], timeout=1)
            self.assertLess(time.time() - t, 10)
            self.assertIn("could not reach the report service", str(e.exception))
            settings.put("report_url", "http://127.0.0.1:%d/" % port_closed)
            with self.assertRaises(RuntimeError) as e:
                report.send_reply("R-1", 1, "hello", timeout=1)
            self.assertIn("is the internet on?", str(e.exception))
        finally:
            silent.close()
            settings._data, settings._path = saved

    def test_answers_to_my_reports(self):
        """The reporter cannot see the private reports repo: the editor keeps the numbers it sent (and finds older
        ones in its log), asks the relay for the author's answers, marks what is new until read, and sends the
        reporter's answer (with a zip of new pictures) to the same report."""
        import base64
        import http.server
        import json
        import threading
        from campaign_editor import report, settings
        saved = (settings._data, settings._path)
        tmp = tempfile.mkdtemp()
        settings._data, settings._path = {}, (lambda: os.path.join(tmp, "s.json"))
        calls = []

        class Relay(http.server.BaseHTTPRequestHandler):
            def do_POST(self):
                body = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
                calls.append((self.path, body))
                if self.path == "/answers":
                    out = {"answers": {"R-20261003-ABCDEF": {"issue": 7, "state": "open", "reason": "",
                                                             "messages": [{"from": "author", "text": "Which picture?",
                                                                           "at": "2026-10-03T10:00:00Z"}]}}}
                elif self.path == "/reply":
                    out = {"ok": True}
                else:
                    out = {"id": "R-20261003-ABCDEF", "issue": 7}
                self.send_response(200)
                self.end_headers()
                self.wfile.write(json.dumps(out).encode())

            def log_message(self, *a):
                pass
        srv = http.server.HTTPServer(("127.0.0.1", 0), Relay)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        try:
            settings.put("report_url", "http://127.0.0.1:%d/" % srv.server_port)
            zipdata = report.build_zip([], "x")
            rid, issue = report.send(zipdata, "Bug: x", "", {"editor": "t"}, full=True)
            self.assertEqual((rid, issue), ("R-20261003-ABCDEF", 7))
            report.remember_sent(rid, issue, "bug", "Bug: x")
            # an older report only in the log is found too; the same number is not doubled
            rows = report.sent_reports(["12:00 Report sent: R-20261001-0A1B2C (40 KB)",
                                        "Report sent: R-20261003-ABCDEF (1 KB)"])
            self.assertEqual([r["id"] for r in rows], ["R-20261003-ABCDEF", "R-20261001-0A1B2C"])
            self.assertEqual(rows[0]["issue"], 7)
            got = report.answers(rows, "t")
            self.assertEqual(calls[-1][0], "/answers")
            self.assertEqual(calls[-1][1]["reports"][0], {"id": rid, "issue": 7})
            self.assertEqual(got[rid]["messages"][0]["text"], "Which picture?")
            # new until it was shown; a later answer or a closing is new again
            self.assertEqual(report.news(got, settings.get("reports_seen")), [rid])
            report.mark_seen(got, [rid])
            self.assertEqual(report.news(got, settings.get("reports_seen")), [])
            got[rid]["state"], got[rid]["reason"] = "closed", "completed"
            self.assertEqual(report.news(got, settings.get("reports_seen")), [rid])
            self.assertEqual(report.state_words(got[rid]), "closed - fixed / done")
            self.assertEqual(report.state_words(None), "no answer yet")
            # the reporter's answer goes to the same report, with its files
            report.send_reply(rid, 7, "the unit cards of England", zipdata, "t")
            path, body = calls[-1]
            self.assertEqual((path, body["id"], body["issue"]), ("/reply", rid, 7))
            self.assertEqual(base64.b64decode(body["zip"]), zipdata)
        finally:
            srv.shutdown()
            srv.server_close()
            settings._data, settings._path = saved
            shutil.rmtree(tmp, ignore_errors=True)

